def load_env_file(path: Path) -> None:
    if not path.exists():
        return
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return
    pattern = re.compile(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$")
    for line in text.splitlines():
        if not line or line.lstrip().startswith("#"):
            continue
        match = pattern.match(line)
        if not match:
            continue
        key = match.group(1)
        existing = os.environ.get(key)
        if existing is not None and str(existing) != "":
            continue
        value = match.group(2).strip()
        if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
            value = value[1:-1]
        os.environ[key] = value
    return


def _parse_proxy_host_port(proxy_url: str) -> Tuple[str, Optional[int]]:
    if not proxy_url:
        return "", None
    if "://" not in proxy_url:
        proxy_url = f"http://{proxy_url}"
    try:
        parsed = urlparse(proxy_url)
    except Exception:
        return "", None
    return parsed.hostname or "", parsed.port


def _parse_port_list(value: Optional[str]) -> List[int]:
    if not value:
        return []
    ports: List[int] = []
    for part in re.split(r"[,\s]+", value):
        if not part:
            continue
        try:
            port = int(part)
        except (TypeError, ValueError):
            continue
        if port <= 0 or port > 65535:
            continue
        if port not in ports:
            ports.append(port)
    return ports


def _proxy_reachable(host: str, port: Optional[int], timeout: float = 0.5) -> bool:
    if not host or not port:
        return False
    try:
        with socket.create_connection((host, int(port)), timeout=timeout):
            return True
    except Exception:
        return False


def _collect_proxy_port_candidates(scutil_output: str = "") -> List[int]:
    ports: List[int] = []
    ports.extend(_parse_port_list(os.environ.get("PM_PROXY_PORTS")))
    proxy_url = os.environ.get("HTTPS_PROXY") or os.environ.get("HTTP_PROXY") or os.environ.get("ALL_PROXY")
    if proxy_url:
        _host, port = _parse_proxy_host_port(proxy_url)
        if port and port not in ports:
            ports.append(port)
    if scutil_output:
        for key in ("HTTPPort", "HTTPSPort", "SOCKSPort"):
            match = re.search(rf"^\s*{re.escape(key)}\s*:\s*(.+)$", scutil_output, flags=re.M)
            if not match:
                continue
            raw = match.group(1).strip()
            try:
                port = int(raw)
            except (TypeError, ValueError):
                continue
            if port > 0 and port <= 65535 and port not in ports:
                ports.append(port)
    return ports


def _build_node_env_with_proxy() -> Dict[str, str]:
    env = dict(os.environ)
    if "PM_CLOB_DIRECT_FIRST" not in env:
        env["PM_CLOB_DIRECT_FIRST"] = "1"
    force_direct = env.get("PM_CLOB_FORCE_DIRECT", "").strip().lower() in {"1", "true", "yes", "on"}
    if force_direct:
        for key in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy"):
            env.pop(key, None)
        env.pop("GLOBAL_AGENT_HTTP_PROXY", None)
        return env
    proxy_url = env.get("HTTPS_PROXY") or env.get("HTTP_PROXY") or env.get("ALL_PROXY")
    if proxy_url:
        host, port = _parse_proxy_host_port(proxy_url)
        if host in {"127.0.0.1", "localhost"} and port and not _proxy_reachable(host, port):
            output = ""
            if shutil.which("scutil"):
                try:
                    output = subprocess.check_output(["scutil", "--proxy"], text=True)
                except Exception:
                    output = ""
            candidates = _collect_proxy_port_candidates(output)
            for candidate in candidates:
                if candidate == port:
                    continue
                if _proxy_reachable(host, candidate):
                    proxy_value = f"http://{host}:{candidate}"
                    env["HTTP_PROXY"] = proxy_value
                    env["HTTPS_PROXY"] = proxy_value
                    env["GLOBAL_AGENT_HTTP_PROXY"] = proxy_value
                    return env
        return env
    if not shutil.which("scutil"):
        return env
    try:
        output = subprocess.check_output(["scutil", "--proxy"], text=True)
    except Exception:
        return env
    http_enable = re.search(r"^\s*HTTPEnable\s*:\s*(\d+)", output, flags=re.M)
    https_enable = re.search(r"^\s*HTTPSEnable\s*:\s*(\d+)", output, flags=re.M)
    http_host = ""
    http_port = ""
    https_host = ""
    https_port = ""
    if http_enable and http_enable.group(1) == "1":
        match = re.search(r"^\s*HTTPProxy\s*:\s*(.+)$", output, flags=re.M)
        if match:
            http_host = match.group(1).strip()
        match = re.search(r"^\s*HTTPPort\s*:\s*(.+)$", output, flags=re.M)
        if match:
            http_port = match.group(1).strip()
    if https_enable and https_enable.group(1) == "1":
        match = re.search(r"^\s*HTTPSProxy\s*:\s*(.+)$", output, flags=re.M)
        if match:
            https_host = match.group(1).strip()
        match = re.search(r"^\s*HTTPSPort\s*:\s*(.+)$", output, flags=re.M)
        if match:
            https_port = match.group(1).strip()
    if http_host and http_port:
        env["HTTP_PROXY"] = f"http://{http_host}:{http_port}"
    if https_host and https_port:
        env["HTTPS_PROXY"] = f"http://{https_host}:{https_port}"
    return env


