def _auto_trade_runtime_lock_stale_sec() -> int:
    # If the UI server crashes mid-run, scan jobs can clean up the stale lock after this TTL.
    raw = str(os.environ.get("PM_AUTO_TRADE_RUNTIME_LOCK_STALE_SEC", "1800") or "").strip()
    try:
        val = int(float(raw))
    except Exception:
        val = 1800
    return max(60, min(val, 24 * 3600))


def _auto_trade_runtime_lock_acquire(run_date: str, *, note: str = "") -> bool:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    ttl = _auto_trade_runtime_lock_stale_sec()
    if AUTO_TRADE_RUNTIME_LOCK_DIR.exists():
        # Best-effort stale cleanup.
        try:
            meta = {}
            if AUTO_TRADE_RUNTIME_LOCK_META.exists():
                meta = json.loads(AUTO_TRADE_RUNTIME_LOCK_META.read_text(encoding="utf-8"))
            started_at = str(meta.get("started_at") or "")
            dt = parse_any_ts(started_at) if started_at else None
            if dt is not None:
                age = (datetime.now().astimezone() - dt).total_seconds()
                if age >= ttl:
                    shutil.rmtree(AUTO_TRADE_RUNTIME_LOCK_DIR, ignore_errors=True)
        except Exception:
            pass
    if AUTO_TRADE_RUNTIME_LOCK_DIR.exists():
        return False
    try:
        AUTO_TRADE_RUNTIME_LOCK_DIR.mkdir(parents=True, exist_ok=False)
    except OSError:
        return False
    meta = {
        "started_at": now_text(),
        "pid": int(os.getpid()),
        "run_date": str(run_date or ""),
        "note": str(note or ""),
    }
    try:
        AUTO_TRADE_RUNTIME_LOCK_META.write_text(json.dumps(meta, ensure_ascii=True), encoding="utf-8")
    except OSError:
        pass
    return True


