def _scan_alerts_paused() -> bool:
    return bool(SCAN_ALERTS_PAUSED)


def _service_issue_suppressed_when_scan_paused(issue: Dict[str, Any]) -> bool:
    if not isinstance(issue, dict):
        return False
    code = str(issue.get("code") or "").strip()
    if code in _SCAN_ALERTS_PAUSED_SERVICE_CODES:
        return True
    if code == "launchd_nonzero_status":
        evidence = issue.get("evidence")
        label = str((evidence or {}).get("label") if isinstance(evidence, dict) else "").strip()
        if label in _SCAN_ALERTS_PAUSED_LABELS:
            return True
    return False


def _health_issue_suppressed_when_scan_paused(issue: Dict[str, Any]) -> bool:
    if not isinstance(issue, dict):
        return False
    code = str(issue.get("code") or "").strip()
    if code in _SCAN_ALERTS_PAUSED_SERVICE_CODES or code in _SCAN_ALERTS_PAUSED_HEALTH_CODES:
        return True
    if code == "launchd_nonzero_status":
        evidence = issue.get("evidence")
        label = str((evidence or {}).get("label") if isinstance(evidence, dict) else "").strip()
        if label in _SCAN_ALERTS_PAUSED_LABELS:
            return True
    return False


def _default_ui_max_concurrent_requests() -> int:
    # Keep headroom for DB/network/log fds during bursty polling.
    fallback = 64
    try:
        soft, _hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except Exception:
        return fallback
    try:
        soft_int = int(soft)
    except Exception:
        return fallback
    if soft_int <= 0:
        return fallback
    # Scale with fd limit to avoid frequent server_busy on busy dashboards.
    return max(24, min(128, soft_int // 8))


