def load_html() -> str:
    html = HTML_PATH.read_text(encoding="utf-8")
    try:
        payload = auto_trade_config_defaults()
        payload.update(load_auto_trade_config())
        bootstrap = json.dumps(payload, ensure_ascii=True, separators=(",", ":"))
    except Exception:
        return html
    injection = f"<script>window.__AUTO_TRADE_BOOTSTRAP__={bootstrap};</script>"
    marker = "</head>"
    if marker in html:
        return html.replace(marker, f"{injection}\n{marker}", 1)
    return f"{injection}\n{html}"


