def get_fd_usage() -> Dict[str, Any]:
    """Return current process file descriptor usage."""
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except (ValueError, OSError):
        soft, hard = None, None
    fd_error = ""
    try:
        fd_count = len(os.listdir("/dev/fd"))
    except OSError as exc:
        fd_count = None
        fd_error = str(exc)
    ratio = None
    if isinstance(fd_count, int) and isinstance(soft, int) and soft > 0:
        ratio = fd_count / soft
    elif "Errno 24" in fd_error or "Too many open files" in fd_error:
        ratio = 1.0
    return {
        "count": fd_count,
        "soft": soft,
        "hard": hard,
        "ratio": ratio,
        "error": fd_error,
    }


_FD_PRESSURE_LOG_TS = 0.0
_ERRNO24_ISSUE_FIRST_SEEN: Dict[str, float] = {}
_UI_FD_BUSY_CACHE_LOCK = threading.Lock()
_UI_FD_BUSY_CACHE: Dict[str, Any] = {"at": 0.0, "busy": False, "usage": None}


def _log_fd_pressure(fd_usage: Optional[Dict[str, Any]]) -> None:
    """Log fd pressure with throttling to avoid log spam."""
    if not isinstance(fd_usage, dict):
        return
    ratio = fd_usage.get("ratio")
    if not isinstance(ratio, float) or ratio < 0.7:
        return
    global _FD_PRESSURE_LOG_TS
    now_ts = time.time()
    if _FD_PRESSURE_LOG_TS and (now_ts - _FD_PRESSURE_LOG_TS) < 120:
        return
    _FD_PRESSURE_LOG_TS = now_ts
    count = fd_usage.get("count")
    soft = fd_usage.get("soft")
    hard = fd_usage.get("hard")
    try:
        print(f"[fd_pressure] count={count} soft={soft} hard={hard} ratio={ratio:.3f}")
    except Exception:
        pass


def _fd_ratio(fd_count: Any, fd_soft: Any) -> Optional[float]:
    try:
        count = int(fd_count)
        soft = int(fd_soft)
    except (TypeError, ValueError):
        return None
    if count < 0 or soft <= 0:
        return None
    return float(count) / float(soft)


def _ui_fd_pressure_busy() -> bool:
    if UI_BUSY_FD_RATIO <= 0:
        return False
    now_mono = time.monotonic()
    with _UI_FD_BUSY_CACHE_LOCK:
        cached_at = float(_UI_FD_BUSY_CACHE.get("at") or 0.0)
        if (now_mono - cached_at) <= UI_BUSY_FD_SAMPLE_CACHE_SEC:
            return bool(_UI_FD_BUSY_CACHE.get("busy"))
    usage = get_fd_usage()
    ratio = usage.get("ratio")
    busy = isinstance(ratio, float) and ratio >= UI_BUSY_FD_RATIO
    if busy:
        _log_fd_pressure(usage)
    with _UI_FD_BUSY_CACHE_LOCK:
        _UI_FD_BUSY_CACHE["at"] = now_mono
        _UI_FD_BUSY_CACHE["busy"] = bool(busy)
        _UI_FD_BUSY_CACHE["usage"] = dict(usage)
    return bool(busy)


def _to_float_safe(value: Any) -> Optional[float]:
    try:
        num = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(num):
        return None
    return num


def _pid_fd_count(pid: int) -> Optional[int]:
    if not isinstance(pid, int) or pid <= 0:
        return None
    if not _LSOF_BIN:
        return None
    try:
        res = subprocess.run(
            [_LSOF_BIN, "-n", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=FD_GUARD_LSOF_TIMEOUT_SEC,
            check=False,
        )
    except Exception:
        return None
    out = str(res.stdout or "")
    if not out:
        return None
    lines = [ln for ln in out.splitlines() if ln.strip()]
    if not lines:
        return None
    if lines and lines[0].lstrip().startswith("COMMAND"):
        lines = lines[1:]
    return max(0, len(lines))


def _fd_guard_sample_by_label(launch_map: Dict[str, Any], labels: Iterable[str]) -> Dict[str, Dict[str, Any]]:
    now_mono = time.monotonic()
    cache = _FD_GUARD_SAMPLE_CACHE
    cache_age = now_mono - float(cache.get("ts") or 0.0)
    cached_rows = cache.get("rows") if cache_age >= 0 and cache_age < FD_GUARD_SAMPLE_CACHE_SEC else {}
    if not isinstance(cached_rows, dict):
        cached_rows = {}
    samples: Dict[str, Dict[str, Any]] = {}
    refreshed = False
    for label in labels:
        row = launch_map.get(label) if isinstance(launch_map, dict) else None
        pid = row.get("pid") if isinstance(row, dict) else None
        if not isinstance(pid, int) or pid <= 0:
            continue
        cached = cached_rows.get(label) if isinstance(cached_rows, dict) else None
        if (
            isinstance(cached, dict)
            and int(cached.get("pid") or 0) == pid
            and isinstance(cached.get("fd_count"), int)
        ):
            samples[label] = dict(cached)
            continue
        fd_count = _pid_fd_count(pid)
        samples[label] = {
            "label": label,
            "pid": pid,
            "fd_count": fd_count,
            "sampled_at": utc_now_iso(),
        }
        refreshed = True
    if refreshed or not isinstance(cached_rows, dict) or cache_age >= FD_GUARD_SAMPLE_CACHE_SEC:
        cache["ts"] = now_mono
        cache["rows"] = dict(samples)
    return samples


def _fd_degrade_control_path() -> Path:
    return DATA_DIR / "fd_degrade_pause_noncritical.json"


def _write_json_atomic(path: Path, payload: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, ensure_ascii=True), encoding="utf-8")
    tmp.replace(path)


def _read_system_pause_state() -> Dict[str, Any]:
    try:
        raw = SYSTEM_PAUSE_STATE_PATH.read_text(encoding="utf-8")
    except FileNotFoundError:
        return {}
    except OSError:
        return {}
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def _update_fd_degrade(fd_guard: Dict[str, Any]) -> Dict[str, Any]:
    report: Dict[str, Any] = {
        "enabled": bool(FD_DEGRADE_ENABLED),
        "active": False,
        "trigger_ratio": float(FD_DEGRADE_TRIGGER_RATIO),
        "trigger_sec": int(FD_DEGRADE_TRIGGER_SEC),
        "hold_sec": int(FD_DEGRADE_HOLD_SEC),
        "high_since": "",
        "active_until": "",
        "max_ratio": None,
        "control_path": str(_fd_degrade_control_path()),
        "issues": [],
        "reasons": [],
    }
    path = _fd_degrade_control_path()
    if not FD_DEGRADE_ENABLED:
        try:
            path.unlink()
        except OSError:
            pass
        return report

    ratios: List[float] = []
    g_ratio = _to_float_safe((fd_guard.get("global") or {}).get("ratio")) if isinstance(fd_guard, dict) else None
    if g_ratio is not None:
        ratios.append(g_ratio)
    for row in list((fd_guard.get("rows") or []) if isinstance(fd_guard, dict) else []):
        if not isinstance(row, dict):
            continue
        r = _to_float_safe(row.get("fd_ratio"))
        if r is not None:
            ratios.append(r)
    max_ratio = max(ratios) if ratios else None
    report["max_ratio"] = max_ratio
    now_ts = time.time()
    active = False
    high_since_ts = 0.0
    active_until_ts = 0.0
    with _FD_DEGRADE_STATE_LOCK:
        st = _FD_DEGRADE_STATE
        high_now = max_ratio is not None and max_ratio >= FD_DEGRADE_TRIGGER_RATIO
        if high_now:
            if float(st.get("high_since") or 0.0) <= 0:
                st["high_since"] = now_ts
            sustained = max(0.0, now_ts - float(st.get("high_since") or now_ts))
            if sustained >= float(FD_DEGRADE_TRIGGER_SEC):
                st["active_until"] = max(float(st.get("active_until") or 0.0), now_ts + float(FD_DEGRADE_HOLD_SEC))
            st["last_ratio"] = max_ratio
        else:
            st["high_since"] = 0.0
            if float(st.get("active_until") or 0.0) <= now_ts:
                st["active_until"] = 0.0
        high_since_ts = float(st.get("high_since") or 0.0)
        active_until_ts = float(st.get("active_until") or 0.0)
        active = active_until_ts > now_ts

    if high_since_ts > 0:
        report["high_since"] = datetime.fromtimestamp(high_since_ts, tz=timezone.utc).isoformat(timespec="seconds")
    if active_until_ts > 0:
        report["active_until"] = datetime.fromtimestamp(active_until_ts, tz=timezone.utc).isoformat(timespec="seconds")
    report["active"] = bool(active)

    if active:
        payload = {
            "active": True,
            "reason": "fd_pressure_sustained",
            "trigger_ratio": FD_DEGRADE_TRIGGER_RATIO,
            "trigger_sec": FD_DEGRADE_TRIGGER_SEC,
            "hold_sec": FD_DEGRADE_HOLD_SEC,
            "max_ratio": max_ratio,
            "high_since": report["high_since"],
            "active_until": report["active_until"],
            "updated_at": utc_now_iso(),
        }
        try:
            _write_json_atomic(path, payload)
        except OSError:
            pass
        report["issues"].append(
            {
                "code": "fd_degrade_noncritical_active",
                "severity": "warn",
                "message": "FD 压力持续过高：已暂停非关键扫描任务",
                "evidence": payload,
            }
        )
        report["reasons"].append("FD 压力过高，已暂停非关键扫描")
    else:
        try:
            path.unlink()
        except OSError:
            pass
    return report


def _evaluate_fd_guard(
    *,
    launch_map: Dict[str, Any],
    fd_usage: Dict[str, Any],
    launchctl_bin: str,
) -> Dict[str, Any]:
    report: Dict[str, Any] = {
        "enabled": bool(FD_GUARD_ENABLED),
        "soft_warn_ratio": float(FD_SOFT_WARN_RATIO),
        "restart_ratio": float(FD_RESTART_RATIO),
        "restart_min_consec": int(FD_RESTART_MIN_CONSEC),
        "restart_cooldown_sec": int(FD_RESTART_COOLDOWN_SEC),
        "labels": list(FD_GUARD_LABELS),
        "rows": [],
        "restarts": [],
        "issues": [],
        "reasons": [],
    }
    issues: List[Dict[str, Any]] = []
    reasons: List[str] = []
    soft_limit = fd_usage.get("soft") if isinstance(fd_usage, dict) else None
    global_count = fd_usage.get("count") if isinstance(fd_usage, dict) else None
    global_ratio = _fd_ratio(global_count, soft_limit)
    report["global"] = {
        "count": global_count,
        "soft": soft_limit,
        "ratio": global_ratio,
    }
    if global_ratio is not None and global_ratio >= FD_SOFT_WARN_RATIO:
        issues.append(
            {
                "code": "fd_pressure",
                "severity": "warn",
                "message": "文件描述符接近上限（可能触发 Errno 24）",
                "evidence": {
                    "fd_count": global_count,
                    "fd_soft": soft_limit,
                    "fd_ratio": global_ratio,
                    "warn_ratio": FD_SOFT_WARN_RATIO,
                },
            }
        )
        _log_fd_pressure(fd_usage)
    if not FD_GUARD_ENABLED:
        report["issues"] = issues
        report["reasons"] = reasons
        return report
    if not _LSOF_BIN and FD_GUARD_LABELS:
        issues.append(
            {
                "code": "fd_guard_lsof_missing",
                "severity": "warn",
                "message": "FD 守护未启用按进程采样（缺少 lsof）",
                "evidence": {"labels": list(FD_GUARD_LABELS)},
            }
        )
        report["issues"] = issues
        report["reasons"] = reasons
        return report

    label_samples = _fd_guard_sample_by_label(launch_map, FD_GUARD_LABELS)
    now_ts = time.time()
    restart_plans: List[Dict[str, Any]] = []
    skip_self_rows: List[Dict[str, Any]] = []
    cooldown_rows: List[Dict[str, Any]] = []
    with _FD_GUARD_STATE_LOCK:
        state_map = _FD_GUARD_STATE.setdefault("labels", {})
        if not isinstance(state_map, dict):
            state_map = {}
            _FD_GUARD_STATE["labels"] = state_map
        for label in FD_GUARD_LABELS:
            row = launch_map.get(label) if isinstance(launch_map, dict) else None
            pid = row.get("pid") if isinstance(row, dict) else None
            fd_count = None
            sampled_at = ""
            sample = label_samples.get(label)
            if isinstance(sample, dict):
                fd_count = sample.get("fd_count")
                sampled_at = str(sample.get("sampled_at") or "")
            ratio = _fd_ratio(fd_count, soft_limit)
            label_state = state_map.setdefault(label, {"consec": 0, "last_restart_at": 0.0})
            if not isinstance(pid, int) or pid <= 0:
                label_state["consec"] = 0
                report["rows"].append(
                    {
                        "label": label,
                        "pid": None,
                        "fd_count": None,
                        "fd_ratio": None,
                        "consec": 0,
                        "restart_at": "",
                        "sampled_at": sampled_at,
                    }
                )
                continue
            if ratio is not None and ratio >= FD_SOFT_WARN_RATIO:
                issues.append(
                    {
                        "code": "fd_pressure_service",
                        "severity": "warn",
                        "message": f"服务 FD 压力偏高：{label}",
                        "evidence": {
                            "label": label,
                            "pid": pid,
                            "fd_count": fd_count,
                            "fd_soft": soft_limit,
                            "fd_ratio": ratio,
                            "warn_ratio": FD_SOFT_WARN_RATIO,
                        },
                    }
                )
            if ratio is not None and ratio >= FD_RESTART_RATIO:
                label_state["consec"] = int(label_state.get("consec") or 0) + 1
            else:
                label_state["consec"] = 0
            consec = int(label_state.get("consec") or 0)
            last_restart_at = float(label_state.get("last_restart_at") or 0.0)
            restart_at_text = (
                datetime.fromtimestamp(last_restart_at, tz=timezone.utc).isoformat(timespec="seconds")
                if last_restart_at > 0
                else ""
            )
            report["rows"].append(
                {
                    "label": label,
                    "pid": pid,
                    "fd_count": fd_count,
                    "fd_ratio": ratio,
                    "consec": consec,
                    "restart_at": restart_at_text,
                    "sampled_at": sampled_at,
                }
            )
            if ratio is None or ratio < FD_RESTART_RATIO or consec < FD_RESTART_MIN_CONSEC:
                continue
            cool_down_left = max(0.0, FD_RESTART_COOLDOWN_SEC - (now_ts - last_restart_at))
            if cool_down_left > 0:
                cooldown_rows.append(
                    {
                        "label": label,
                        "pid": pid,
                        "fd_count": fd_count,
                        "fd_ratio": ratio,
                        "consec": consec,
                        "cooldown_left_sec": int(round(cool_down_left)),
                    }
                )
                continue
            if pid == os.getpid():
                label_state["consec"] = 0
                skip_self_rows.append(
                    {
                        "label": label,
                        "pid": pid,
                        "fd_count": fd_count,
                        "fd_ratio": ratio,
                    }
                )
                continue
            label_state["last_restart_at"] = now_ts
            label_state["consec"] = 0
            restart_plans.append(
                {
                    "label": label,
                    "pid": pid,
                    "fd_count": fd_count,
                    "fd_ratio": ratio,
                    "target": f"gui/{os.getuid()}/{label}",
                }
            )

    for row in cooldown_rows:
        issues.append(
            {
                "code": "fd_auto_restart_cooldown",
                "severity": "warn",
                "message": f"FD 守护命中重启阈值，但仍在冷却：{row.get('label')}",
                "evidence": row,
            }
        )
    for row in skip_self_rows:
        issues.append(
            {
                "code": "fd_auto_restart_skipped_self",
                "severity": "warn",
                "message": f"FD 守护跳过自重启（当前请求进程）：{row.get('label')}",
                "evidence": row,
            }
        )

    for plan in restart_plans:
        cmd = [launchctl_bin, "kickstart", "-k", str(plan.get("target") or "")]
        kick = _launchctl_run(cmd, timeout_sec=8)
        restart_row = {**plan, "kickstart": kick, "at": utc_now_iso()}
        report["restarts"].append(restart_row)
        if bool(kick.get("ok")):
            msg = f"FD 守护已自动重启：{plan.get('label')}"
            issues.append(
                {
                    "code": "fd_auto_restart",
                    "severity": "warn",
                    "message": msg,
                    "evidence": restart_row,
                }
            )
            reasons.append(msg)
        else:
            issues.append(
                {
                    "code": "fd_auto_restart_failed",
                    "severity": "warn",
                    "message": f"FD 守护重启失败：{plan.get('label')}",
                    "evidence": restart_row,
                }
            )
    report["issues"] = issues
    report["reasons"] = reasons
    return report


def _issue_contains_errno24(issue: Dict[str, Any]) -> bool:
    if not isinstance(issue, dict):
        return False
    msg = str(issue.get("message") or "")
    if "Errno 24" in msg or "Too many open files" in msg:
        return True
    evidence = issue.get("evidence")
    if isinstance(evidence, dict):
        err = str(evidence.get("error") or "")
        if "Errno 24" in err or "Too many open files" in err:
            return True
    return False


def _suppress_errno24_issues(issues: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    now_ts = time.time()
    out: List[Dict[str, Any]] = []
    for it in issues or []:
        if not _issue_contains_errno24(it):
            key = f"{it.get('group')}:{it.get('code')}"
            _ERRNO24_ISSUE_FIRST_SEEN.pop(key, None)
            out.append(it)
            continue
        key = f"{it.get('group')}:{it.get('code')}"
        first_seen = _ERRNO24_ISSUE_FIRST_SEEN.get(key)
        if first_seen is None:
            _ERRNO24_ISSUE_FIRST_SEEN[key] = now_ts
            out.append(it)
            continue
        if (now_ts - first_seen) >= ERRNO24_CLEAR_SEC:
            # Suppress after timeout to avoid persistent noise.
            continue
        out.append(it)
    return out


def write_trade_sync_status(
    ok: bool,
    error: str = "",
    detail: str = "",
    is_502: bool = False,
    extra: Optional[Dict[str, Any]] = None,
) -> None:
    status = load_trade_sync_status()
    now = utc_now_iso()
    status["last_attempt_at"] = now
    status["updated_at"] = now
    status["ok"] = bool(ok)
    if ok:
        status["last_ok_at"] = now
        status["last_error"] = ""
        status["last_error_detail"] = ""
        status["last_error_is_502"] = False
    else:
        status["last_error"] = str(error or "")
        status["last_error_detail"] = str(detail or "")
        status["last_error_is_502"] = bool(is_502)
    if extra:
        status.update(extra)
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        TRADE_SYNC_STATUS_PATH.write_text(json.dumps(status, ensure_ascii=True), encoding="utf-8")
    except OSError:
        pass


def _is_fetch_trades_timeout_text(error: str, detail: str) -> bool:
    blob = f"{error or ''} {detail or ''}".lower()
    has_timeout = any(token in blob for token in ("timed out", "timeout", "etimedout"))
    if not has_timeout:
        return False
    return any(token in blob for token in ("fetch-trades", "fetch trades", "trade sync", "exec_failed"))


def build_trade_sync_watchdog(status: Dict[str, Any]) -> Dict[str, Any]:
    row = status if isinstance(status, dict) else {}
    window_sec = int(TRADE_SYNC_TIMEOUT_ALERT_SEC)
    now_ms = int(time.time() * 1000)

    def _to_int(value: Any) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return 0

    until_ms = _to_int(row.get("fetch_trades_timeout_until"))
    last_at = str(row.get("fetch_trades_timeout_at") or row.get("last_attempt_at") or row.get("updated_at") or "")
    last_ok_at = str(row.get("last_ok_at") or "")
    error_text = str(row.get("fetch_trades_timeout_error") or row.get("last_error") or "")
    detail_text = str(row.get("fetch_trades_timeout_detail") or row.get("last_error_detail") or "")

    last_ok_dt = parse_iso_ts(last_ok_at) if last_ok_at else None
    if last_ok_dt is not None and last_ok_dt.tzinfo is None:
        last_ok_dt = last_ok_dt.replace(tzinfo=timezone.utc)
    last_dt = parse_iso_ts(last_at)
    if last_dt is not None and last_dt.tzinfo is None:
        last_dt = last_dt.replace(tzinfo=timezone.utc)
    if last_dt is not None and last_ok_dt is not None and last_ok_dt >= last_dt:
        until_ms = 0
        error_text = ""
        detail_text = ""
    if until_ms <= 0 and _is_fetch_trades_timeout_text(error_text, detail_text):
        if last_dt is not None:
            until_ms = int(last_dt.timestamp() * 1000) + window_sec * 1000

    if until_ms > 0 and until_ms <= now_ms:
        until_ms = 0

    active = until_ms > now_ms
    remaining_sec = int(max(0, (until_ms - now_ms + 999) // 1000)) if until_ms > 0 else 0
    until_at = ""
    if until_ms > 0:
        until_at = datetime.fromtimestamp(until_ms / 1000.0, tz=timezone.utc).isoformat(timespec="seconds")

    return {
        "fetch_trades_timeout_recent": active,
        "window_sec": window_sec,
        "remaining_sec": remaining_sec,
        "until_at": until_at,
        "last_at": last_at,
        "error": error_text,
        "detail": detail_text,
    }


def _migrate_legacy_edge_keys(data: Dict[str, Any]) -> bool:
    migrated = False
    legacy_edge_keys = {
        "entry_edge_min": "entry_signal_edge_min",
        "entry_edge_min_consecutive": "entry_signal_edge_min_consecutive",
        "entry_require_edge_min": "entry_require_signal_edge",
        "entry_yes_top_edge_min": "entry_yes_top_signal_edge_min",
        "entry_yes_top_price_take_edge_min": "entry_yes_top_price_take_signal_edge_min",
        "entry_trade_edge_min": "entry_signal_edge_min",
        "entry_trade_edge_min_consecutive": "entry_signal_edge_min_consecutive",
        "entry_require_trade_edge": "entry_require_signal_edge",
        "entry_yes_top_trade_edge_min": "entry_yes_top_signal_edge_min",
        "entry_yes_top_price_take_trade_edge_min": "entry_yes_top_price_take_signal_edge_min",
    }
    for legacy_key, new_key in legacy_edge_keys.items():
        if new_key not in data and legacy_key in data:
            data[new_key] = data.get(legacy_key)
            migrated = True
        if legacy_key in data:
            data.pop(legacy_key, None)
            migrated = True
    legacy_weather_keys = {
        "weather_spread_max": "entry_spread_max",
        "weather_reverse_confirm_count": "exit_lag_consecutive",
        "weather_token_cooldown_sec": "reentry_cooldown_sec",
        "weather_min_hold_sec": "min_hold_sec",
    }
    for legacy_key, new_key in legacy_weather_keys.items():
        if new_key not in data and legacy_key in data:
            data[new_key] = data.get(legacy_key)
            migrated = True
        if legacy_key in data:
            data.pop(legacy_key, None)
            migrated = True
    return migrated


_ENTRY_ONLY_REALIZABLE_SOFT_FLAGS = {
    "entry_require_signal_edge",
    "entry_require_edge_band",
    "entry_require_edge_confidence",
    "entry_require_edge_bias",
    "entry_apply_edge_bias",
    "entry_require_q_range",
    "entry_require_q_band",
    "entry_require_ask_range",
    "entry_require_no_ask_range",
    "entry_require_yes_overprice",
    "entry_block_no_by_yes_q",
    "entry_require_spread_max",
    "entry_require_ask_le_q_min",
    "entry_require_auto_max_ask",
    "entry_skip_top_label",
    "entry_lag_enabled",
    "entry_lag_limit_enabled",
    "entry_require_depth",
}


def _normalize_entry_only_realizable_config(
    config: Dict[str, Any],
    *,
    entry_only_realizable: Optional[bool] = None,
) -> Dict[str, Any]:
    if not isinstance(config, dict):
        return config
    if entry_only_realizable is None:
        if "entry_only_realizable" in config:
            entry_only_realizable = bool(config.get("entry_only_realizable"))
        else:
            entry_only_realizable = _env_bool("PM_AUTO_TRADE_ENTRY_ONLY_REALIZABLE", True)
    if not entry_only_realizable:
        return config
    config["entry_only_realizable"] = True
    for key in _ENTRY_ONLY_REALIZABLE_SOFT_FLAGS:
        if key in config:
            config[key] = False
    if "entry_min_outcome_volume" in config:
        config["entry_min_outcome_volume"] = 0.0
    if "entry_outcome_volume_gate_mode" in config:
        config["entry_outcome_volume_gate_mode"] = "off"
    if "entry_outcome_volume_refresh_sec" in config:
        config["entry_outcome_volume_refresh_sec"] = 0.0
    if "entry_outcome_volume_refresh_missing_only" in config:
        config["entry_outcome_volume_refresh_missing_only"] = False
    return config


def load_auto_trade_config() -> Dict[str, Any]:
    if not AUTO_TRADE_CONFIG_PATH.exists():
        return {}
    try:
        data = json.loads(AUTO_TRADE_CONFIG_PATH.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    if not isinstance(data, dict):
        return {}
    migrated = _migrate_legacy_edge_keys(data)
    raw_consensus = data.get("entry_yes_top_model_consensus_min")
    if raw_consensus is not None:
        consensus_val = to_float(raw_consensus)
        if consensus_val is None:
            fixed = 2
        else:
            fixed = int(round(consensus_val))
            if fixed < 2:
                fixed = 2
        if raw_consensus != fixed:
            data["entry_yes_top_model_consensus_min"] = fixed
            migrated = True
    defaults = auto_trade_config_defaults()
    for key in (
        "entry_outcome_volume_gate_mode",
        "entry_outcome_volume_refresh_sec",
        "entry_outcome_volume_refresh_missing_only",
    ):
        if key in data:
            continue
        if key not in defaults:
            continue
        data[key] = defaults.get(key)
        migrated = True
    if migrated:
        try:
            save_auto_trade_config(data)
        except OSError:
            pass
    return data


def save_auto_trade_config(payload: Dict[str, Any]) -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    AUTO_TRADE_CONFIG_PATH.write_text(json.dumps(payload, ensure_ascii=True), encoding="utf-8")


def load_ab_entry_results() -> Dict[str, Any]:
    with AB_ENTRY_RESULTS_LOCK:
        if not AB_ENTRY_RESULTS_PATH.exists():
            return {"ok": False, "error": "missing"}
        try:
            raw = AB_ENTRY_RESULTS_PATH.read_text(encoding="utf-8")
        except OSError:
            return {"ok": False, "error": "read_failed"}
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            return {"ok": False, "error": "invalid_json"}
        if not isinstance(data, dict):
            return {"ok": False, "error": "invalid_format"}
        if "updated_at" not in data:
            try:
                mtime = datetime.fromtimestamp(AB_ENTRY_RESULTS_PATH.stat().st_mtime)
                data["updated_at"] = mtime.isoformat(timespec="seconds")
            except OSError:
                pass
        data.setdefault("ok", True)
        return data


