def load_auto_trade_presets_state() -> Dict[str, Any]:
    if not AUTO_TRADE_PRESETS_PATH.exists():
        return {}
    try:
        data = json.loads(AUTO_TRADE_PRESETS_PATH.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def save_auto_trade_presets_state(state: Dict[str, Any]) -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    AUTO_TRADE_PRESETS_PATH.write_text(json.dumps(state, ensure_ascii=True), encoding="utf-8")


def _preset_id_from_custom(custom_id: str) -> str:
    return f"custom:{custom_id}"


def _custom_id_from_preset_id(preset_id: str) -> Optional[str]:
    if not preset_id or not preset_id.startswith("custom:"):
        return None
    return preset_id.split(":", 1)[1].strip() or None


def _normalize_preset_name(name: str) -> str:
    return str(name or "").strip()[:80]


def _unique_preset_name(name: str, existing: List[str]) -> str:
    base = _normalize_preset_name(name) or "自定义方案"
    if base not in existing:
        return base
    idx = 2
    while True:
        candidate = f"{base} {idx}"
        if candidate not in existing:
            return candidate
        idx += 1


def build_auto_trade_presets() -> Dict[str, Any]:
    defaults = auto_trade_config_defaults()
    overrides = _auto_trade_preset_overrides()
    state = load_auto_trade_presets_state()
    presets_migrated = False
    custom_map = state.get("custom") if isinstance(state.get("custom"), dict) else {}
    presets: List[Dict[str, Any]] = [
        {
            "id": "default",
            "name": "默认",
            "type": "builtin",
            "config": defaults,
        },
        {
            "id": "conservative",
            "name": "保守型",
            "type": "builtin",
            "config": {**defaults, **overrides.get("conservative", {})},
        },
        {
            "id": "aggressive",
            "name": "进攻型",
            "type": "builtin",
            "config": {**defaults, **overrides.get("aggressive", {})},
        },
    ]
    custom_entries: List[Dict[str, Any]] = []
    for cid, entry in custom_map.items():
        if not isinstance(entry, dict):
            continue
        config = entry.get("config")
        if not isinstance(config, dict):
            continue
        config = dict(config)
        if _migrate_legacy_edge_keys(config):
            entry["config"] = config
            presets_migrated = True
        name = _normalize_preset_name(entry.get("name") or f"自定义 {cid[:6]}")
        custom_entries.append(
            {
                "id": _preset_id_from_custom(cid),
                "name": name,
                "type": "custom",
                "config": {**defaults, **config},
                "updated_at": entry.get("updated_at") or "",
            }
        )
    custom_entries.sort(key=lambda row: row.get("updated_at") or "", reverse=True)
    presets.extend(custom_entries)
    if presets_migrated:
        try:
            save_auto_trade_presets_state(state)
        except OSError:
            pass
    active = str(state.get("active") or "")
    preset_ids = {p["id"] for p in presets}
    if active not in preset_ids:
        active = ""
    return {"ok": True, "presets": presets, "active": active}


def auto_trade_config_defaults() -> Dict[str, Any]:
    def env_float(key: str, fallback: float) -> float:
        raw = os.environ.get(key)
        try:
            val = float(raw) if raw is not None else None
        except (TypeError, ValueError):
            val = None
        if val is None or not math.isfinite(val):
            return fallback
        return val

    def env_bool(key: str, fallback: bool) -> bool:
        raw = os.environ.get(key)
        if raw is None:
            return fallback
        return str(raw).strip().lower() in {"1", "true", "yes", "on"}

    def env_float_optional(key: str) -> Optional[float]:
        raw = os.environ.get(key)
        if raw is None:
            return None
        try:
            val = float(raw)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(val):
            return None
        return val

    def env_int(key: str, fallback: int, min_val: int = 1) -> int:
        raw = os.environ.get(key)
        if raw is None:
            return fallback
        try:
            val = int(raw)
        except (TypeError, ValueError):
            return fallback
        if val < min_val:
            return fallback
        return val

    def env_choice(key: str, fallback: str, choices: Set[str]) -> str:
        raw = str(os.environ.get(key) or "").strip().lower()
        if raw in choices:
            return raw
        return fallback

    def env_json_list(key: str) -> Optional[List[Dict[str, Any]]]:
        raw = os.environ.get(key)
        if not raw:
            return None
        try:
            payload = json.loads(raw)
        except json.JSONDecodeError:
            return None
        if isinstance(payload, list):
            return payload
        return None

    entry_only_realizable = env_bool("PM_AUTO_TRADE_ENTRY_ONLY_REALIZABLE", True)
    entry_require_signal_edge = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_MIN", True)
    entry_require_edge_band = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_BAND", False)
