def validate_auto_trade_config(config: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(config, dict):
        return {"ok": False, "errors": ["配置格式无效"], "warnings": []}
    config = dict(config)
    if "prefetch_event_detail" in config:
        config["prefetch_event_detail"] = bool(config["prefetch_event_detail"])
    _migrate_legacy_edge_keys(config)
    entry_only_realizable = bool(config.get("entry_only_realizable", True))
    exec_edge_flags_disabled = {
        "entry_yes_top_require_exec_edge",
        "entry_follow_require_exec_edge",
        "entry_hard_bound_no_require_exec_edge",
        "entry_adj_pair_require_exec_edge",
        "entry_require_q_range",
        "entry_require_q_band",
        "entry_require_ask_range",
        "entry_require_no_ask_range",
        "entry_require_yes_overprice",
        "entry_block_no_by_yes_q",
        "entry_require_spread_max",
        "entry_require_ask_le_q_min",
        "entry_require_auto_max_ask",
        "entry_skip_top_label",
        "entry_lag_enabled",
        "entry_lag_limit_enabled",
        "entry_require_depth",
    }
    errors: List[str] = []
    warnings: List[str] = []

    def num(key: str) -> Optional[float]:
        return to_float(config.get(key))

    def flag(key: str) -> bool:
        if entry_only_realizable and key in exec_edge_flags_disabled:
            return False
        return bool(config.get(key))

    def ensure_range(min_key: str, max_key: str, label: str, enabled: bool = True) -> None:
        if not enabled:
            return
        min_val = num(min_key)
        max_val = num(max_key)
        if min_val is None or max_val is None:
            return
        if min_val > max_val:
            errors.append(f"{label}最小值大于最大值")

    ensure_range("entry_q_min", "entry_q_max", "q范围", flag("entry_require_q_range"))
    ensure_range("entry_ask_min", "entry_ask_max", "ask范围", flag("entry_require_ask_range"))
    ensure_range("no_ask_min", "no_ask_max", "ask_no范围", flag("entry_require_no_ask_range"))
    ensure_range("entry_depth_mult_min", "entry_depth_mult_max", "深度倍数范围", True)
    ensure_range("entry_open_delay_min_sec", "entry_open_delay_max_sec", "开盘延迟范围", True)
    ensure_range("edge_score_never_min", "edge_score_never_max", "有效优势分 Never区间", flag("entry_require_edge_score_range"))
    ensure_range("edge_score_buy_min", "edge_score_buy_max", "有效优势分 Buy区间", flag("entry_require_edge_score_buy_range"))
    min_span = num("price_trend_min_span_sec")
    if min_span is not None and min_span < 0:
        errors.append("趋势最小时间跨度需为非负秒数")
    min_interval = num("auto_trade_min_run_interval_sec")
    if min_interval is not None and min_interval < 0:
        errors.append("自动交易最小间隔需为非负秒数")
    if flag("entry_require_q_range"):
        q_min = num("entry_q_min")
        q_max = num("entry_q_max")
        if q_min is not None and q_max is not None:
            if q_min < 0 or q_max > 1:
                errors.append("q范围需在[0,1]")
    if flag("entry_require_ask_range"):
        ask_min = num("entry_ask_min")
        ask_max = num("entry_ask_max")
        if ask_min is not None and ask_max is not None:
            if ask_min < 0 or ask_max > 1:
                errors.append("ask范围需在[0,1]")
    if flag("entry_require_no_ask_range"):
        no_min = num("no_ask_min")
        no_max = num("no_ask_max")
        if no_min is not None and no_max is not None:
            if no_min < 0 or no_max > 1:
                errors.append("ask_no范围需在[0,1]")
    if flag("entry_require_q_band"):
        q_bands: List[Tuple[float, float]] = []
        for idx in range(1, 4):
            min_val = num(f"entry_q_band_{idx}_min")
            max_val = num(f"entry_q_band_{idx}_max")
            if min_val is None and max_val is None:
                continue
            if min_val is None or max_val is None:
                errors.append(f"q分段{idx}需同时填写上下限")
                continue
            if min_val == 0 and max_val == 0:
                continue
            if min_val < 0 or max_val < 0 or min_val > 1 or max_val > 1:
                errors.append(f"q分段{idx}需在[0,1]")
                continue
            if min_val > max_val:
                errors.append(f"q分段{idx}最小值大于最大值")
                continue
            q_bands.append((min_val, max_val))
        if not q_bands:
            errors.append("q分段已开启但没有有效区间")
        else:
            if flag("entry_require_q_range"):
                q_min = num("entry_q_min")
                q_max = num("entry_q_max")
                if q_min is not None and q_max is not None:
                    overlap = any(max(q_min, band_min) <= min(q_max, band_max) for band_min, band_max in q_bands)
                    if not overlap:
                        errors.append("q分段与q范围无交集，结果将无可买样本")

    if flag("entry_require_edge_score_range") and flag("entry_require_edge_score_buy_range"):
        n_min = num("edge_score_never_min")
        n_max = num("edge_score_never_max")
        b_min = num("edge_score_buy_min")
        b_max = num("edge_score_buy_max")
        if None not in (n_min, n_max, b_min, b_max):
            if max(n_min, b_min) > min(n_max, b_max):
                warnings.append("有效优势分 Never/Buy 参考区间无交集（不影响入场硬门槛，仅影响参考展示）")
    if flag("entry_require_edge_score_buy_range"):
        score_min = num("edge_score_min")
        buy_max = num("edge_score_buy_max")
        if score_min is not None and buy_max is not None and score_min > buy_max:
            warnings.append("有效优势分最低门槛高于 Buy 参考上限（不影响入场硬门槛）")
    if flag("entry_require_edge_score_range"):
        score_min = num("edge_score_min")
        never_max = num("edge_score_never_max")
        if score_min is not None and never_max is not None and score_min > never_max:
            warnings.append("有效优势分最低门槛高于 Never 参考上限（不影响入场硬门槛）")
