def apply_auto_trade_config(payload: Dict[str, Any]) -> None:
    global AUTO_TRADE_MIN_RUN_INTERVAL_SEC
    if not isinstance(payload, dict):
        return
    _migrate_legacy_edge_keys(payload)
    entry_only_realizable = (
        bool(payload.get("entry_only_realizable"))
        if "entry_only_realizable" in payload
        else _env_bool("PM_AUTO_TRADE_ENTRY_ONLY_REALIZABLE", True)
    )
    _normalize_entry_only_realizable_config(payload, entry_only_realizable=entry_only_realizable)

    def apply_float(key: str, env_key: str, min_val: Optional[float] = None) -> Optional[float]:
        if key not in payload:
            return None
        raw = payload.get(key)
        try:
            val = float(raw) if raw is not None else None
        except (TypeError, ValueError):
            return None
        if val is None or not math.isfinite(val):
            return None
        if min_val is not None and val < min_val:
            return None
        os.environ[env_key] = f"{val:.6g}"
        return val

    def apply_float_nullable(
        key: str,
        env_key: str,
        *,
        min_val: Optional[float] = None,
        default_val: float = 0.0,
    ) -> Optional[float]:
        if key not in payload:
            return None
        raw = payload.get(key)
        if raw is None:
            os.environ[env_key] = f"{default_val:.6g}"
            return default_val
        try:
            val = float(raw)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(val):
            return None
        if min_val is not None and val < min_val:
            return None
        os.environ[env_key] = f"{val:.6g}"
        return val

    def apply_bool(key: str, env_key: str) -> Optional[bool]:
        if key not in payload:
            return None
        flag = bool(payload.get(key))
        os.environ[env_key] = "1" if flag else "0"
        return flag

    def apply_choice(key: str, env_key: str, choices: Set[str]) -> Optional[str]:
        if key not in payload:
            return None
        value = str(payload.get(key) or "").strip().lower()
        if value not in choices:
            return None
        os.environ[env_key] = value
        return value

    def apply_int(key: str, env_key: str, min_val: Optional[int] = None) -> Optional[int]:
        if key not in payload:
            return None
        raw = payload.get(key)
        try:
            val = int(raw) if raw is not None else None
        except (TypeError, ValueError):
            return None
        if val is None:
            return None
        if min_val is not None and val < min_val:
            return None
        os.environ[env_key] = str(val)
        return val

    def apply_json_list(key: str, env_key: str) -> Optional[List[Dict[str, Any]]]:
        if key not in payload:
            return None
        raw = payload.get(key)
        if not isinstance(raw, list):
            return None
        cleaned: List[Dict[str, Any]] = []
        for item in raw:
            if not isinstance(item, dict):
                continue
            cleaned.append(dict(item))
        if not cleaned:
            return None
        os.environ[env_key] = json.dumps(cleaned, ensure_ascii=True)
        return cleaned

