def _normalize_balance_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    data = payload if isinstance(payload, dict) else {}

    def pick(keys: List[str]) -> Optional[Any]:
        for key in keys:
            if key in data:
                return data.get(key)
        return None

    asset_type = str(pick(["asset_type", "assetType"]) or "COLLATERAL")
    decimals = 6 if asset_type.upper() == "COLLATERAL" else 0

    def parse_amount(raw_value: Any) -> Optional[float]:
        if raw_value is None:
            return None
        text = str(raw_value).strip()
        if not text:
            return None
        num = to_float(text)
        if num is None:
            return None
        if decimals > 0 and re.fullmatch(r"-?\d+", text):
            return num / (10 ** decimals)
        return num

    def extract_max_amount(raw_value: Any) -> Optional[float]:
        vals: List[float] = []
        if isinstance(raw_value, dict):
            for value in raw_value.values():
                parsed = extract_max_amount(value)
                if parsed is not None and math.isfinite(parsed):
                    vals.append(parsed)
        elif isinstance(raw_value, (list, tuple, set)):
            for value in raw_value:
                parsed = extract_max_amount(value)
                if parsed is not None and math.isfinite(parsed):
                    vals.append(parsed)
        else:
            parsed = parse_amount(raw_value)
            if parsed is not None and math.isfinite(parsed):
                vals.append(parsed)
        if not vals:
            return None
        return max(max(vals), 0.0)

    def normalize_allowances_map(raw_value: Any) -> Dict[str, float]:
        out: Dict[str, float] = {}
        if not isinstance(raw_value, dict):
            return out
        for key, value in raw_value.items():
            spender = str(key or "").strip()
            if not spender:
                continue
            parsed = extract_max_amount(value)
            if parsed is None or not math.isfinite(parsed):
                continue
            out[spender.lower()] = max(0.0, float(parsed))
        return out

    balance_raw = pick(["balance", "available", "available_balance", "availableBalance", "free_balance", "freeBalance"])
    allowance_raw = pick(["allowance"])
    allowances_raw = pick(["allowances"])
    balance_allowance_raw = pick(["balance_allowance", "balanceAllowance"])
    balance = extract_max_amount(balance_raw)
    allowance = extract_max_amount(allowance_raw)
    allowances_map = normalize_allowances_map(allowances_raw)
    allowance_max = max(allowances_map.values()) if allowances_map else None
    if allowance is None:
        allowance = allowance_max
    balance_allowance = extract_max_amount(balance_allowance_raw)
    if balance_allowance is None and balance is not None and allowance is not None:
        balance_allowance = min(balance, allowance)
    updated_at = str(pick(["updated_at", "updatedAt"]) or now_text())
    error = str(data.get("error") or "")
    return {
        "ok": data.get("ok", True) if isinstance(data.get("ok", True), bool) else True,
        "balance": balance,
        "allowance": allowance,
        "balance_allowance": balance_allowance,
        "allowances": allowances_map,
        "allowance_max": allowance_max,
        "allowance_spenders": len(allowances_map),
        "balance_raw": str(balance_raw or ""),
        "allowance_raw": str(allowance_raw or ""),
        "balance_allowance_raw": str(balance_allowance_raw or ""),
        "allowances_raw": str(allowances_raw or ""),
        "decimals": decimals,
        "asset_type": asset_type,
        "updated_at": updated_at,
        "error": error,
    }


def fetch_auto_trade_balance(force: bool = False, refresh: bool = False) -> Dict[str, Any]:
    now = time.time()
    cache = AUTO_TRADE_BALANCE_CACHE
    if ACCOUNT_REQUESTS_DISABLED or _env_bool("PM_AUTO_TRADE_BALANCE_DISABLED", False):
        payload = {"ok": False, "error": "balance_disabled", "updated_at": now_text()}
        cache["ts"] = now
        cache["last_exec_ts"] = now
        cache["payload"] = payload
        return dict(payload)
    last_exec = float(cache.get("last_exec_ts") or 0.0)
    if last_exec and now - last_exec < max(1, AUTO_TRADE_BALANCE_MIN_INTERVAL_SEC):
        return dict(cache.get("payload") or {"ok": False, "error": "balance_cooldown", "updated_at": now_text()})
    if not force and cache.get("payload") and now - float(cache.get("ts") or 0.0) < AUTO_TRADE_BALANCE_CACHE_SEC:
        return dict(cache["payload"])
    if not BALANCE_SYNC_LOCK.acquire(blocking=False):
        return dict(cache.get("payload") or {"ok": False, "error": "balance_sync_running", "updated_at": now_text()})
    try:
        cache["last_exec_ts"] = now
        ok, payload = _run_node_balance(refresh=refresh)
        if not ok:
            err = str(payload.get("error") or "balance_failed")
            detail = str(payload.get("stderr") or payload.get("stdout") or payload.get("error_detail") or "")
            if _is_errno24_error_text(err):
                cached_payload = dict(cache.get("payload") or {})
                if cached_payload:
                    cached_payload.setdefault("updated_at", now_text())
                    cache["ts"] = now
                    cache["payload"] = cached_payload
                    return dict(cached_payload)
            if (
                _is_exec_timeout_error_text(err)
                or _is_exec_timeout_error_text(detail)
                or _is_upstream_5xx_error_text(err)
                or _is_upstream_5xx_error_text(detail)
            ):
                cached_payload = dict(cache.get("payload") or {})
                if cached_payload:
                    cached_payload["ok"] = bool(cached_payload.get("ok", True))
                    cached_payload["error"] = str(cached_payload.get("error") or "")
                    cached_payload.setdefault("updated_at", now_text())
                    cache["ts"] = now
                    cache["payload"] = cached_payload
                    return dict(cached_payload)
            result = {"ok": False, "error": err, "updated_at": now_text()}
        else:
            result = _normalize_balance_payload(payload)
            if not result.get("ok") and payload.get("error"):
                result["error"] = str(payload.get("error"))
        diag = auto_trade_env_diagnostics()
        result["signature_type"] = diag.get("signature_type")
        result["signer_address"] = diag.get("signer_address")
        result["funder_address"] = diag.get("funder_address")
        result["balance_owner"] = diag.get("balance_owner")
        cache["ts"] = now
        cache["payload"] = result
        return dict(result)
    finally:
        BALANCE_SYNC_LOCK.release()


def _active_open_order_ids_snapshot(now_utc: Optional[datetime] = None) -> Tuple[set[str], bool]:
    if now_utc is None:
        now_utc = datetime.now(timezone.utc)
    active_open_order_ids: set[str] = set()
    open_order_cache_fresh = False
    open_order_updated = parse_iso_ts(str(OPEN_ORDER_CACHE.get("updated_at") or ""))
    if open_order_updated is not None and open_order_updated.tzinfo is None:
        open_order_updated = open_order_updated.replace(tzinfo=timezone.utc)
    if open_order_updated is not None:
        age_sec = max(0.0, (now_utc - open_order_updated).total_seconds())
        open_order_cache_fresh = age_sec <= max(float(OPEN_ORDER_CACHE_MAX_AGE_SEC) * 2.0, 120.0)
    if open_order_cache_fresh:
        for item in list(OPEN_ORDER_CACHE.get("data") or []):
            if not isinstance(item, dict):
                continue
            order_id = str(item.get("last_order_id") or item.get("order_id") or item.get("id") or "").strip()
            if order_id:
                active_open_order_ids.add(order_id)
    return active_open_order_ids, open_order_cache_fresh


def collect_auto_trade_job_blockers(
    conn: sqlite3.Connection,
    *,
    run_date: str = "",
    window_hours: Optional[int] = None,
) -> Dict[str, Any]:
    now_utc = datetime.now(timezone.utc)
    now_iso = now_utc.isoformat(timespec="seconds")
    window = int(window_hours if window_hours is not None else AUTO_TRADE_BLOCKER_WINDOW_HOURS)
    window = max(1, min(window, 72))
    cutoff_dt = now_utc - timedelta(hours=window)
    cutoff_iso = cutoff_dt.isoformat(timespec="seconds")
    queue_stale_sec = max(120, int(os.environ.get("PM_AUTO_TRADE_JOB_QUEUE_STALE_SEC", "600") or 600))
    stuck_sec = max(120, int(os.environ.get("PM_AUTO_TRADE_JOB_STUCK_SEC", "1200") or 1200))
    run_date_key = _normalize_date_key(run_date)
    cur = conn.cursor()
    where_run = ""
    params: List[Any] = [cutoff_iso]
    if run_date_key:
        where_run = "AND run_date = ?"
        params.append(run_date_key)
    try:
        cur.execute(
            f"""
            SELECT id, run_date, source, state, retry_count, max_retry,
                   next_retry_at, lease_until, last_error, started_at, ended_at,
                   created_at, updated_at
            FROM auto_trade_jobs
            WHERE (
                    COALESCE(created_at, '') >= ?
                    OR state IN ('queued', 'running', 'retrying')
                  )
              {where_run}
            ORDER BY updated_at DESC, id DESC
            LIMIT 800
            """,
            tuple(params),
        )
        rows = cur.fetchall() or []
    except sqlite3.OperationalError:
        return {
            "window_hours": window,
            "has_blocker": False,
            "total": 0,
            "top_error": "",
            "counts": [],
            "latest": None,
            "source": "auto_trade_jobs",
            "latest_job": None,
        }

    counts: Dict[str, int] = {}
    latest: Optional[Dict[str, Any]] = None
    latest_dt: Optional[datetime] = None
    latest_job: Optional[Dict[str, Any]] = None
    recovery_by_run_date: Dict[str, datetime] = {}

    def _event_dt(row: sqlite3.Row) -> Optional[datetime]:
        for key in ("updated_at", "ended_at", "started_at", "created_at"):
            text = str(row[key] or "").strip()
            dt = parse_iso_ts(text)
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt
        return None

    for row in rows:
        state = str(row["state"] or "").strip().lower()
        if state not in {"queued", "running", "retrying", "success"}:
            continue
        run_date_text = _normalize_date_key(str(row["run_date"] or ""))
        if not run_date_text:
            continue
        dt = _event_dt(row)
        if dt is None:
            continue
        prev = recovery_by_run_date.get(run_date_text)
        if prev is None or dt > prev:
            recovery_by_run_date[run_date_text] = dt

    for row in rows:
        state = str(row["state"] or "").strip().lower()
        event_dt = _event_dt(row)
        if event_dt is None:
            event_dt = now_utc
        if event_dt < cutoff_dt:
            continue
        run_date_text = _normalize_date_key(str(row["run_date"] or ""))
        recovery_dt = recovery_by_run_date.get(run_date_text) if run_date_text else None
        if state in {"failed", "stuck"} and recovery_dt is not None and recovery_dt > event_dt:
            continue
        if latest_job is None:
            latest_job = {
                "id": int(row["id"] or 0),
                "run_date": str(row["run_date"] or ""),
                "source": str(row["source"] or ""),
                "state": state,
                "retry_count": int(row["retry_count"] or 0),
                "max_retry": int(row["max_retry"] or 0),
                "next_retry_at": str(row["next_retry_at"] or ""),
                "lease_until": str(row["lease_until"] or ""),
                "last_error": str(row["last_error"] or ""),
                "started_at": str(row["started_at"] or ""),
                "ended_at": str(row["ended_at"] or ""),
                "updated_at": str(row["updated_at"] or ""),
            }
        code = ""
        detail = ""
        if state == "running":
            started_at = parse_iso_ts(str(row["started_at"] or ""))
            if started_at is not None and started_at.tzinfo is None:
                started_at = started_at.replace(tzinfo=timezone.utc)
            lease_until = parse_iso_ts(str(row["lease_until"] or ""))
            if lease_until is not None and lease_until.tzinfo is None:
                lease_until = lease_until.replace(tzinfo=timezone.utc)
            run_age = None
            if started_at is not None:
                run_age = max(0.0, (now_utc - started_at).total_seconds())
            lease_expired = lease_until is not None and lease_until <= now_utc
            # Do not flag running jobs only because lease expired:
            # worker may still be executing a long run without heartbeat updates.
            if (run_age is not None and run_age >= float(stuck_sec)) or (run_age is None and lease_expired):
                code = "job_running_stuck"
                detail = f"running 超时 ({int(run_age or 0)}s)"
        elif state == "retrying":
            code = "job_retrying"
            retry_count = int(row["retry_count"] or 0)
            max_retry = int(row["max_retry"] or 0)
            detail = f"retry {retry_count}/{max_retry}"
        elif state == "failed":
            code = "job_failed"
            detail = str(row["last_error"] or "").strip() or "worker_failed"
        elif state == "stuck":
            code = "job_stuck"
            detail = str(row["last_error"] or "").strip() or "worker_stuck"
        elif state == "queued":
            created_at = parse_iso_ts(str(row["created_at"] or ""))
            if created_at is not None and created_at.tzinfo is None:
                created_at = created_at.replace(tzinfo=timezone.utc)
            queue_age = None
            if created_at is not None:
                queue_age = max(0.0, (now_utc - created_at).total_seconds())
            if queue_age is not None and queue_age >= float(queue_stale_sec):
                code = "job_queued_stale"
                detail = f"queued {int(queue_age)}s"
        if not code:
            continue
        counts[code] = int(counts.get(code) or 0) + 1
        if latest is None or (event_dt is not None and (latest_dt is None or event_dt > latest_dt)):
            latest_dt = event_dt
            latest = {
                "id": int(row["id"] or 0),
                "run_date": str(row["run_date"] or ""),
                "source": str(row["source"] or ""),
                "state": state,
                "code": code,
                "detail": detail,
                "retry_count": int(row["retry_count"] or 0),
                "max_retry": int(row["max_retry"] or 0),
                "next_retry_at": str(row["next_retry_at"] or ""),
                "lease_until": str(row["lease_until"] or ""),
                "last_error": str(row["last_error"] or ""),
                "started_at": str(row["started_at"] or ""),
                "ended_at": str(row["ended_at"] or ""),
                "updated_at": str(row["updated_at"] or ""),
            }

    sorted_counts = sorted(counts.items(), key=lambda item: (-int(item[1]), str(item[0])))
    top_error = sorted_counts[0][0] if sorted_counts else ""
    total = sum(int(v) for _k, v in sorted_counts)
    return {
        "window_hours": window,
        "has_blocker": bool(sorted_counts),
        "total": total,
        "top_error": top_error,
        "counts": [{"error": key, "count": int(val)} for key, val in sorted_counts],
        "latest": latest,
        "source": "auto_trade_jobs",
        "latest_job": latest_job,
        "now_at": now_iso,
    }


def collect_auto_trade_blockers(
    conn: sqlite3.Connection,
    trade_sync_status: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    window_hours = max(1, AUTO_TRADE_BLOCKER_WINDOW_HOURS)
    now_utc = datetime.now(timezone.utc)
    cutoff_dt = now_utc - timedelta(hours=window_hours)
    active_open_order_ids, open_order_cache_fresh = _active_open_order_ids_snapshot(now_utc)
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, side, state, position_size, last_status, last_error, last_order_id, last_action, last_action_at, updated_at, exit_skip_reason
            FROM edge_trades
            WHERE COALESCE(last_error, '') <> ''
            ORDER BY updated_at DESC
            LIMIT ?
            """,
            (AUTO_TRADE_BLOCKER_MAX_ROWS,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        rows = []
    counts: Dict[str, int] = {}
    holdoff_count = 0
    holdoff_samples: List[Dict[str, Any]] = []
    latest: Optional[Dict[str, Any]] = None
    latest_dt: Optional[datetime] = None
    open_order_blocker_stale_sec = max(
        60.0,
        _env_float("PM_AUTO_TRADE_OPEN_ORDER_BLOCKER_STALE_SEC", 600.0) or 600.0,
    )
    open_order_wait_sec = max(
        30.0,
        _env_float("PM_AUTO_TRADE_OPEN_ORDER_WAIT_SEC", 90.0) or 90.0,
    )
    open_order_recheck_sec = max(
        5.0,
        _env_float("PM_AUTO_TRADE_OPEN_ORDER_RECHECK_COOLDOWN_SEC", 20.0) or 20.0,
    )
    open_order_auto_cancel_enabled = _env_bool("PM_AUTO_TRADE_OPEN_ORDER_AUTO_CANCEL_ENABLED", True)
    open_order_auto_cancel_sec = max(
        open_order_wait_sec + open_order_recheck_sec,
        _env_float("PM_AUTO_TRADE_OPEN_ORDER_AUTO_CANCEL_SEC", 300.0) or 300.0,
    )
    open_order_waiting_sec = max(
        open_order_wait_sec + open_order_recheck_sec,
        open_order_auto_cancel_sec if open_order_auto_cancel_enabled else (open_order_wait_sec + open_order_recheck_sec),
    )
    sync_last_ok_dt: Optional[datetime] = None
    if isinstance(trade_sync_status, dict):
        sync_last_ok_dt = parse_iso_ts(str(trade_sync_status.get("last_ok_at") or ""))
        if sync_last_ok_dt is not None and sync_last_ok_dt.tzinfo is None:
            sync_last_ok_dt = sync_last_ok_dt.replace(tzinfo=timezone.utc)
    local_today = datetime.now().astimezone().date()
    for row in rows:
        error_text = str(row["last_error"] or "").strip()
        if not error_text:
            continue
        if error_text.startswith("min_hold:"):
            holdoff_count += 1
            if len(holdoff_samples) < 6:
                event_at = str(row["last_action_at"] or row["updated_at"] or "")
                event_dt = parse_iso_ts(event_at)
                if event_dt is not None and event_dt.tzinfo is None:
                    event_dt = event_dt.replace(tzinfo=timezone.utc)
                age_min = None
                if event_dt is not None:
                    age_min = int(max(0.0, (datetime.now(timezone.utc) - event_dt).total_seconds() / 60.0))
                wait_elapsed = None
                wait_target = None
                wait_remaining = None
                m = re.match(r"^min_hold:(\d+)\s*/\s*(\d+)$", error_text)
                if m:
                    try:
                        wait_elapsed = int(m.group(1))
                        wait_target = int(m.group(2))
                    except (TypeError, ValueError):
                        wait_elapsed = None
                        wait_target = None
                    if wait_elapsed is not None and wait_target is not None:
                        wait_remaining = max(0, wait_target - wait_elapsed)
                holdoff_samples.append(
                    {
                        "slug": str(row["slug"] or ""),
                        "event_date": str(row["event_date"] or ""),
                        "outcome": str(row["outcome"] or ""),
                        "side": str(row["side"] or ""),
                        "state": str(row["state"] or ""),
                        "last_status": str(row["last_status"] or ""),
                        "last_error": error_text,
                        "last_action": str(row["last_action"] or ""),
                        "event_at": event_at,
                        "age_min": age_min,
                        "updated_at": str(row["updated_at"] or ""),
                        "wait_elapsed_sec": wait_elapsed,
                        "wait_target_sec": wait_target,
                        "wait_remaining_sec": wait_remaining,
                    }
                )
            continue
        if error_text == "exit_retry_blocked":
            holdoff_count += 1
            if len(holdoff_samples) < 6:
                event_at = str(row["last_action_at"] or row["updated_at"] or "")
                event_dt = parse_iso_ts(event_at)
                if event_dt is not None and event_dt.tzinfo is None:
                    event_dt = event_dt.replace(tzinfo=timezone.utc)
                age_min = None
                wait_elapsed = None
                wait_target = int(max(0.0, float(AUTO_TRADE_EXIT_RETRY_COOLDOWN_SEC)))
                wait_remaining = wait_target
                if event_dt is not None:
                    elapsed_sec = max(0.0, (datetime.now(timezone.utc) - event_dt).total_seconds())
                    age_min = int(elapsed_sec / 60.0)
                    wait_elapsed = int(elapsed_sec)
                    wait_remaining = max(0, wait_target - wait_elapsed)
                holdoff_samples.append(
                    {
                        "slug": str(row["slug"] or ""),
                        "event_date": str(row["event_date"] or ""),
                        "outcome": str(row["outcome"] or ""),
                        "side": str(row["side"] or ""),
                        "state": str(row["state"] or ""),
                        "last_status": str(row["last_status"] or ""),
                        "last_error": error_text,
                        "last_action": str(row["last_action"] or ""),
                        "event_at": event_at,
                        "age_min": age_min,
                        "updated_at": str(row["updated_at"] or ""),
                        "wait_elapsed_sec": wait_elapsed,
                        "wait_target_sec": wait_target,
                        "wait_remaining_sec": wait_remaining,
                        "holdoff_type": "exit_retry_cooldown",
                    }
                )
            continue
        skip_reason = str(row["exit_skip_reason"] or "").strip().lower()
        if skip_reason == "no_orderbook":
            continue
        if error_text.lower() in AUTO_TRADE_IGNORED_ERRORS:
            continue
        lowered_error = error_text.lower()
        if "orderbook" in lowered_error and ("does not exist" in lowered_error or "not exist" in lowered_error):
            continue
        if lowered_error.startswith("topup_size_too_large:") and str(row["last_action"] or "").strip().lower() == "exit_skip":
            continue
        if error_text.startswith("open_order_exists:"):
            blocker_order_id = error_text.split(":", 1)[1].strip()
            if open_order_cache_fresh and blocker_order_id and blocker_order_id not in active_open_order_ids:
                continue
        if error_text == "order_missing":
            blocker_order_id = str(row["last_order_id"] or "").strip()
            if open_order_cache_fresh and blocker_order_id and blocker_order_id not in active_open_order_ids:
                continue
        action = str(row["last_action"] or "").strip().lower()
        state = str(row["state"] or "").strip().lower()
        last_order_id = str(row["last_order_id"] or "").strip()
        position_size = to_float(row["position_size"])
        position_size = position_size if position_size is not None and math.isfinite(position_size) else 0.0
        # No remaining position in exit state is not an execution blocker.
        # Keep health focused on actionable failures only.
        if state == "exit" and position_size <= TIME_EDGE_Q_EPS:
            continue
        # Entry failed without position/open-order is historical failure noise, not a live blocker.
        if state == "entry_failed" and position_size <= TIME_EDGE_Q_EPS and not last_order_id:
            continue
        event_date_text = str(row["event_date"] or "").strip()
        if position_size <= TIME_EDGE_Q_EPS and event_date_text:
            try:
                event_day = datetime.strptime(event_date_text, "%Y-%m-%d").date()
            except (TypeError, ValueError):
                event_day = None
            if event_day is not None and event_day < local_today:
                stale_no_pos_error = (
                    lowered_error in {
                        "order_missing",
                        "no_order_id",
                        "confirm_wait_sync",
                        "pending_timeout",
                        "order_not_found",
                        "confirm_not_found",
                    }
                    or lowered_error.startswith("open_order_exists:")
                    or lowered_error.startswith("open_order_reprice")
                    or "timeout" in lowered_error
                )
                if stale_no_pos_error:
                    continue
        if (
            error_text.startswith("open_order_exists:")
            and state == "exit"
            and position_size <= TIME_EDGE_Q_EPS
        ):
            continue
        if error_text == "order_missing":
            if (state == "entry" and position_size > TIME_EDGE_Q_EPS) or (
                state == "exit" and position_size <= TIME_EDGE_Q_EPS
            ):
                continue
        if error_text.lower() in {"no_balance", "balance_parse_failed", "balance_unavailable"} and action == "exit_skip":
            try:
                event_day = datetime.strptime(event_date_text, "%Y-%m-%d").date()
                if event_day < local_today:
                    continue
            except (TypeError, ValueError):
                pass
        event_at = str(row["last_action_at"] or row["updated_at"] or "")
        event_dt = parse_iso_ts(event_at)
        if event_dt is not None and event_dt.tzinfo is None:
            event_dt = event_dt.replace(tzinfo=timezone.utc)
        if event_dt is None and action in {"entry", "entry_topup"}:
            event_dt = datetime.now(timezone.utc)
        if event_dt is not None and event_dt < cutoff_dt:
            continue
        if error_text.startswith("open_order_exists:") and event_dt is not None:
            # open_order_pending in waiting window is in-progress, not a blocker.
            last_status_text = str(row["last_status"] or "").strip().lower()
            waiting_like = (
                last_status_text in {"open_order_pending", "open_order_recheck_pending"}
                or "open_order_pending" in last_status_text
            )
            if waiting_like:
                wait_age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                if wait_age_sec < open_order_waiting_sec:
                    continue
        if error_text.startswith("open_order_exists:"):
            blocker_order_id = error_text.split(":", 1)[1].strip()
            if open_order_cache_fresh and blocker_order_id and blocker_order_id in active_open_order_ids:
                if event_dt is not None:
                    active_age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                    if active_age_sec < open_order_blocker_stale_sec:
                        continue
                else:
                    continue
        if error_text == "confirm_wait_sync":
            if sync_last_ok_dt is not None and event_dt is not None and sync_last_ok_dt > event_dt + timedelta(seconds=1):
                continue
            if event_dt is not None and AUTO_TRADE_CONFIRM_WAIT_SYNC_MAX_SEC > 0:
                wait_age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                if wait_age_sec >= float(AUTO_TRADE_CONFIRM_WAIT_SYNC_MAX_SEC):
                    continue
        if error_text == "exit_retry_blocked":
            if event_dt is not None and AUTO_TRADE_EXIT_RETRY_COOLDOWN_SEC > 0:
                age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                if age_sec >= float(AUTO_TRADE_EXIT_RETRY_COOLDOWN_SEC):
                    continue
        counts[error_text] = int(counts.get(error_text) or 0) + 1
        if latest is None or (event_dt is not None and (latest_dt is None or event_dt > latest_dt)):
            latest_dt = event_dt
            age_min = None
            if event_dt is not None:
                age_min = int(max(0.0, (datetime.now(timezone.utc) - event_dt).total_seconds() / 60.0))
            latest = {
                "slug": str(row["slug"] or ""),
                "event_date": str(row["event_date"] or ""),
                "outcome": str(row["outcome"] or ""),
                "side": str(row["side"] or ""),
                "state": str(row["state"] or ""),
                "last_status": str(row["last_status"] or ""),
                "last_error": error_text,
                "last_action": str(row["last_action"] or ""),
                "event_at": event_at,
                "age_min": age_min,
                "updated_at": str(row["updated_at"] or ""),
            }
    sorted_counts = sorted(counts.items(), key=lambda item: (-int(item[1]), str(item[0])))
    top_error = sorted_counts[0][0] if sorted_counts else ""
    total = sum(int(v) for _k, v in sorted_counts)
    return {
        "window_hours": window_hours,
        "has_blocker": bool(sorted_counts),
        "total": total,
        "top_error": top_error,
        "counts": [{"error": key, "count": int(val)} for key, val in sorted_counts],
        "holdoff_count": int(holdoff_count),
        "holdoff_samples": holdoff_samples,
        "latest": latest,
        "source": "edge_trades",
    }


def collect_fill_attribution_blockers(
    conn: sqlite3.Connection,
    *,
    window_hours: Optional[int] = None,
) -> Dict[str, Any]:
    window = int(window_hours or AUTO_TRADE_ATTR_BLOCKER_WINDOW_HOURS)
    if window <= 0:
        window = AUTO_TRADE_ATTR_BLOCKER_WINDOW_HOURS
    cutoff_iso = (datetime.now(timezone.utc) - timedelta(hours=window)).isoformat(timespec="seconds")
    cur = conn.cursor()
    payload: Dict[str, Any] = {
        "window_hours": window,
        "cutoff_at": cutoff_iso,
        "fills_recent": 0,
        "fills_with_order": 0,
        "linked": 0,
        "unlinked": 0,
        "missing_rows": 0,
        "link_ratio": None,
        "top_reasons": [],
        "updated_at": now_text(),
    }
    try:
        row_recent = cur.execute(
            """
            SELECT COUNT(*)
            FROM edge_trade_fills
            WHERE datetime(COALESCE(trade_time, created_at)) >= datetime(?)
            """,
            (cutoff_iso,),
        ).fetchone()
        payload["fills_recent"] = int((row_recent[0] if row_recent else 0) or 0)
        row_order = cur.execute(
            """
            SELECT COUNT(*)
            FROM edge_trade_fills
            WHERE datetime(COALESCE(trade_time, created_at)) >= datetime(?)
              AND COALESCE(order_id, '') <> ''
            """,
            (cutoff_iso,),
        ).fetchone()
        fills_with_order = int((row_order[0] if row_order else 0) or 0)
        payload["fills_with_order"] = fills_with_order
    except sqlite3.OperationalError:
        payload["error"] = "edge_trade_fills_missing"
        return payload
    try:
        row_linked = cur.execute(
            """
            SELECT
                SUM(CASE WHEN COALESCE(a.linked, 0) = 1 THEN 1 ELSE 0 END) AS linked_n,
                SUM(CASE WHEN a.trade_id IS NULL THEN 1 ELSE 0 END) AS missing_n
            FROM edge_trade_fills f
            LEFT JOIN trade_fill_attributions a ON a.trade_id = f.trade_id
            WHERE datetime(COALESCE(f.trade_time, f.created_at)) >= datetime(?)
              AND COALESCE(f.order_id, '') <> ''
            """,
            (cutoff_iso,),
        ).fetchone()
    except sqlite3.OperationalError as exc:
        text = str(exc or "").lower()
        if "trade_fill_attributions" in text:
            fills_with_order = int(payload.get("fills_with_order") or 0)
            payload["table_missing"] = True
            payload["unlinked"] = fills_with_order
            payload["missing_rows"] = fills_with_order
            payload["link_ratio"] = 0.0 if fills_with_order > 0 else None
            if fills_with_order > 0:
                payload["top_reasons"] = [{"reason": "unattributed", "count": fills_with_order}]
            return payload
        payload["error"] = "trade_fill_attributions_query_failed"
        payload["error_detail"] = str(exc)
        return payload
    linked = int((row_linked[0] if row_linked else 0) or 0)
    missing_rows = int((row_linked[1] if row_linked else 0) or 0)
    fills_with_order = int(payload.get("fills_with_order") or 0)
    unlinked = max(fills_with_order - linked, 0)
    payload["linked"] = linked
    payload["unlinked"] = unlinked
    payload["missing_rows"] = missing_rows
    payload["link_ratio"] = (float(linked) / float(fills_with_order)) if fills_with_order > 0 else None
    reason_rows = cur.execute(
        """
        SELECT
            COALESCE(
                NULLIF(TRIM(a.reason), ''),
                CASE WHEN a.trade_id IS NULL THEN 'unattributed' ELSE 'unknown' END
            ) AS reason,
            COUNT(*) AS n
        FROM edge_trade_fills f
        LEFT JOIN trade_fill_attributions a ON a.trade_id = f.trade_id
        WHERE datetime(COALESCE(f.trade_time, f.created_at)) >= datetime(?)
          AND COALESCE(f.order_id, '') <> ''
          AND COALESCE(a.linked, 0) <> 1
        GROUP BY reason
        ORDER BY n DESC, reason ASC
        LIMIT 10
        """,
        (cutoff_iso,),
    ).fetchall()
    payload["top_reasons"] = [
        {"reason": str(row[0] or "unknown"), "count": int(row[1] or 0)}
        for row in (reason_rows or [])
    ]
    return payload


def reconcile_stale_trade_blockers(
    conn: sqlite3.Connection,
    trade_sync_status: Optional[Dict[str, Any]] = None,
) -> Dict[str, int]:
    now_utc = datetime.now(timezone.utc)
    now_iso = utc_now_iso()
    active_open_order_ids, open_order_cache_fresh = _active_open_order_ids_snapshot(now_utc)
    sync_last_ok_dt: Optional[datetime] = None
    if isinstance(trade_sync_status, dict):
        sync_last_ok_dt = parse_iso_ts(str(trade_sync_status.get("last_ok_at") or ""))
        if sync_last_ok_dt is not None and sync_last_ok_dt.tzinfo is None:
            sync_last_ok_dt = sync_last_ok_dt.replace(tzinfo=timezone.utc)
    open_order_blocker_stale_sec = max(
        60.0,
        _env_float("PM_AUTO_TRADE_OPEN_ORDER_BLOCKER_STALE_SEC", 600.0) or 600.0,
    )
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, side, state,
                   position_size, last_error, last_order_id, last_action,
                   last_action_at, updated_at
            FROM edge_trades
            WHERE COALESCE(last_error, '') <> ''
            LIMIT ?
            """,
            (AUTO_TRADE_BLOCKER_MAX_ROWS,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return {"cleared": 0}

    cleared = 0
    for row in rows:
        error_text = str(row["last_error"] or "").strip()
        if not error_text:
            continue
        action = str(row["last_action"] or "").strip().lower()
        state = str(row["state"] or "").strip().lower()
        position_size = to_float(row["position_size"])
        position_size = position_size if position_size is not None and math.isfinite(position_size) else 0.0
        event_date_text = str(row["event_date"] or "").strip()
        event_at = str(row["last_action_at"] or row["updated_at"] or "")
        event_dt = parse_iso_ts(event_at)
        if event_dt is not None and event_dt.tzinfo is None:
            event_dt = event_dt.replace(tzinfo=timezone.utc)

        clear_reason = ""
        error_lower = error_text.lower()
        if error_lower in AUTO_TRADE_IGNORED_ERRORS:
            clear_reason = "ignored_error"
        elif error_text == "no_order_id":
            # This is an inconsistent state: state=entry but order_id is missing.
            # If there's no position, it is safe to clear and mark it as exited.
            if position_size <= TIME_EDGE_Q_EPS:
                clear_reason = "no_order_id_no_position"
        elif error_text == "confirm_wait_sync":
            if sync_last_ok_dt is not None and event_dt is not None and sync_last_ok_dt > event_dt + timedelta(seconds=1):
                clear_reason = "confirm_synced"
            elif event_dt is not None and AUTO_TRADE_CONFIRM_WAIT_SYNC_MAX_SEC > 0:
                wait_age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                if wait_age_sec >= float(AUTO_TRADE_CONFIRM_WAIT_SYNC_MAX_SEC):
                    clear_reason = "confirm_wait_timeout"
        elif error_text == "pending_timeout":
            if state == "entry" and position_size > TIME_EDGE_Q_EPS:
                clear_reason = "pending_timeout_has_position"
            elif state == "exit" and position_size <= TIME_EDGE_Q_EPS:
                clear_reason = "pending_timeout_no_position_exit"
            else:
                blocker_order_id = str(row["last_order_id"] or "").strip()
                if open_order_cache_fresh and blocker_order_id and blocker_order_id not in active_open_order_ids:
                    clear_reason = "pending_timeout_order_inactive"
                elif event_dt is not None and sync_last_ok_dt is not None:
                    if sync_last_ok_dt > event_dt + timedelta(seconds=1):
                        age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                        if age_sec >= float(AUTO_TRADE_PENDING_TIMEOUT_CLEAR_SEC):
                            clear_reason = "pending_timeout_timeout"
        elif error_text.startswith("open_order_exists:"):
            blocker_order_id = error_text.split(":", 1)[1].strip()
            is_active = False
            if blocker_order_id and open_order_cache_fresh:
                is_active = blocker_order_id in active_open_order_ids
                if not is_active:
                    clear_reason = "open_order_not_active"
            if not clear_reason and event_dt is not None:
                age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                # Active open-order blockers should not stay forever in health noise.
                # Once stale window is exceeded, clear and let execution re-evaluate.
                if age_sec >= open_order_blocker_stale_sec:
                    clear_reason = "open_order_blocker_stale"
        elif error_text == "order_missing":
            state = str(row["state"] or "").strip().lower()
            position_size = to_float(row["position_size"])
            position_size = position_size if position_size is not None and math.isfinite(position_size) else 0.0
            if state == "entry" and position_size > TIME_EDGE_Q_EPS:
                clear_reason = "order_missing_has_position"
            elif state == "exit" and position_size <= TIME_EDGE_Q_EPS:
                clear_reason = "order_missing_no_position"
            else:
                blocker_order_id = str(row["last_order_id"] or "").strip()
                if open_order_cache_fresh and blocker_order_id and blocker_order_id not in active_open_order_ids:
                    clear_reason = "order_missing_reconciled"
                elif event_dt is not None and sync_last_ok_dt is not None:
                    if sync_last_ok_dt > event_dt + timedelta(seconds=1):
                        age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                        if age_sec >= float(AUTO_TRADE_ORDER_MISSING_CLEAR_SEC):
                            clear_reason = "order_missing_timeout"
        elif error_text == "exit_retry_blocked":
            if event_dt is not None and AUTO_TRADE_EXIT_RETRY_COOLDOWN_SEC > 0:
                age_sec = max(0.0, (now_utc - event_dt).total_seconds())
                if age_sec >= float(AUTO_TRADE_EXIT_RETRY_COOLDOWN_SEC):
                    clear_reason = "exit_retry_cooldown"
        elif error_lower in {"no_balance", "balance_parse_failed", "balance_unavailable"} and action == "exit_skip":
            try:
                event_day = datetime.strptime(event_date_text, "%Y-%m-%d").date()
                if event_day < now_utc.date():
                    clear_reason = "expired_exit_skip"
            except (TypeError, ValueError):
                pass

        if not clear_reason:
            continue

        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        outcome = str(row["outcome"] or "")
        side = str(row["side"] or "")
        try:
            if clear_reason == "no_order_id_no_position":
                cur.execute(
                    """
                    UPDATE edge_trades
                    SET state = 'exit',
                        position_size = 0.0,
                        last_order_id = '',
                        last_error = '',
                        last_status = 'no_position',
                        last_action = 'blocker_reconcile',
                        last_action_at = ?,
                        updated_at = ?
                    WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
                      AND COALESCE(last_error, '') = ?
                    """,
                    (now_iso, now_iso, slug, event_date, outcome, side, error_text),
                )
            elif clear_reason == "pending_timeout_has_position":
                cur.execute(
                    """
                    UPDATE edge_trades
                    SET last_error = '',
                        last_status = 'entry_recovered',
                        last_action = 'blocker_reconcile',
                        last_action_at = ?,
                        updated_at = ?
                    WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
                      AND COALESCE(last_error, '') = ?
                    """,
                    (now_iso, now_iso, slug, event_date, outcome, side, error_text),
                )
            else:
                cur.execute(
                    """
                    UPDATE edge_trades
                    SET last_error = '',
                        last_action = 'blocker_reconcile',
                        last_action_at = ?,
                        updated_at = ?
                    WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
                      AND COALESCE(last_error, '') = ?
                    """,
                    (now_iso, now_iso, slug, event_date, outcome, side, error_text),
                )
        except sqlite3.OperationalError:
            continue
        if cur.rowcount and cur.rowcount > 0:
            cleared += int(cur.rowcount)

    if cleared:
        try:
            conn.commit()
        except sqlite3.OperationalError:
            pass
    return {"cleared": cleared}


def _parse_open_order_time(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (int, float)):
        ts = float(value)
        if ts > 1e12:
            ts /= 1000.0
        try:
            return datetime.fromtimestamp(ts, tz=timezone.utc).isoformat(timespec="seconds")
        except (OSError, ValueError):
            return ""
    text = str(value)
    dt = parse_iso_ts(text)
    if not dt:
        return text
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.isoformat(timespec="seconds")


def reconcile_stale_open_order_blockers(conn: sqlite3.Connection, active_order_ids: set[str]) -> int:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, side, last_error, last_order_id
            FROM edge_trades
            WHERE COALESCE(last_error, '') LIKE 'open_order_exists:%' OR COALESCE(last_error, '') = 'order_missing'
            LIMIT ?
            """,
            (AUTO_TRADE_BLOCKER_MAX_ROWS,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return 0
    cleared = 0
    now_iso = utc_now_iso()
    for row in rows:
        error_text = str(row["last_error"] or "").strip()
        blocker_order_id = ""
        if error_text.startswith("open_order_exists:"):
            blocker_order_id = error_text.split(":", 1)[1].strip()
        elif error_text == "order_missing":
            blocker_order_id = str(row["last_order_id"] or "").strip()
        else:
            continue
        if blocker_order_id and blocker_order_id in active_order_ids:
            continue
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        outcome = str(row["outcome"] or "")
        side = str(row["side"] or "")
        try:
            cur.execute(
                """
                UPDATE edge_trades
                SET last_error = '', last_action = 'open_order_reconcile', last_action_at = ?, updated_at = ?
                WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ? AND COALESCE(last_error, '') = ?
                """,
                (now_iso, now_iso, slug, event_date, outcome, side, error_text),
            )
            if cur.rowcount and cur.rowcount > 0:
                cleared += int(cur.rowcount)
        except sqlite3.OperationalError:
            continue
    if cleared:
        try:
            conn.commit()
        except sqlite3.OperationalError:
            pass
    return cleared


def fetch_open_orders(conn: sqlite3.Connection, force: bool = False) -> Tuple[List[Dict[str, Any]], str, str, int]:
    if ACCOUNT_REQUESTS_DISABLED:
        return [], "data_only", OPEN_ORDER_CACHE.get("updated_at", ""), int(OPEN_ORDER_CACHE.get("raw_count") or 0)
    if not OPEN_ORDER_SYNC_ENABLED:
        return [], "", OPEN_ORDER_CACHE.get("updated_at", ""), int(OPEN_ORDER_CACHE.get("raw_count") or 0)
    now = time.time()
    last_exec = float(OPEN_ORDER_CACHE.get("last_exec_ts") or 0.0)
    if last_exec and now - last_exec < max(1, OPEN_ORDER_MIN_INTERVAL_SEC):
        return (
            list(OPEN_ORDER_CACHE.get("data") or []),
            str(OPEN_ORDER_CACHE.get("error") or ""),
            str(OPEN_ORDER_CACHE.get("updated_at") or ""),
            int(OPEN_ORDER_CACHE.get("raw_count") or 0),
        )
    if (
        not force
        and OPEN_ORDER_CACHE.get("ts")
        and now - float(OPEN_ORDER_CACHE.get("ts") or 0.0) < OPEN_ORDER_CACHE_MAX_AGE_SEC
    ):
        return (
            list(OPEN_ORDER_CACHE.get("data") or []),
            str(OPEN_ORDER_CACHE.get("error") or ""),
            str(OPEN_ORDER_CACHE.get("updated_at") or ""),
            int(OPEN_ORDER_CACHE.get("raw_count") or 0),
        )
    if not OPEN_ORDER_SYNC_LOCK.acquire(blocking=False):
        return (
            list(OPEN_ORDER_CACHE.get("data") or []),
            str(OPEN_ORDER_CACHE.get("error") or ""),
            str(OPEN_ORDER_CACHE.get("updated_at") or ""),
            int(OPEN_ORDER_CACHE.get("raw_count") or 0),
        )
    try:
        OPEN_ORDER_CACHE["last_exec_ts"] = now
        missing = trade_sync_env_missing()
        if missing:
            OPEN_ORDER_CACHE["error"] = "缺少 " + ", ".join(missing)
            OPEN_ORDER_CACHE["updated_at"] = now_text()
            OPEN_ORDER_CACHE["ts"] = now
            OPEN_ORDER_CACHE["raw_count"] = 0
            return (
                list(OPEN_ORDER_CACHE.get("data") or []),
                str(OPEN_ORDER_CACHE.get("error") or ""),
                OPEN_ORDER_CACHE["updated_at"],
                0,
            )
        ok, payload = _run_node_open_orders()
        if not ok:
            err = str(payload.get("error") or "open_order_failed")
            detail = str(payload.get("stderr") or payload.get("stdout") or "")
            if _is_errno24_error_text(err):
                OPEN_ORDER_CACHE["updated_at"] = now_text()
                OPEN_ORDER_CACHE["ts"] = now
                return (
                    list(OPEN_ORDER_CACHE.get("data") or []),
                    "",
                    OPEN_ORDER_CACHE["updated_at"],
                    int(OPEN_ORDER_CACHE.get("raw_count") or 0),
                )
            if (
                _is_exec_timeout_error_text(err)
                or _is_exec_timeout_error_text(detail)
                or _is_upstream_5xx_error_text(err)
                or _is_upstream_5xx_error_text(detail)
            ):
                cached_data = list(OPEN_ORDER_CACHE.get("data") or [])
                if not cached_data:
                    cached_data = compute_open_order_list_local(conn, limit=80)
                    OPEN_ORDER_CACHE["data"] = cached_data
                    OPEN_ORDER_CACHE["raw_count"] = len(cached_data)
                OPEN_ORDER_CACHE["error"] = ""
                OPEN_ORDER_CACHE["updated_at"] = now_text()
                OPEN_ORDER_CACHE["ts"] = now
                return (
                    cached_data,
                    "",
                    OPEN_ORDER_CACHE["updated_at"],
                    int(OPEN_ORDER_CACHE.get("raw_count") or 0),
                )
            OPEN_ORDER_CACHE["error"] = f"{err}{(' ' + detail) if detail else ''}".strip()
            OPEN_ORDER_CACHE["updated_at"] = now_text()
            OPEN_ORDER_CACHE["ts"] = now
            OPEN_ORDER_CACHE["raw_count"] = 0
            return (
                list(OPEN_ORDER_CACHE.get("data") or []),
                OPEN_ORDER_CACHE["error"],
                OPEN_ORDER_CACHE["updated_at"],
                0,
            )
        orders_raw = payload.get("open_orders")
        if orders_raw is None:
            orders_raw = payload.get("orders") or payload.get("data")
        orders = orders_raw if isinstance(orders_raw, list) else []
        OPEN_ORDER_CACHE["raw_count"] = len(orders)
        mapped = map_open_orders(conn, orders)
        active_order_ids: set[str] = set()
        for order in orders:
            if not isinstance(order, dict):
                continue
            order_id = str(order.get("id") or order.get("orderID") or order.get("orderId") or order.get("order_id") or "").strip()
            if order_id:
                active_order_ids.add(order_id)
        for row in mapped:
            if not isinstance(row, dict):
                continue
            order_id = str(row.get("last_order_id") or row.get("order_id") or row.get("id") or "").strip()
            if order_id:
                active_order_ids.add(order_id)
        reconcile_stale_open_order_blockers(conn, active_order_ids)
        reconcile_stale_trade_blockers(conn, trade_sync_status=load_trade_sync_status())
        OPEN_ORDER_CACHE["data"] = mapped
        OPEN_ORDER_CACHE["error"] = ""
        OPEN_ORDER_CACHE["updated_at"] = now_text()
        OPEN_ORDER_CACHE["ts"] = now
        return mapped, "", OPEN_ORDER_CACHE["updated_at"], len(orders)
    finally:
        OPEN_ORDER_SYNC_LOCK.release()


def map_open_orders(conn: sqlite3.Connection, orders: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not orders:
        return []
    token_map = build_token_map_latest_runs(conn)
    if not token_map:
        return []
    event_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}
    open_orders: List[Dict[str, Any]] = []
    for order in orders:
        if not isinstance(order, dict):
            continue
        token_id = (
            order.get("asset_id")
            or order.get("assetId")
            or order.get("tokenID")
            or order.get("tokenId")
            or order.get("token_id")
            or order.get("token")
        )
        if not token_id:
            continue
        mapping = token_map.get(str(token_id))
        if not mapping:
            continue
        order_side = str(order.get("side") or "").upper()
        if not order_side:
            order_side = "BUY"
        slug = mapping["slug"]
        event_date = mapping["event_date"]
        outcome = mapping["outcome"]
        side = mapping["side"]
        key = (slug, event_date)
        if key not in event_cache:
            event_cache[key] = _latest_event_meta_from_facts(conn, slug, event_date)
        cached = event_cache[key]
        price = to_float(order.get("price"))
        size_raw = to_float(order.get("original_size") or order.get("originalSize") or order.get("size"))
        matched = to_float(order.get("size_matched") or order.get("sizeMatched"))
        size = size_raw
        if size_raw is not None and matched is not None:
            size = max(size_raw - matched, 0.0)
        if size is None or not math.isfinite(size) or size <= 0:
            continue
        created_at = _parse_open_order_time(order.get("created_at") or order.get("createdAt"))
        open_orders.append(
            {
                "slug": slug,
                "event_date": event_date,
                "outcome": outcome,
                "side": side,
                "trade_side": order_side,
                "state": "entry",
                "entry_price": price,
                "entry_size": size,
                "last_order_id": str(order.get("id") or order.get("orderID") or order.get("orderId") or ""),
                "last_status": str(order.get("status") or ""),
                "last_error": "",
                "last_action_at": created_at,
                "updated_at": created_at,
                "event_url": cached.get("event_url", ""),
                "title": cached.get("title", ""),
                "city": cached.get("city", ""),
                "station_id": cached.get("station_id", ""),
                "event_tz": cached.get("event_tz", "UTC"),
                "event_end_utc": cached.get("event_end_utc", ""),
                "settlement_actual": cached.get("settlement_actual", None),
                "market_closed": cached.get("market_closed", 0),
                "market_var": cached.get("market_var", ""),
                "resolution_source": cached.get("resolution_source", ""),
                "market_top_label": cached.get("market_top_label", ""),
                "market_unit": cached.get("market_unit", ""),
            }
        )
    open_orders.sort(
        key=lambda item: parse_iso_ts(str(item.get("last_action_at") or "")) or datetime.min,
        reverse=True,
    )
    return open_orders


def build_token_map_latest_runs(conn: sqlite3.Connection) -> Dict[str, Dict[str, str]]:
    token_map: Dict[str, Dict[str, str]] = {}
    seen: set[Tuple[str, str]] = set()
    try:
        ensure_fact_tables(conn)
    except Exception:
        return {}
    cur = conn.cursor()
    cur.execute(
        """
        SELECT h.slug, h.event_date, h.fact_json
        FROM event_fact_latest l
        JOIN event_fact_history h ON h.id = l.fact_id
        ORDER BY h.fact_as_of DESC, h.id DESC
        """
    )
    for row in cur.fetchall():
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        if not slug or not event_date:
            continue
        key = (slug, event_date)
        if key in seen:
            continue
        seen.add(key)
        fact = safe_json_loads(row["fact_json"])
        if not isinstance(fact, dict):
            continue
        rows_payload = fact.get("distribution") or fact.get("rows") or []
        if not isinstance(rows_payload, list):
            continue
        for item in rows_payload:
            if not isinstance(item, dict):
                continue
            outcome = str(item.get("outcome") or "")
            if not outcome:
                continue
            yes_token = item.get("yes_token")
            no_token = item.get("no_token")
            if yes_token:
                token_map[str(yes_token)] = {
                    "slug": slug,
                    "event_date": event_date,
                    "outcome": outcome,
                    "side": "YES",
                }
            if no_token:
                token_map[str(no_token)] = {
                    "slug": slug,
                    "event_date": event_date,
                    "outcome": outcome,
                    "side": "NO",
                }
    return token_map


def _allow_insecure_ssl() -> bool:
    raw = os.environ.get("PM_SCAN_ALLOW_INSECURE_SSL") or os.environ.get("PM_SCAN_INSECURE") or ""
    return raw.strip().lower() in {"1", "true", "yes", "on"}


def _fetch_json(url: str, headers: Optional[Dict[str, str]] = None, timeout: int = 20) -> Dict[str, Any]:
    req_headers = headers or {}
    verify_candidates: List[Any] = []
    if _allow_insecure_ssl():
        verify_candidates.append(False)
    else:
        verify_candidates.extend([certifi.where(), True, False])
    data = ""
    last_exc: Optional[Exception] = None
    for verify in verify_candidates:
        try:
            resp = requests.get(url, headers=req_headers, timeout=timeout, verify=verify)
            resp.raise_for_status()
            data = resp.text
            last_exc = None
            break
        except Exception as exc:
            last_exc = exc
            continue
    if last_exc is not None:
        raise last_exc
    try:
        parsed = json.loads(data)
    except json.JSONDecodeError:
        return {"_raw": data}
    return parsed if isinstance(parsed, dict) else {"_data": parsed}


def _extract_positions_list(payload: Any) -> List[Any]:
    if isinstance(payload, list):
        return payload
    if not isinstance(payload, dict):
        return []
    for key in ("positions", "data", "result", "items", "rows", "results"):
        value = payload.get(key)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            for subkey in ("positions", "items", "rows", "results"):
                subval = value.get(subkey)
                if isinstance(subval, list):
                    return subval
            edges = value.get("edges")
            if isinstance(edges, list):
                nodes = []
                for edge in edges:
                    if isinstance(edge, dict) and isinstance(edge.get("node"), dict):
                        nodes.append(edge["node"])
                if nodes:
                    return nodes
    data = payload.get("_data")
    if isinstance(data, list):
        return data
    return []


def _positions_api_url() -> str:
    if not POSITIONS_API_URL:
        return ""
    addr = os.environ.get("PM_FUNDER_ADDRESS") or ""
    if "{address}" in POSITIONS_API_URL:
        return POSITIONS_API_URL.replace("{address}", addr)
    if addr and "address=" not in POSITIONS_API_URL and "user=" not in POSITIONS_API_URL:
        sep = "&" if "?" in POSITIONS_API_URL else "?"
        return f"{POSITIONS_API_URL}{sep}user={addr}"
    return POSITIONS_API_URL


def fetch_positions_cache(conn: sqlite3.Connection, force: bool = False) -> Tuple[Dict[Tuple[str, str, str, str], Dict[str, Any]], str, str]:
    if ACCOUNT_REQUESTS_DISABLED:
        return {}, "data_only", str(POSITIONS_CACHE.get("updated_at") or "")
    if not POSITIONS_SYNC_ENABLED or not POSITIONS_API_URL:
        return {}, "", str(POSITIONS_CACHE.get("updated_at") or "")
    now = time.time()
    if (
        not force
        and POSITIONS_CACHE.get("ts")
        and now - float(POSITIONS_CACHE.get("ts") or 0.0) < POSITIONS_CACHE_MAX_AGE_SEC
    ):
        return dict(POSITIONS_CACHE.get("positions") or {}), str(POSITIONS_CACHE.get("error") or ""), str(POSITIONS_CACHE.get("updated_at") or "")
    if not POSITIONS_SYNC_LOCK.acquire(blocking=False):
        return dict(POSITIONS_CACHE.get("positions") or {}), str(POSITIONS_CACHE.get("error") or ""), str(POSITIONS_CACHE.get("updated_at") or "")
    try:
        url = _positions_api_url()
        if not url:
            POSITIONS_CACHE["error"] = "missing_positions_url"
            POSITIONS_CACHE["updated_at"] = now_text()
            POSITIONS_CACHE["ts"] = now
            return {}, POSITIONS_CACHE["error"], POSITIONS_CACHE["updated_at"]
        headers = {"User-Agent": "Mozilla/5.0"}
        if POSITIONS_API_AUTH:
            headers["Authorization"] = POSITIONS_API_AUTH
        elif POSITIONS_API_KEY:
            headers["X-API-KEY"] = POSITIONS_API_KEY
        payload = _fetch_json(url, headers=headers, timeout=POSITIONS_SYNC_TIMEOUT)
        positions = _extract_positions_list(payload)
        token_map = build_token_map_latest_runs(conn)
        slug_latest: Dict[str, str] = {}
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT h.slug, h.event_date, h.fact_as_of
                FROM event_fact_latest l
                JOIN event_fact_history h ON h.id = l.fact_id
                ORDER BY h.fact_as_of DESC, h.id DESC
                """
            )
            for row in cur.fetchall():
                slug = str(row[0] if isinstance(row, tuple) else row["slug"] or "")
                if not slug or slug in slug_latest:
                    continue
                event_date = str(row[1] if isinstance(row, tuple) else row["event_date"] or "")
                if event_date:
                    slug_latest[slug] = event_date
        except sqlite3.OperationalError:
            slug_latest = {}
        def _parse_bool(value: Any) -> Optional[bool]:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                try:
                    return bool(int(value))
                except Exception:
                    return None
            text = str(value or "").strip().lower()
            if not text:
                return None
            if text in {"1", "true", "yes", "on", "y"}:
                return True
            if text in {"0", "false", "no", "off", "n"}:
                return False
            return None

        mapped: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        for entry in positions:
            if not isinstance(entry, dict):
                continue
            token_id = (
                entry.get("token_id")
                or entry.get("tokenId")
                or entry.get("asset_id")
                or entry.get("assetId")
                or entry.get("asset")
                or entry.get("token")
                or entry.get("clobTokenId")
            )
            mapping = token_map.get(str(token_id)) if token_id else None
            slug = ""
            event_date = ""
            outcome = ""
            side = ""
            if mapping:
                slug = mapping["slug"]
                event_date = mapping["event_date"]
                outcome = mapping["outcome"]
                side = mapping["side"]
            else:
                market = entry.get("market") if isinstance(entry.get("market"), dict) else {}
                slug = str(
                    entry.get("slug")
                    or entry.get("market_slug")
                    or entry.get("eventSlug")
                    or entry.get("event_slug")
                    or entry.get("question_slug")
                    or market.get("slug")
                    or market.get("eventSlug")
                    or market.get("event_slug")
                    or market.get("question_slug")
                    or ""
                )
                event_date = str(
                    entry.get("event_date")
                    or entry.get("eventDate")
                    or entry.get("endDate")
                    or entry.get("end_date")
                    or entry.get("event_date_utc")
                    or entry.get("eventDateUtc")
                    or market.get("event_date")
                    or market.get("eventDate")
                    or market.get("endDate")
                    or market.get("end_date")
                    or ""
                )
                outcome = str(
                    entry.get("outcome")
                    or entry.get("outcome_name")
                    or entry.get("outcomeName")
                    or entry.get("bucket")
                    or ""
                )
                side = str(
                    entry.get("side")
                    or entry.get("outcome_side")
                    or entry.get("outcomeSide")
                    or ""
                )
                side = side.strip().upper()
                if side in {"Y", "YES", "LONG", "BUY"}:
                    side = "YES"
                elif side in {"N", "NO", "SHORT", "SELL"}:
                    side = "NO"
                if event_date and "T" in event_date:
                    event_date = event_date.split("T")[0]
                if not event_date and slug:
                    event_date = slug_latest.get(slug, "")
            if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
                continue
            size = to_float(
                entry.get("size")
                or entry.get("position_size")
                or entry.get("balance")
                or entry.get("quantity")
                or entry.get("shares")
            )
            if size is None or size <= 0:
                continue
            avg_price = to_float(
                entry.get("avg_price")
                or entry.get("average_price")
                or entry.get("avgPrice")
                or entry.get("entry_price")
                or entry.get("cost_basis")
                or entry.get("avg_cost")
                or entry.get("averageCost")
            )
            if avg_price is None:
                total_cost = to_float(entry.get("total_cost") or entry.get("cost") or entry.get("notional"))
                if total_cost is not None and size:
                    avg_price = total_cost / size
            market = entry.get("market") if isinstance(entry.get("market"), dict) else {}
            redeemable = _parse_bool(entry.get("redeemable"))
            if redeemable is None:
                redeemable = _parse_bool(market.get("redeemable"))
            end_date = date_only(
                str(
                    entry.get("endDate")
                    or entry.get("end_date")
                    or entry.get("eventDate")
                    or entry.get("event_date")
                    or market.get("endDate")
                    or market.get("end_date")
                    or market.get("eventDate")
                    or market.get("event_date")
                    or event_date
                )
            )
            event_slug = str(
                entry.get("eventSlug")
                or entry.get("event_slug")
                or market.get("eventSlug")
                or market.get("event_slug")
                or slug
            )
            key = (slug, event_date, outcome, side)
            mapped[key] = {
                "position_size": size,
                "size": size,
                "avg_price": avg_price,
                "avgPrice": avg_price,
                "redeemable": redeemable,
                "end_date": end_date or event_date,
                "endDate": end_date or event_date,
                "event_slug": event_slug or slug,
                "eventSlug": event_slug or slug,
            }
        POSITIONS_CACHE["positions"] = mapped
        POSITIONS_CACHE["error"] = ""
        POSITIONS_CACHE["updated_at"] = now_text()
        POSITIONS_CACHE["ts"] = now
        return mapped, "", POSITIONS_CACHE["updated_at"]
    except Exception as exc:
        POSITIONS_CACHE["error"] = f"{exc}"
        POSITIONS_CACHE["updated_at"] = now_text()
        POSITIONS_CACHE["ts"] = now
        return dict(POSITIONS_CACHE.get("positions") or {}), POSITIONS_CACHE["error"], POSITIONS_CACHE["updated_at"]
    finally:
        POSITIONS_SYNC_LOCK.release()


def format_bucket_tag(label: str) -> str:
    if not label or not scan_parse_outcome_label:
        return ""
    try:
        spec = scan_parse_outcome_label(label)
    except Exception:
        return ""
    unit = spec.unit or ""
    if spec.kind == "range" and spec.k2 is not None:
        return f"{spec.k:g}-{spec.k2:g}{unit}"
    if spec.kind == "le":
        return f"≤{spec.k:g}{unit}"
    if spec.kind == "ge":
        return f"≥{spec.k:g}{unit}"
    return f"{spec.k:g}{unit}"


def parse_iso_ts(value: str) -> Optional[datetime]:
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=None)


def parse_any_ts(value: str) -> Optional[datetime]:
    """Parse either ISO timestamps or `now_text()` format."""
    if not value:
        return None
    dt = parse_iso_ts(value)
    if dt is not None:
        if dt.tzinfo is None:
            try:
                local_tz = datetime.now().astimezone().tzinfo
                if local_tz is not None:
                    return dt.replace(tzinfo=local_tz)
            except Exception:
                pass
        return dt
    text = str(value).strip()
    if not text:
        return None
    try:
        naive = datetime.strptime(text, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None
    # Interpret as local time.
    try:
        local_tz = datetime.now().astimezone().tzinfo
        return naive.replace(tzinfo=local_tz)
    except Exception:
        return naive


def compute_auto_trade_daily_stats(
    conn: sqlite3.Connection,
    *,
    lightweight: bool = False,
) -> Dict[str, Any]:
    now_local = datetime.now().astimezone()
    local_tz = now_local.tzinfo
    cutoff = stats_cutoff_date()
    cutoff_text = cutoff.isoformat() if cutoff else ""
    cur = conn.cursor()
    today = now_local.date()
    today_source = "local"
    stats_today_mode = os.environ.get("PM_STATS_TODAY_MODE", "local").strip().lower()
    if stats_today_mode in {"run_date", "scan", "latest"}:
        try:
            try:
                ensure_fact_tables(conn)
                cur.execute("SELECT MAX(run_date) as run_date FROM event_fact_history")
            except Exception:
                cur.execute("SELECT MAX(run_date) as run_date FROM event_runs")
            row = cur.fetchone()
            run_date = ""
            if row is not None:
                try:
                    run_date = str(row["run_date"] or "")
                except (KeyError, TypeError, IndexError):
                    run_date = str(row[0] or "")
            run_dt = parse_date(run_date)
            if run_dt:
                today = run_dt
                today_source = "run_date"
        except sqlite3.OperationalError:
            pass
    buy_count = 0
    sell_count = 0
    buy_count_total = 0
    sell_count_total = 0
    buy_count_7d = 0
    sell_count_7d = 0
    buy_amount = 0.0
    buy_amount_7d = 0.0
    odds_sum_total = 0.0
    odds_count_total = 0
    odds_sum_7d = 0.0
    odds_count_7d = 0
    odds_sum_today = 0.0
    odds_count_today = 0
    total_buy_amount = 0.0
    fill_count = 0
    fill_count_7d = 0
    fill_count_today = 0
    filled_order_ids: Set[str] = set()
    filled_order_ids_7d: Set[str] = set()
    filled_order_ids_today: Set[str] = set()
    trade_ids: Set[str] = set()
    trade_ids_7d: Set[str] = set()
    trade_ids_today: Set[str] = set()
    buy_trade_ids: Set[str] = set()
    buy_trade_ids_7d: Set[str] = set()
    buy_trade_ids_today: Set[str] = set()
    sell_trade_ids: Set[str] = set()
    sell_trade_ids_7d: Set[str] = set()
    sell_trade_ids_today: Set[str] = set()
    auto_order_ids: Set[str] = set()
    auto_order_keys: Set[Tuple[str, str, str, str]] = set()
    inferred_auto_keys: Set[Tuple[str, str, str, str]] = set()
    mirror_follow_order_ids: Set[str] = set()
    mirror_follow_keys: Set[Tuple[str, str, str, str]] = set()
    buy_totals: Dict[Tuple[str, str, str, str], Tuple[float, float]] = {}
    sell_totals: Dict[Tuple[str, str, str, str], Tuple[float, float]] = {}
    key_first_buy_date: Dict[Tuple[str, str, str, str], date] = {}
    key_entry_date_hint: Dict[Tuple[str, str, str, str], date] = {}
    key_open_cost: Dict[Tuple[str, str, str, str], float] = {}
    key_unrealized_pnl: Dict[Tuple[str, str, str, str], float] = {}
    sell_today_qty: Dict[Tuple[str, str, str, str], float] = {}
    sell_last_date: Dict[Tuple[str, str, str, str], date] = {}
    sell_fills: List[Dict[str, Any]] = []
    order_strategy_map: Dict[str, str] = {}
    key_strategy_map: Dict[Tuple[str, str, str, str], str] = {}
    key_strategy_created_at: Dict[Tuple[str, str, str, str], str] = {}
    today_filled_events_map: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    strict_mirror_follow = bool(STATS_STRICT_MIRROR_FOLLOW)
    stats_scope = "mirror_follow_strict" if strict_mirror_follow else "auto_managed"
    if lightweight:
        position_sync_error_local = str(POSITIONS_CACHE.get("error") or "")
        position_sync_at_local = str(POSITIONS_CACHE.get("updated_at") or "")
        if ACCOUNT_REQUESTS_DISABLED:
            position_truth_source = "data_only_local"
            if not position_sync_error_local:
                position_sync_error_local = "account_requests_disabled"
        elif not POSITIONS_SYNC_ENABLED:
            position_truth_source = "edge_trades_local_sync_disabled"
            if not position_sync_error_local:
                position_sync_error_local = "positions_sync_disabled"
        elif not POSITIONS_API_URL:
            position_truth_source = "edge_trades_local_missing_url"
            if not position_sync_error_local:
                position_sync_error_local = "missing_positions_url"
        elif position_sync_error_local:
            position_truth_source = "edge_trades_local_sync_error"
        else:
            position_truth_source = "positions_api_funder"
        out = {
            "stats_today": today.isoformat(),
            "stats_today_source": today_source,
            "stats_scope": stats_scope,
            "stats_start_date": cutoff_text,
        }
        open_count = 0
        try:
            cur.execute(
                """
                SELECT COUNT(1)
                FROM edge_trades
                WHERE COALESCE(position_size, 0) > 0
                """
            )
            row = cur.fetchone()
            if row:
                try:
                    open_count = int(row[0] or 0)
                except (TypeError, ValueError):
                    open_count = 0
        except sqlite3.OperationalError:
            open_count = 0
        out["open_position_count"] = open_count
        out["open_position_count_all"] = open_count
        out["open_position_total_count"] = open_count
        out["open_position_redeemable_count"] = 0
        out["open_position_redeemable_events"] = []
        out["open_position_count_7d"] = open_count
        out["open_position_count_today"] = 0
        out["position_truth_source"] = position_truth_source
        out["position_sync_error"] = position_sync_error_local
        out["position_sync_at"] = position_sync_at_local
        out["order_count"] = 0
        out["order_count_7d"] = 0
        out["order_count_today"] = 0
        out["buy_count_total"] = 0
        out["buy_count_7d"] = 0
        out["today_buy_count"] = 0
        out["sell_count_total"] = 0
        out["sell_count_7d"] = 0
        out["today_sell_count"] = 0
        out["fill_count"] = 0
        out["fill_count_7d"] = 0
        out["fill_count_today"] = 0
        out["filled_order_count"] = 0
        out["filled_order_count_7d"] = 0
        out["filled_order_count_today"] = 0
        out["active_positions"] = open_count
        out["realized_pnl"] = 0.0
        out["unrealized_pnl"] = 0.0
        out["successful_trade_count"] = 0
        out["successful_trade_count_7d"] = 0
        out["successful_trade_count_today"] = 0
        out["failed_trade_count"] = 0
        out["failed_trade_count_7d"] = 0
        out["failed_trade_count_today"] = 0
        out["break_even_trade_count"] = 0
        out["break_even_trade_count_7d"] = 0
        out["break_even_trade_count_today"] = 0
        out["completed_trade_count"] = 0
        out["completed_trade_count_7d"] = 0
        out["completed_trade_count_today"] = 0
        out["total_roi"] = None
        out["net_roi"] = None
        out["net_roi_7d"] = None
        out["net_roi_today"] = None
        out["marginal_roi_curve_7d"] = []
        out["marginal_roi_latest_7d"] = None
        out["marginal_roi_median_7d"] = None
        out["marginal_balance_day_7d"] = ""
        out["marginal_balance_cost_7d"] = None
        out["marginal_balance_pnl_7d"] = None
        out["marginal_balance_key_count_7d"] = 0
        out["marginal_avg_buy_usdc_7d"] = None
        out["marginal_recommended_order_usdc_7d"] = None
        out["marginal_recommended_order_basis_7d"] = ""
        out["lcb_global_summary"] = {
            "start_date": cutoff_text,
            "open_position_count": open_count,
            "completed_order_count": 0,
            "completed_success_count": 0,
            "completed_failed_count": 0,
            "completed_break_even_count": 0,
            "realized_pnl": 0.0,
            "unrealized_pnl": 0.0,
            "roi": None,
            "net_roi": None,
        }
        out["total_pnl"] = 0.0
        out["last_updated"] = ""
        return out
    try:
        auto_orders_sql = """
            SELECT order_id, slug, event_date, outcome, side, strategy, action, created_at
            FROM auto_orders
            WHERE order_id IS NOT NULL AND order_id != ''
        """
        auto_orders_params: List[Any] = []
        if strict_mirror_follow:
            auto_orders_sql += " AND LOWER(COALESCE(strategy, '')) = 'mirror_follow'"
        if cutoff_text:
            auto_orders_sql += " AND created_at >= ?"
            auto_orders_params.append(cutoff_text)
        cur.execute(auto_orders_sql, auto_orders_params)
        for row in cur.fetchall():
            oid = str(row["order_id"] or "")
            strategy = str(row["strategy"] or "").strip()
            action = str(row["action"] or "").strip().lower()
            created_at = str(row["created_at"] or "")
            if oid:
                auto_order_ids.add(oid)
                if strategy:
                    order_strategy_map[oid] = strategy
            slug = str(row["slug"] or "")
            event_date = date_only(str(row["event_date"] or ""))
            outcome = str(row["outcome"] or "")
            side = str(row["side"] or "")
            if slug and event_date and outcome and side:
                key = (slug, event_date, outcome, side)
                auto_order_keys.add(key)
                if strategy:
                    prev_ts = key_strategy_created_at.get(key, "")
                    prev_strategy = key_strategy_map.get(key, "")
                    prev_is_exit = str(prev_strategy or "").strip().lower() == "exit"
                    curr_is_exit = action == "exit" or str(strategy).strip().lower() == "exit"
                    if (
                        not prev_ts
                        or created_at > prev_ts
                        or (created_at == prev_ts and prev_is_exit and not curr_is_exit)
                    ):
                        key_strategy_created_at[key] = created_at
                        key_strategy_map[key] = strategy
    except sqlite3.OperationalError:
        auto_order_ids = set()
        auto_order_keys = set()
        order_strategy_map = {}
        key_strategy_map = {}
        key_strategy_created_at = {}

    # Mirror chain SSOT: backfill order_id/key ownership from mirror_follow_trades,
    # so stats stay strict-to-chain even when auto_orders linkage is missing.
    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, outcome_side, mirror_order_id
            FROM mirror_follow_trades
            WHERE LOWER(COALESCE(mirror_status, '')) = 'placed'
            """
        )
        for row in cur.fetchall():
            slug = str(row["slug"] or "")
            event_date = date_only(str(row["event_date"] or ""))
            outcome = str(row["outcome"] or "")
            side = str(row["outcome_side"] or "")
            key = (slug, event_date, outcome, side)
            if all(key):
                mirror_follow_keys.add(key)
                if key not in key_strategy_map:
                    key_strategy_map[key] = "mirror_follow"
            oid = str(row["mirror_order_id"] or "").strip()
            if oid:
                mirror_follow_order_ids.add(oid)
                auto_order_ids.add(oid)
                if oid not in order_strategy_map:
                    order_strategy_map[oid] = "mirror_follow"
    except sqlite3.OperationalError:
        mirror_follow_order_ids = set()
        mirror_follow_keys = set()

    inferred_auto_keys = set(auto_order_keys)

    def _looks_auto_managed_trade(last_status: str, last_action: str) -> bool:
        status = str(last_status or "").strip().lower()
        action = str(last_action or "").strip().lower()
        if status.startswith(("entry_", "exit_", "open_order_", "reconcile_")):
            return True
        if action in {
            "entry",
            "entry_skip",
            "entry_order",
            "entry_retry",
            "exit",
            "exit_skip",
            "exit_order",
            "exit_retry",
            "blocker_reconcile",
        }:
            return True
        if status in {"no_balance"}:
            return True
        return False

    if not strict_mirror_follow:
        # 补齐“已纳入自动交易管理但 auto_orders 缺失”的历史 key/order_id，避免统计漏算。
        try:
            cur.execute(
                """
                SELECT slug, event_date, outcome, side, last_order_id, last_status, last_action
                FROM edge_trades
                WHERE COALESCE(position_size, 0) > 0
                """
            )
            for row in cur.fetchall():
                if not _looks_auto_managed_trade(str(row["last_status"] or ""), str(row["last_action"] or "")):
                    continue
                key = (
                    str(row["slug"] or ""),
                    str(row["event_date"] or ""),
                    str(row["outcome"] or ""),
                    str(row["side"] or ""),
                )
                if all(key):
                    inferred_auto_keys.add(key)
                oid = str(row["last_order_id"] or "")
                if oid:
                    auto_order_ids.add(oid)
        except sqlite3.OperationalError:
            pass

    def _is_auto_fill(order_id: str, trade_id: str, key: Tuple[str, str, str, str]) -> bool:
        if strict_mirror_follow:
            return bool(order_id and order_id in auto_order_ids)
        if order_id and order_id in auto_order_ids:
            return True
        if trade_id and trade_id.startswith("residual_clear:"):
            return True
        # Keep fills aligned by contract key when order_id linkage is missing.
        return key in inferred_auto_keys

    def _today_bucket_for_key(key: Tuple[str, str, str, str]) -> Dict[str, Any]:
        bucket = today_filled_events_map.get(key)
        if bucket is not None:
            return bucket
        slug_key, event_date_key, outcome_key, side_key = key
        bucket = {
            "slug": slug_key,
            "event_date": event_date_key,
            "outcome": outcome_key,
            "side": side_key,
            "buy_fill_count_today": 0,
            "sell_fill_count_today": 0,
            "buy_qty_today": 0.0,
            "sell_qty_today": 0.0,
            "buy_notional_today": 0.0,
            "sell_notional_today": 0.0,
            "buy_avg_price_today": None,
            "sell_avg_price_today": None,
            "realized_pnl_today": 0.0,
            "unrealized_pnl": None,
            "total_pnl_est": None,
            "position_size": 0.0,
            "position_avg_price": None,
            "position_state": "",
            "position_active": False,
            "entry_at": "",
            "updated_at": "",
            "first_fill_at": "",
            "last_fill_at": "",
            "strategy": str(key_strategy_map.get(key) or ""),
            "strategy_candidates": [],
        }
        today_filled_events_map[key] = bucket
        return bucket

    try:
        cur.execute(
            """
            SELECT trade_id, order_id, slug, event_date, outcome, outcome_side, trade_side, price, size, trade_time, created_at
            FROM edge_trade_fills
            """
        )
        fill_rows = cur.fetchall()
        if not strict_mirror_follow:
            for row in fill_rows:
                trade_id = str(row["trade_id"] or "")
                order_id = str(row["order_id"] or "")
                if not ((order_id and order_id in auto_order_ids) or trade_id.startswith("residual_clear:")):
                    continue
                key = (
                    str(row["slug"] or ""),
                    str(row["event_date"] or ""),
                    str(row["outcome"] or ""),
                    str(row["outcome_side"] or ""),
                )
                if all(key):
                    inferred_auto_keys.add(key)
        for row in fill_rows:
            trade_id = str(row["trade_id"] or "")
            order_id = str(row["order_id"] or "")
            trade_side = str(row["trade_side"] or "").upper()
            price = to_float(row["price"])
            size = to_float(row["size"])
            if price is None or size is None:
                continue
            ts = str(row["trade_time"] or row["created_at"] or "")
            dt = parse_iso_ts(ts)
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=local_tz)
            dt_local = dt.astimezone(local_tz)
            if cutoff and dt_local.date() < cutoff:
                continue
            key = (
                str(row["slug"] or ""),
                str(row["event_date"] or ""),
                str(row["outcome"] or ""),
                str(row["outcome_side"] or ""),
            )
            if not _is_auto_fill(order_id, trade_id, key):
                continue
            if dt_local.date() == today:
                bucket = _today_bucket_for_key(key)
                fill_at = str(row["trade_time"] or row["created_at"] or "")
                if fill_at:
                    if (not bucket.get("first_fill_at")) or str(fill_at) < str(bucket.get("first_fill_at") or ""):
                        bucket["first_fill_at"] = fill_at
                    if (not bucket.get("last_fill_at")) or str(fill_at) > str(bucket.get("last_fill_at") or ""):
                        bucket["last_fill_at"] = fill_at
                if trade_side == "BUY":
                    bucket["buy_fill_count_today"] = int(bucket.get("buy_fill_count_today") or 0) + 1
                    bucket["buy_qty_today"] = float(bucket.get("buy_qty_today") or 0.0) + float(size)
                    bucket["buy_notional_today"] = float(bucket.get("buy_notional_today") or 0.0) + float(price * size)
                elif trade_side == "SELL":
                    bucket["sell_fill_count_today"] = int(bucket.get("sell_fill_count_today") or 0) + 1
                    bucket["sell_qty_today"] = float(bucket.get("sell_qty_today") or 0.0) + float(size)
                    bucket["sell_notional_today"] = float(bucket.get("sell_notional_today") or 0.0) + float(price * size)
                strategy_now = str(order_strategy_map.get(order_id) or "").strip()
                if strategy_now:
                    cands = bucket.get("strategy_candidates")
                    if not isinstance(cands, list):
                        cands = []
                    if strategy_now not in cands:
                        cands.append(strategy_now)
                    bucket["strategy_candidates"] = cands
            if trade_id:
                trade_ids.add(trade_id)
                if dt_local.date() == today:
                    trade_ids_today.add(trade_id)
                if dt_local.date() >= (today - timedelta(days=6)):
                    trade_ids_7d.add(trade_id)
            if order_id:
                filled_order_ids.add(order_id)
                if dt_local.date() == today:
                    filled_order_ids_today.add(order_id)
                if dt_local.date() >= (today - timedelta(days=6)):
                    filled_order_ids_7d.add(order_id)
            fill_count += 1
            if dt_local.date() == today:
                fill_count_today += 1
            if dt_local.date() >= (today - timedelta(days=6)):
                fill_count_7d += 1
            if trade_side == "BUY":
                if trade_id:
                    buy_trade_ids.add(trade_id)
                    if dt_local.date() == today:
                        buy_trade_ids_today.add(trade_id)
                    if dt_local.date() >= (today - timedelta(days=6)):
                        buy_trade_ids_7d.add(trade_id)
                cost, qty = buy_totals.get(key, (0.0, 0.0))
                buy_totals[key] = (cost + price * size, qty + size)
                buy_date = dt_local.date()
                first_buy = key_first_buy_date.get(key)
                if first_buy is None or buy_date < first_buy:
                    key_first_buy_date[key] = buy_date
                total_buy_amount += price * size
                if 0 < price < 1:
                    odds_sum_total += (1 - price) / price
                    odds_count_total += 1
                if dt_local.date() == today:
                    buy_amount += price * size
                    if 0 < price < 1:
                        odds_sum_today += (1 - price) / price
                        odds_count_today += 1
                if dt_local.date() >= (today - timedelta(days=6)):
                    buy_amount_7d += price * size
                    if 0 < price < 1:
                        odds_sum_7d += (1 - price) / price
                        odds_count_7d += 1
            elif trade_side == "SELL":
                if trade_id:
                    sell_trade_ids.add(trade_id)
                    if dt_local.date() == today:
                        sell_trade_ids_today.add(trade_id)
                    if dt_local.date() >= (today - timedelta(days=6)):
                        sell_trade_ids_7d.add(trade_id)
                proceeds, qty = sell_totals.get(key, (0.0, 0.0))
                sell_totals[key] = (proceeds + price * size, qty + size)
                last_date = sell_last_date.get(key)
                sell_date = dt_local.date()
                if last_date is None or sell_date > last_date:
                    sell_last_date[key] = sell_date
                if dt_local.date() == today:
                    sell_count += 1
                    sell_today_qty[key] = sell_today_qty.get(key, 0.0) + size
                if dt_local.date() >= (today - timedelta(days=6)):
                    sell_count_7d += 1
                if trade_id:
                    sell_fills.append(
                        {
                            "trade_id": trade_id,
                            "key": key,
                            "price": price,
                            "size": size,
                            "date": dt_local.date(),
                        }
                    )
    except sqlite3.OperationalError:
        return {}
    for key, bucket in today_filled_events_map.items():
        buy_qty_today_val = to_float(bucket.get("buy_qty_today")) or 0.0
        sell_qty_today_val = to_float(bucket.get("sell_qty_today")) or 0.0
        buy_notional_today_val = to_float(bucket.get("buy_notional_today")) or 0.0
        sell_notional_today_val = to_float(bucket.get("sell_notional_today")) or 0.0
        if buy_qty_today_val > 0:
            bucket["buy_avg_price_today"] = buy_notional_today_val / buy_qty_today_val
        if sell_qty_today_val > 0:
            bucket["sell_avg_price_today"] = sell_notional_today_val / sell_qty_today_val
        if not str(bucket.get("strategy") or "").strip():
            base_strategy = str(key_strategy_map.get(key) or "").strip()
            if base_strategy:
                bucket["strategy"] = base_strategy
    realized_total = 0.0
    realized_7d = 0.0
    realized_today = 0.0
    cost_total = 0.0
    cost_7d = 0.0
    cost_today = 0.0
    failed_trade_count = 0
    failed_trade_count_7d = 0
    failed_trade_count_today = 0
    failed_trade_ids: Set[str] = set()
    failed_trade_ids_7d: Set[str] = set()
    failed_trade_ids_today: Set[str] = set()
    successful_trade_count = 0
    successful_trade_count_7d = 0
    successful_trade_count_today = 0
    successful_trade_ids: Set[str] = set()
    successful_trade_ids_7d: Set[str] = set()
    successful_trade_ids_today: Set[str] = set()
    break_even_trade_count = 0
    break_even_trade_count_7d = 0
    break_even_trade_count_today = 0
    break_even_trade_ids: Set[str] = set()
    break_even_trade_ids_7d: Set[str] = set()
    break_even_trade_ids_today: Set[str] = set()
    for key, (sell_proceeds, sell_qty) in sell_totals.items():
        buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
        if buy_qty <= 0 or sell_qty <= 0:
            continue
        avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
        matched_qty = sell_qty if sell_qty <= buy_qty else buy_qty
        realized = sell_proceeds - avg_cost * matched_qty
        realized_total += realized
        cost_total += avg_cost * matched_qty
    for entry in sell_fills:
        trade_id = str(entry.get("trade_id") or "")
        key = entry.get("key")
        if not trade_id or not key:
            continue
        buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
        if buy_qty <= 0:
            continue
        avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
        price = float(entry.get("price") or 0.0)
        size = float(entry.get("size") or 0.0)
        if size <= 0:
            continue
        realized = (price - avg_cost) * size
        if realized < -TIME_EDGE_Q_EPS:
            failed_trade_ids.add(trade_id)
            trade_date = entry.get("date")
            if trade_date == today:
                failed_trade_ids_today.add(trade_id)
            if trade_date and trade_date >= (today - timedelta(days=6)):
                failed_trade_ids_7d.add(trade_id)
        elif realized > TIME_EDGE_Q_EPS:
            successful_trade_ids.add(trade_id)
            trade_date = entry.get("date")
            if trade_date == today:
                successful_trade_ids_today.add(trade_id)
            if trade_date and trade_date >= (today - timedelta(days=6)):
                successful_trade_ids_7d.add(trade_id)
        else:
            break_even_trade_ids.add(trade_id)
            trade_date = entry.get("date")
            if trade_date == today:
                break_even_trade_ids_today.add(trade_id)
            if trade_date and trade_date >= (today - timedelta(days=6)):
                break_even_trade_ids_7d.add(trade_id)
    failed_trade_count = len(failed_trade_ids)
    failed_trade_count_7d = len(failed_trade_ids_7d)
    failed_trade_count_today = len(failed_trade_ids_today)
    successful_trade_count = len(successful_trade_ids)
    successful_trade_count_7d = len(successful_trade_ids_7d)
    successful_trade_count_today = len(successful_trade_ids_today)
    break_even_trade_count = len(break_even_trade_ids)
    break_even_trade_count_7d = len(break_even_trade_ids_7d)
    break_even_trade_count_today = len(break_even_trade_ids_today)
    completed_trade_count = successful_trade_count + failed_trade_count
    completed_trade_count_7d = successful_trade_count_7d + failed_trade_count_7d
    completed_trade_count_today = successful_trade_count_today + failed_trade_count_today
    for entry in sell_fills:
        key = entry.get("key")
        if not key:
            continue
        buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
        if buy_qty <= 0:
            continue
        avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
        price = float(entry.get("price") or 0.0)
        size = float(entry.get("size") or 0.0)
        if size <= 0:
            continue
        pnl = (price - avg_cost) * size
        trade_date = entry.get("date")
        if trade_date == today:
            realized_today += pnl
            cost_today += avg_cost * size
            bucket = today_filled_events_map.get(key)
            if isinstance(bucket, dict):
                bucket["realized_pnl_today"] = float(bucket.get("realized_pnl_today") or 0.0) + float(pnl)
        if trade_date and trade_date >= (today - timedelta(days=6)):
            realized_7d += pnl
            cost_7d += avg_cost * size
    unrealized_total = 0.0
    unrealized_7d = 0.0
    unrealized_today = 0.0
    open_cost_total = 0.0
    open_cost_7d = 0.0
    open_cost_today = 0.0
    open_position_count = 0
    open_position_count_all = 0
    open_position_total_count = 0
    open_position_redeemable_count = 0
    open_position_legacy_count = 0
    open_position_count_7d = 0
    open_position_count_today = 0
    open_position_redeemable_events_map: Dict[Tuple[str, str], Dict[str, Any]] = {}
    position_sync_error_local = ""
    position_sync_at_local = str(POSITIONS_CACHE.get("updated_at") or "")
    position_truth_source = "edge_trades_local"
    use_positions_truth = False
    position_overrides: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    if ACCOUNT_REQUESTS_DISABLED:
        position_truth_source = "data_only_local"
        position_sync_error_local = "account_requests_disabled"
    elif not POSITIONS_SYNC_ENABLED:
        position_truth_source = "edge_trades_local_sync_disabled"
        position_sync_error_local = "positions_sync_disabled"
    elif not POSITIONS_API_URL:
        position_truth_source = "edge_trades_local_missing_url"
        position_sync_error_local = "missing_positions_url"
    else:
        position_overrides, pos_err, pos_updated = fetch_positions_cache(conn)
        position_sync_error_local = str(pos_err or "")
        position_sync_at_local = str(pos_updated or position_sync_at_local)
        if position_sync_error_local:
            position_truth_source = "edge_trades_local_sync_error"
        else:
            position_truth_source = "positions_api_funder"
            use_positions_truth = True
    position_event_status: Dict[Tuple[str, str], Dict[str, Any]] = {}

    def _get_position_event_status(slug: str, event_date: str) -> Dict[str, Any]:
        key = (str(slug or ""), date_only(str(event_date or "")))
        cached = position_event_status.get(key)
        if cached is not None:
            return cached
        meta = _latest_event_meta_from_facts(conn, key[0], key[1]) if key[0] and key[1] else {}
        status = {
            "settlement_actual": to_float(meta.get("settlement_actual")) if isinstance(meta, dict) else None,
            "market_closed": int((meta or {}).get("market_closed") or 0) if isinstance(meta, dict) else 0,
        }
        position_event_status[key] = status
        return status

    def _parse_bool(value: Any) -> Optional[bool]:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            try:
                return bool(int(value))
            except Exception:
                return None
        text = str(value or "").strip().lower()
        if not text:
            return None
        if text in {"1", "true", "yes", "on", "y"}:
            return True
        if text in {"0", "false", "no", "off", "n"}:
            return False
        return None

    redeemable_meta_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}

    def _redeemable_event_meta(slug: str, event_date: str) -> Dict[str, Any]:
        key = (str(slug or ""), date_only(str(event_date or "")))
        cached = redeemable_meta_cache.get(key)
        if cached is not None:
            return cached
        meta = _latest_event_meta_from_facts(conn, key[0], key[1]) if key[0] and key[1] else {}
        payload = {
            "title": str((meta or {}).get("title") or ""),
            "event_url": str((meta or {}).get("event_url") or ""),
            "city": str((meta or {}).get("city") or ""),
            "market_top_label": str((meta or {}).get("market_top_label") or ""),
        }
        redeemable_meta_cache[key] = payload
        return payload

    try:
        cur.execute(
            """
            SELECT slug, event_date, outcome, side, state, position_size, avg_price, entry_price, mark_price, entry_at, updated_at, last_order_id
            FROM edge_trades
            """
        )
        edge_rows = cur.fetchall()
        edge_rows_by_key: Dict[Tuple[str, str, str, str], sqlite3.Row] = {}
        for row in edge_rows:
            key = (
                str(row["slug"] or ""),
                date_only(str(row["event_date"] or "")),
                str(row["outcome"] or ""),
                str(row["side"] or ""),
            )
            if all(key):
                edge_rows_by_key[key] = row

        def _is_auto_position_key(
            key: Tuple[str, str, str, str],
            row_obj: Optional[sqlite3.Row],
        ) -> bool:
            is_auto = key in mirror_follow_keys if strict_mirror_follow else key in inferred_auto_keys
            if is_auto:
                return True
            last_order_id = str((row_obj["last_order_id"] if row_obj is not None else "") or "")
            return bool(last_order_id and last_order_id in auto_order_ids)

        def _mark_redeemable_event(
            *,
            slug: str,
            event_date: str,
            outcome: str,
            side: str,
            position_size: float,
            avg_price: Optional[float],
            updated_at: str,
            event_slug: str = "",
            end_date: str = "",
        ) -> None:
            ev_key = (slug, event_date)
            existing = open_position_redeemable_events_map.get(ev_key)
            if existing is None:
                meta = _redeemable_event_meta(slug, event_date)
                existing = {
                    "slug": slug,
                    "event_date": event_date,
                    "event_slug": event_slug or slug,
                    "end_date": end_date or event_date,
                    "title": str(meta.get("title") or slug or "—"),
                    "event_url": str(meta.get("event_url") or ""),
                    "city": str(meta.get("city") or ""),
                    "market_top_label": str(meta.get("market_top_label") or ""),
                    "updated_at": updated_at,
                    "event_live_position_size": 0.0,
                    "event_live_position_count": 0,
                    "event_live_position_summary": "",
                    "legs": [],
                }
                open_position_redeemable_events_map[ev_key] = existing
            if updated_at and updated_at > str(existing.get("updated_at") or ""):
                existing["updated_at"] = updated_at
            existing["event_live_position_size"] = float(existing.get("event_live_position_size") or 0.0) + float(position_size)
            existing["event_live_position_count"] = int(existing.get("event_live_position_count") or 0) + 1
            leg = {
                "outcome": outcome,
                "side": side,
                "position_size": float(position_size),
                "avg_price": avg_price,
            }
            legs = existing.get("legs")
            if isinstance(legs, list):
                legs.append(leg)
                preview = legs[:3]
                summary = " · ".join(
                    f"{str(x.get('outcome') or '')} {str(x.get('side') or '')} {float(x.get('position_size') or 0.0):.3f}".strip()
                    for x in preview
                ).strip(" ·")
                total_count = int(existing.get("event_live_position_count") or 0)
                if total_count > len(preview):
                    summary = f"{summary} · +{total_count - len(preview)} legs" if summary else f"{total_count} legs"
                existing["event_live_position_summary"] = summary

        if use_positions_truth:
            for key, pos_entry in position_overrides.items():
                slug, event_date_raw, outcome, side = key
                event_date = date_only(str(event_date_raw or ""))
                if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
                    continue
                key_norm = (slug, event_date, outcome, side)
                pos = to_float(pos_entry.get("position_size"))
                if pos is None:
                    pos = to_float(pos_entry.get("size"))
                if pos is None or not math.isfinite(pos) or pos <= TIME_EDGE_Q_EPS:
                    continue
                row = edge_rows_by_key.get(key_norm)
                if not _is_auto_position_key(key_norm, row):
                    continue
                redeemable = bool(_parse_bool(pos_entry.get("redeemable")))
                avg_override = to_float(pos_entry.get("avg_price"))
                if avg_override is None:
                    avg_override = to_float(pos_entry.get("avgPrice"))
                status = _get_position_event_status(slug, event_date)
                is_settled = status.get("settlement_actual") is not None
                is_closed = int(status.get("market_closed") or 0) == 1
                event_date_obj = parse_date(event_date)
                legacy_cutoff = today - timedelta(days=STATS_OPEN_POSITION_LEGACY_GRACE_DAYS)
                legacy_by_date = bool(event_date_obj and event_date_obj <= legacy_cutoff)
                bucket = today_filled_events_map.get(key_norm)
                if redeemable:
                    open_position_redeemable_count += 1
                    open_position_total_count += 1
                    if isinstance(bucket, dict):
                        bucket["position_redeemable"] = True
                        bucket["position_active"] = False
                        bucket["position_size"] = float(pos)
                    _mark_redeemable_event(
                        slug=slug,
                        event_date=event_date,
                        outcome=outcome,
                        side=side,
                        position_size=float(pos),
                        avg_price=avg_override,
                        updated_at=str(pos_entry.get("updated_at") or (row["updated_at"] if row is not None else "") or ""),
                        event_slug=str(pos_entry.get("event_slug") or pos_entry.get("eventSlug") or slug),
                        end_date=str(pos_entry.get("end_date") or pos_entry.get("endDate") or event_date),
                    )
                    continue
                if is_settled or legacy_by_date:
                    open_position_legacy_count += 1
                    if isinstance(bucket, dict):
                        bucket["position_active"] = False
                    continue
                if not isinstance(bucket, dict):
                    bucket = _today_bucket_for_key(key_norm)
                open_position_count += 1
                open_position_total_count += 1
                buy_cost, buy_qty = buy_totals.get(key_norm, (0.0, 0.0))
                avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
                if avg_cost <= 0 and avg_override is not None and math.isfinite(avg_override):
                    avg_cost = float(avg_override)
                position_cost = (avg_cost * float(pos)) if (avg_cost > 0 and math.isfinite(avg_cost)) else 0.0
                if position_cost > 0:
                    open_cost_total += position_cost
                    key_open_cost[key_norm] = float(key_open_cost.get(key_norm) or 0.0) + float(position_cost)
                mark = to_float(row["mark_price"]) if row is not None else None
                if mark is None:
                    mark = avg_override
                if mark is None and row is not None:
                    mark = to_float(row["avg_price"])
                if mark is None and row is not None:
                    mark = to_float(row["entry_price"])
                pnl = None
                if mark is not None and avg_cost > 0:
                    pnl = (mark - avg_cost) * float(pos)
                    unrealized_total += pnl
                    key_unrealized_pnl[key_norm] = float(pnl)
                entry_at_raw = str((row["entry_at"] if row is not None else "") or "")
                entry_at = parse_iso_ts(entry_at_raw) if entry_at_raw else None
                if entry_at is not None:
                    if entry_at.tzinfo is None:
                        entry_at = entry_at.replace(tzinfo=local_tz)
                    entry_local = entry_at.astimezone(local_tz)
                    if pnl is not None:
                        if entry_local.date() == today:
                            unrealized_today += pnl
                        if entry_local.date() >= (today - timedelta(days=6)):
                            unrealized_7d += pnl
                    entry_date = entry_local.date()
                    key_entry_date_hint[key_norm] = entry_date
                    if entry_date == today:
                        open_position_count_today += 1
                        if position_cost > 0:
                            open_cost_today += position_cost
                    if entry_date >= (today - timedelta(days=6)):
                        open_position_count_7d += 1
                        if position_cost > 0:
                            open_cost_7d += position_cost
                avg_cost_bucket = avg_override
                if avg_cost_bucket is None and row is not None:
                    avg_cost_bucket = to_float(row["avg_price"])
                if avg_cost_bucket is None and row is not None:
                    avg_cost_bucket = to_float(row["entry_price"])
                mark_bucket = mark if mark is not None else avg_cost_bucket
                bucket["position_size"] = float(pos)
                bucket["position_state"] = "entry"
                bucket["position_redeemable"] = False
                bucket["market_closed"] = bool(is_closed)
                bucket["settled"] = bool(is_settled)
                bucket["position_avg_price"] = avg_cost_bucket
                bucket["entry_at"] = entry_at_raw
                bucket["updated_at"] = str(pos_entry.get("updated_at") or (row["updated_at"] if row is not None else "") or "")
                if (
                    avg_cost_bucket is not None
                    and math.isfinite(avg_cost_bucket)
                    and mark_bucket is not None
                    and math.isfinite(mark_bucket)
                ):
                    bucket["unrealized_pnl"] = (mark_bucket - avg_cost_bucket) * float(pos)
                else:
                    bucket["unrealized_pnl"] = None
                bucket["position_active"] = True
        else:
            for row in edge_rows:
                pos = to_float(row["position_size"]) or 0.0
                if pos <= 0:
                    continue
                slug = str(row["slug"] or "")
                event_date = date_only(str(row["event_date"] or ""))
                outcome = str(row["outcome"] or "")
                side = str(row["side"] or "")
                key = (slug, event_date, outcome, side)
                if not _is_auto_position_key(key, row):
                    continue
                bucket = today_filled_events_map.get(key)
                event_date_obj = parse_date(event_date)
                status = _get_position_event_status(slug, event_date)
                is_settled = status.get("settlement_actual") is not None
                is_closed = int(status.get("market_closed") or 0) == 1
                legacy_cutoff = today - timedelta(days=STATS_OPEN_POSITION_LEGACY_GRACE_DAYS)
                legacy_by_date = bool(event_date_obj and event_date_obj <= legacy_cutoff)
                if is_settled or legacy_by_date:
                    open_position_legacy_count += 1
                    if isinstance(bucket, dict):
                        bucket["position_active"] = False
                    continue
                if not isinstance(bucket, dict):
                    bucket = _today_bucket_for_key(key)
                open_position_count += 1
                open_position_total_count += 1
                buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
                avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
                if avg_cost <= 0:
                    avg_cost = 0.0
                position_cost = (avg_cost * pos) if (avg_cost > 0 and math.isfinite(avg_cost)) else 0.0
                if position_cost > 0:
                    open_cost_total += position_cost
                    key_open_cost[key] = float(key_open_cost.get(key) or 0.0) + float(position_cost)
                mark = to_float(row["mark_price"])
                if mark is None:
                    mark = to_float(row["avg_price"])
                if mark is None:
                    mark = to_float(row["entry_price"])
                if mark is not None and avg_cost > 0:
                    pnl = (mark - avg_cost) * pos
                    unrealized_total += pnl
                    key_unrealized_pnl[key] = float(pnl)
                entry_at = parse_iso_ts(str(row["entry_at"] or "")) if "entry_at" in row.keys() else None
                if entry_at is not None:
                    if entry_at.tzinfo is None:
                        entry_at = entry_at.replace(tzinfo=local_tz)
                    entry_local = entry_at.astimezone(local_tz)
                    if mark is not None and avg_cost > 0:
                        if entry_local.date() == today:
                            unrealized_today += pnl
                        if entry_local.date() >= (today - timedelta(days=6)):
                            unrealized_7d += pnl
                    entry_date = entry_local.date()
                    key_entry_date_hint[key] = entry_date
                    if entry_date == today:
                        open_position_count_today += 1
                        if position_cost > 0:
                            open_cost_today += position_cost
                    if entry_date >= (today - timedelta(days=6)):
                        open_position_count_7d += 1
                        if position_cost > 0:
                            open_cost_7d += position_cost
                avg_cost_bucket = to_float(row["avg_price"])
                if avg_cost_bucket is None:
                    avg_cost_bucket = to_float(row["entry_price"])
                mark_bucket = to_float(row["mark_price"])
                if mark_bucket is None:
                    mark_bucket = avg_cost_bucket
                pos_bucket = to_float(row["position_size"]) or 0.0
                bucket["position_size"] = pos_bucket
                bucket["position_state"] = str(row["state"] or "")
                bucket["position_redeemable"] = False
                bucket["market_closed"] = bool(is_closed)
                bucket["settled"] = bool(is_settled)
                bucket["position_avg_price"] = avg_cost_bucket
                bucket["entry_at"] = str(row["entry_at"] or "")
                bucket["updated_at"] = str(row["updated_at"] or "")
                if (
                    avg_cost_bucket is not None
                    and math.isfinite(avg_cost_bucket)
                    and mark_bucket is not None
                    and math.isfinite(mark_bucket)
                    and pos_bucket > 0
                ):
                    bucket["unrealized_pnl"] = (mark_bucket - avg_cost_bucket) * pos_bucket
                else:
                    bucket["unrealized_pnl"] = None
                bucket["position_active"] = bool(pos > 0)
    except sqlite3.OperationalError:
        pass
    open_position_count_all = open_position_total_count
    open_position_redeemable_events = list(open_position_redeemable_events_map.values())

    def _redeemable_sort_ts(item: Dict[str, Any]) -> float:
        dt = parse_any_ts(str(item.get("updated_at") or ""))
        if isinstance(dt, datetime):
            return float(dt.timestamp())
        return 0.0

    open_position_redeemable_events.sort(
        key=lambda item: (
            -_redeemable_sort_ts(item),
            str(item.get("event_date") or ""),
            str(item.get("slug") or ""),
        )
    )
    today_filled_events: List[Dict[str, Any]] = []
    if today_filled_events_map:
        event_meta_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}

        def _resolve_event_meta(slug_key: str, event_date_key: str) -> Dict[str, Any]:
            cache_key = (slug_key, event_date_key)
            cached = event_meta_cache.get(cache_key)
            if cached is not None:
                return cached
            meta = _latest_event_meta_from_facts(conn, slug_key, event_date_key)
            payload = {
                "title": str(meta.get("title") or ""),
                "event_url": str(meta.get("event_url") or ""),
                "city": str(meta.get("city") or ""),
                "market_top_label": str(meta.get("market_top_label") or ""),
            }
            event_meta_cache[cache_key] = payload
            return payload

        def _pick_strategy(base_value: str, candidates: List[str]) -> str:
            base = str(base_value or "").strip()
            if base and base.lower() != "exit":
                return base
            if base:
                return base
            for cand in candidates:
                c = str(cand or "").strip()
                if c and c.lower() != "exit":
                    return c
            for cand in candidates:
                c = str(cand or "").strip()
                if c:
                    return c
            return ""

        for key, bucket in today_filled_events_map.items():
            slug_key, event_date_key, _outcome_key, _side_key = key
            buy_qty_today_val = to_float(bucket.get("buy_qty_today")) or 0.0
            sell_qty_today_val = to_float(bucket.get("sell_qty_today")) or 0.0
            buy_notional_today_val = to_float(bucket.get("buy_notional_today")) or 0.0
            sell_notional_today_val = to_float(bucket.get("sell_notional_today")) or 0.0
            buy_avg_today_val = to_float(bucket.get("buy_avg_price_today"))
            if buy_qty_today_val > 0 and (buy_avg_today_val is None or not math.isfinite(buy_avg_today_val)):
                bucket["buy_avg_price_today"] = buy_notional_today_val / buy_qty_today_val
            sell_avg_today_val = to_float(bucket.get("sell_avg_price_today"))
            if sell_qty_today_val > 0 and (
                sell_avg_today_val is None or not math.isfinite(sell_avg_today_val)
            ):
                bucket["sell_avg_price_today"] = sell_notional_today_val / sell_qty_today_val
            strategy_candidates = [
                str(item).strip()
                for item in (bucket.get("strategy_candidates") or [])
                if str(item or "").strip()
            ]
            bucket["strategy"] = _pick_strategy(str(bucket.get("strategy") or ""), strategy_candidates)
            bucket["strategy_candidates"] = strategy_candidates
            position_size_val = to_float(bucket.get("position_size")) or 0.0
            bucket["position_active"] = bool(position_size_val > 0 and not bool(bucket.get("position_redeemable")))
            realized_today_val = to_float(bucket.get("realized_pnl_today"))
            unrealized_val = to_float(bucket.get("unrealized_pnl"))
            total_pnl_est = None
            if realized_today_val is not None and math.isfinite(realized_today_val):
                total_pnl_est = float(realized_today_val)
            if unrealized_val is not None and math.isfinite(unrealized_val):
                total_pnl_est = (total_pnl_est or 0.0) + float(unrealized_val)
            bucket["total_pnl_est"] = total_pnl_est
            meta = _resolve_event_meta(slug_key, event_date_key)
            bucket["title"] = str(meta.get("title") or slug_key or "—")
            bucket["event_url"] = str(meta.get("event_url") or "")
            bucket["city"] = str(meta.get("city") or "")
            bucket["market_top_label"] = str(meta.get("market_top_label") or "")
            today_filled_events.append(bucket)

        def _event_sort_ts(item: Dict[str, Any]) -> float:
            ts_vals: List[float] = []
            for key_name in ("updated_at", "last_fill_at", "first_fill_at", "entry_at"):
                dt = parse_iso_ts(str(item.get(key_name) or ""))
                if dt is not None:
                    ts_vals.append(float(dt.timestamp()))
            if ts_vals:
                return max(ts_vals)
            return 0.0

        today_filled_events.sort(
            key=lambda item: (
                0 if bool(item.get("position_active")) else 1,
                -_event_sort_ts(item),
                str(item.get("slug") or ""),
            )
        )
    mirror_follow_today: Dict[str, Any] = {
        "stats_today": today.isoformat(),
        "rows": [],
        "count": 0,
        "placed": 0,
        "failed": 0,
        "skipped": 0,
        "sync": {},
    }
    if today_filled_events:
        today_filled_events_map_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        for row in today_filled_events:
            key = (
                str(row.get("slug") or ""),
                date_only(str(row.get("event_date") or "")),
                str(row.get("outcome") or ""),
                str(row.get("side") or ""),
            )
            if all(key):
                today_filled_events_map_by_key[key] = row
    else:
        today_filled_events_map_by_key = {}
    try:
        cur.execute(
            """
            SELECT source_address, source_trade_id, source_side, source_price, source_size, source_notional, source_ts,
                   slug, event_date, outcome, outcome_side,
                   mirror_price, mirror_size, mirror_order_id, mirror_status, mirror_error, created_at
            FROM mirror_follow_trades
            ORDER BY COALESCE(source_ts, 0) DESC, created_at DESC
            LIMIT 240
            """
        )
        mirror_rows_raw = cur.fetchall()
        mirror_rows: List[Dict[str, Any]] = []
        order_ids: List[str] = []
        configured_source_address = str(os.environ.get("PM_MIRROR_SOURCE_ADDRESS") or "").strip().lower()
        source_address_target = configured_source_address
        if not source_address_target:
            for row in mirror_rows_raw:
                source_addr_guess = str(row["source_address"] or "").strip().lower()
                if source_addr_guess:
                    source_address_target = source_addr_guess
                    break
        source_trade_today_count = 0
        for row in mirror_rows_raw:
            source_addr = str(row["source_address"] or "").strip().lower()
            if source_address_target and source_addr and source_addr != source_address_target:
                continue
            created_at = str(row["created_at"] or "")
            created_dt = parse_iso_ts(created_at)
            if created_dt is not None and created_dt.tzinfo is None:
                created_dt = created_dt.replace(tzinfo=timezone.utc)
            if created_dt is None and created_at:
                created_dt = parse_any_ts(created_at)
            if created_dt is not None:
                try:
                    created_local = created_dt.astimezone(local_tz)
                except Exception:
                    created_local = created_dt
                if created_local.date() != today:
                    continue
            source_trade_today_count += 1
            source_ts = int(row["source_ts"] or 0)
            source_at = ""
            if source_ts > 0:
                try:
                    source_at = datetime.fromtimestamp(source_ts, tz=timezone.utc).isoformat(timespec="seconds")
                except (ValueError, OSError):
                    source_at = ""
            slug = str(row["slug"] or "")
            event_date = date_only(str(row["event_date"] or ""))
            outcome = str(row["outcome"] or "")
            side = str(row["outcome_side"] or "")
            key = (slug, event_date, outcome, side)
            event_meta = _latest_event_meta_from_facts(conn, slug, event_date) if slug and event_date else {}
            fill_bucket = today_filled_events_map_by_key.get(key) or {}
            mirror_order_id = str(row["mirror_order_id"] or "")
            if mirror_order_id:
                order_ids.append(mirror_order_id)
            mirror_rows.append(
                {
                    "source_trade_id": str(row["source_trade_id"] or ""),
                    "source_side": str(row["source_side"] or ""),
                    "source_price": to_float(row["source_price"]),
                    "source_size": to_float(row["source_size"]),
                    "source_notional": to_float(row["source_notional"]),
                    "source_ts": source_ts,
                    "source_at": source_at,
                    "slug": slug,
                    "event_date": event_date,
                    "outcome": outcome,
                    "side": side,
                    "mirror_price": to_float(row["mirror_price"]),
                    "mirror_size": to_float(row["mirror_size"]),
                    "mirror_order_id": mirror_order_id,
                    "mirror_status": str(row["mirror_status"] or ""),
                    "mirror_error": str(row["mirror_error"] or ""),
                    "created_at": created_at,
                    "title": str(event_meta.get("title") or slug or "—"),
                    "event_url": str(event_meta.get("event_url") or ""),
                    "city": str(event_meta.get("city") or ""),
                    "market_top_label": str(event_meta.get("market_top_label") or ""),
                    "realized_pnl_est": to_float(fill_bucket.get("realized_pnl_today")),
                    "unrealized_pnl_est": to_float(fill_bucket.get("unrealized_pnl")),
                    "total_pnl_est": to_float(fill_bucket.get("total_pnl_est")),
                    "position_size": to_float(fill_bucket.get("position_size")),
                    "position_active": bool(fill_bucket.get("position_active")),
                    "fill_count": 0,
                    "fill_qty": 0.0,
                    "fill_avg_price": None,
                    "last_fill_at": "",
                }
            )
        source_trade_total = 0
        latest_source_ts = 0
        latest_created_at = ""
        latest_mirror_created_at = ""
        latest_mirror_status = ""
        latest_mirror_error = ""
        source_open_keys_count = 0
        mirror_open_keys_count = 0
        matched_open_keys_count = 0
        source_only_open_keys_count = 0
        mirror_only_open_keys_count = 0
        source_to_mirror_lag_sec = None
        sync_update_age_sec = None
        source_latest_trade_at = ""
        if source_address_target:
            try:
                cur.execute(
                    """
                    SELECT COUNT(1), MAX(COALESCE(source_ts, 0)), MAX(COALESCE(created_at, ''))
                    FROM mirror_follow_trades
                    WHERE LOWER(COALESCE(source_address, '')) = ?
                    """,
                    (source_address_target,),
                )
                stats_row = cur.fetchone()
                if stats_row:
                    source_trade_total = int(stats_row[0] or 0)
                    latest_source_ts = int(stats_row[1] or 0)
                    latest_created_at = str(stats_row[2] or "")
            except sqlite3.OperationalError:
                source_trade_total = 0
                latest_source_ts = 0
                latest_created_at = ""
            try:
                cur.execute(
                    """
                    SELECT created_at, mirror_status, mirror_error
                    FROM mirror_follow_trades
                    WHERE LOWER(COALESCE(source_address, '')) = ?
                    ORDER BY COALESCE(source_ts, 0) DESC, created_at DESC
                    LIMIT 1
                    """,
                    (source_address_target,),
                )
                last_row = cur.fetchone()
                if last_row:
                    latest_mirror_created_at = str(last_row[0] or "")
                    latest_mirror_status = str(last_row[1] or "")
                    latest_mirror_error = str(last_row[2] or "")
            except sqlite3.OperationalError:
                latest_mirror_created_at = ""
                latest_mirror_status = ""
                latest_mirror_error = ""
            source_net_by_key: Dict[Tuple[str, str, str, str], float] = {}
            try:
                cur.execute(
                    """
                    SELECT slug, event_date, outcome, outcome_side,
                           SUM(
                               CASE UPPER(COALESCE(source_side, ''))
                                   WHEN 'BUY' THEN COALESCE(source_size, 0)
                                   WHEN 'SELL' THEN -COALESCE(source_size, 0)
                                   ELSE 0
                               END
                           ) AS source_net
                    FROM mirror_follow_trades
                    WHERE LOWER(COALESCE(source_address, '')) = ?
                    GROUP BY slug, event_date, outcome, outcome_side
                    """,
                    (source_address_target,),
                )
                for source_row in cur.fetchall():
                    key = (
                        str(source_row[0] or ""),
                        date_only(str(source_row[1] or "")),
                        str(source_row[2] or ""),
                        str(source_row[3] or ""),
                    )
                    net_val = to_float(source_row[4]) or 0.0
                    if not all(key):
                        continue
                    source_net_by_key[key] = float(net_val)
            except sqlite3.OperationalError:
                source_net_by_key = {}
            source_open_keys = {
                key for key, net_val in source_net_by_key.items()
                if net_val > 1e-9
            }
            tracked_keys = set(source_net_by_key.keys())
            mirror_open_keys: Set[Tuple[str, str, str, str]] = set()
            if tracked_keys:
                try:
                    cur.execute(
                        """
                        SELECT slug, event_date, outcome, side, MAX(COALESCE(position_size, 0))
                        FROM edge_trades
                        WHERE COALESCE(position_size, 0) > 0
                        GROUP BY slug, event_date, outcome, side
                        """
                    )
                    for mirror_pos_row in cur.fetchall():
                        key = (
                            str(mirror_pos_row[0] or ""),
                            date_only(str(mirror_pos_row[1] or "")),
                            str(mirror_pos_row[2] or ""),
                            str(mirror_pos_row[3] or ""),
                        )
                        if key not in tracked_keys:
                            continue
                        pos_val = to_float(mirror_pos_row[4]) or 0.0
                        if pos_val > 1e-9:
                            mirror_open_keys.add(key)
                except sqlite3.OperationalError:
                    mirror_open_keys = set()
            source_open_keys_count = len(source_open_keys)
            mirror_open_keys_count = len(mirror_open_keys)
            matched_open_keys_count = len(source_open_keys & mirror_open_keys)
            source_only_open_keys_count = len(source_open_keys - mirror_open_keys)
            mirror_only_open_keys_count = len(mirror_open_keys - source_open_keys)
            if latest_source_ts > 0:
                try:
                    source_latest_trade_at = datetime.fromtimestamp(
                        latest_source_ts, tz=timezone.utc
                    ).isoformat(timespec="seconds")
                except (ValueError, OSError):
                    source_latest_trade_at = ""
            latest_epoch = None
            if latest_created_at:
                dt_latest = parse_iso_ts(latest_created_at) or parse_any_ts(latest_created_at)
                if dt_latest is not None:
                    if dt_latest.tzinfo is None:
                        dt_latest = dt_latest.replace(tzinfo=timezone.utc)
                    latest_epoch = dt_latest.timestamp()
            if latest_epoch is not None:
                sync_update_age_sec = max(0, int(time.time() - latest_epoch))
            if latest_source_ts > 0 and latest_epoch is not None:
                source_to_mirror_lag_sec = max(0, int(latest_epoch - latest_source_ts))
        fill_map: Dict[str, Dict[str, Any]] = {}
        if order_ids:
            unique_order_ids = sorted({oid for oid in order_ids if oid})
            if unique_order_ids:
                placeholders = ",".join("?" for _ in unique_order_ids)
                cur.execute(
                    f"""
                    SELECT order_id, trade_time, created_at, price, size
                    FROM edge_trade_fills
                    WHERE order_id IN ({placeholders})
                    """,
                    tuple(unique_order_ids),
                )
                for row in cur.fetchall():
                    order_id = str(row["order_id"] or "")
                    if not order_id:
                        continue
                    bucket = fill_map.get(order_id)
                    if bucket is None:
                        bucket = {
                            "fill_count": 0,
                            "fill_qty": 0.0,
                            "fill_notional": 0.0,
                            "last_fill_at": "",
                        }
                        fill_map[order_id] = bucket
                    price = to_float(row["price"])
                    size = to_float(row["size"])
                    if price is not None and size is not None:
                        bucket["fill_qty"] += float(size)
                        bucket["fill_notional"] += float(price * size)
                    bucket["fill_count"] = int(bucket.get("fill_count") or 0) + 1
                    ts = str(row["trade_time"] or row["created_at"] or "")
                    if ts and ts > str(bucket.get("last_fill_at") or ""):
                        bucket["last_fill_at"] = ts
        placed = 0
        failed = 0
        skipped = 0
        for row in mirror_rows:
            status = str(row.get("mirror_status") or "").strip().lower()
            if status == "placed":
                placed += 1
            elif status == "failed":
                failed += 1
            else:
                skipped += 1
            order_id = str(row.get("mirror_order_id") or "")
            fill_info = fill_map.get(order_id) if order_id else None
            if isinstance(fill_info, dict):
                fill_qty = float(fill_info.get("fill_qty") or 0.0)
                fill_notional = float(fill_info.get("fill_notional") or 0.0)
                row["fill_count"] = int(fill_info.get("fill_count") or 0)
                row["fill_qty"] = fill_qty
                row["fill_avg_price"] = (fill_notional / fill_qty) if fill_qty > 0 else None
                row["last_fill_at"] = str(fill_info.get("last_fill_at") or "")
        sync_status = "no_data"
        sync_status_text = "暂无跟随账户交易样本"
        if source_trade_total > 0:
            sync_status = "ok"
            sync_status_text = "已同步"
            if source_only_open_keys_count > 0 or mirror_only_open_keys_count > 0:
                sync_status = "mismatch"
                sync_status_text = "持仓未完全对齐"
            if sync_update_age_sec is not None and sync_update_age_sec > 900:
                sync_status = "stale"
                sync_status_text = "同步更新偏旧"
        mirror_follow_today = {
            "stats_today": today.isoformat(),
            "rows": mirror_rows,
            "count": len(mirror_rows),
            "placed": placed,
            "failed": failed,
            "skipped": skipped,
            "source_address": source_address_target,
            "source_trade_today": source_trade_today_count,
            "source_trade_total": source_trade_total,
            "source_latest_trade_at": source_latest_trade_at,
            "latest_created_at": latest_created_at,
            "latest_mirror_created_at": latest_mirror_created_at,
            "latest_mirror_status": latest_mirror_status,
            "latest_mirror_error": latest_mirror_error,
            "source_to_mirror_lag_sec": source_to_mirror_lag_sec,
            "sync_update_age_sec": sync_update_age_sec,
            "source_open_keys": source_open_keys_count,
            "mirror_open_keys": mirror_open_keys_count,
            "matched_open_keys": matched_open_keys_count,
            "source_only_open_keys": source_only_open_keys_count,
            "mirror_only_open_keys": mirror_only_open_keys_count,
            "sync": {
                "status": sync_status,
                "status_text": sync_status_text,
                "source_address": source_address_target,
                "source_trade_today": source_trade_today_count,
                "source_trade_total": source_trade_total,
                "source_latest_trade_at": source_latest_trade_at,
                "latest_created_at": latest_created_at,
                "latest_mirror_created_at": latest_mirror_created_at,
                "latest_mirror_status": latest_mirror_status,
                "latest_mirror_error": latest_mirror_error,
                "source_to_mirror_lag_sec": source_to_mirror_lag_sec,
                "sync_update_age_sec": sync_update_age_sec,
                "source_open_keys": source_open_keys_count,
                "mirror_open_keys": mirror_open_keys_count,
                "matched_open_keys": matched_open_keys_count,
                "source_only_open_keys": source_only_open_keys_count,
                "mirror_only_open_keys": mirror_only_open_keys_count,
            },
        }
        # Source account non-trade ops (CONVERSION / MERGE / REDEEM) from activity feed.
        # These ops do not trigger mirror-follow orders; they are shown for visibility/debugging.
        source_ops_counts: Dict[str, int] = {}
        source_ops_recent: List[Dict[str, Any]] = []
        source_ops_latest_at = ""
        if source_address_target:
            try:
                cur.execute(
                    """
                    SELECT op_type, ts, tx_hash, slug, event_slug, title, size, usdc_size
                    FROM mirror_source_activity_ops
                    WHERE LOWER(COALESCE(source_address, '')) = ?
                    ORDER BY COALESCE(ts, 0) DESC, id DESC
                    LIMIT 30
                    """,
                    (str(source_address_target).strip().lower(),),
                )
                for row in cur.fetchall():
                    op_type = str(row["op_type"] or "").strip().upper()
                    ts = int(row["ts"] or 0)
                    if op_type:
                        source_ops_counts[op_type] = int(source_ops_counts.get(op_type) or 0) + 1
                    if ts > 0 and not source_ops_latest_at:
                        try:
                            source_ops_latest_at = datetime.fromtimestamp(ts, tz=timezone.utc).isoformat(
                                timespec="seconds"
                            )
                        except Exception:
                            source_ops_latest_at = ""
                    source_ops_recent.append(
                        {
                            "op_type": op_type,
                            "ts": ts,
                            "tx_hash": str(row["tx_hash"] or ""),
                            "slug": str(row["slug"] or ""),
                            "event_slug": str(row["event_slug"] or ""),
                            "title": str(row["title"] or ""),
                            "size": to_float(row["size"]),
                            "usdc_size": to_float(row["usdc_size"]),
                        }
                    )
            except sqlite3.OperationalError:
                source_ops_counts = {}
                source_ops_recent = []
                source_ops_latest_at = ""
        mirror_follow_today["source_ops_counts"] = dict(source_ops_counts)
        mirror_follow_today["source_ops_latest_at"] = source_ops_latest_at
        mirror_follow_today["source_ops_recent"] = source_ops_recent
        try:
            if isinstance(mirror_follow_today.get("sync"), dict):
                mirror_follow_today["sync"]["source_ops_counts"] = dict(source_ops_counts)
                mirror_follow_today["sync"]["source_ops_latest_at"] = source_ops_latest_at
        except Exception:
            pass
    except sqlite3.OperationalError:
        pass
    marginal_roi_curve_7d: List[Dict[str, Any]] = []
    marginal_roi_latest_7d: Optional[float] = None
    marginal_roi_median_7d: Optional[float] = None
    marginal_balance_day_7d = ""
    marginal_balance_cost_7d: Optional[float] = None
    marginal_balance_pnl_7d: Optional[float] = None
    marginal_balance_key_count_7d = 0
    seven_start = today - timedelta(days=6)
    seven_dates = [seven_start + timedelta(days=offset) for offset in range(7)]
    marginal_day_cost: Dict[date, float] = {day: 0.0 for day in seven_dates}
    marginal_day_pnl: Dict[date, float] = {day: 0.0 for day in seven_dates}
    marginal_day_keys: Dict[date, int] = {day: 0 for day in seven_dates}
    tracked_keys = (
        set(buy_totals.keys())
        | set(sell_totals.keys())
        | set(key_open_cost.keys())
        | set(key_unrealized_pnl.keys())
    )
    for key in tracked_keys:
        buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
        sell_proceeds, sell_qty = sell_totals.get(key, (0.0, 0.0))
        realized_cost_key = 0.0
        realized_pnl_key = 0.0
        if buy_qty > TIME_EDGE_Q_EPS and sell_qty > TIME_EDGE_Q_EPS:
            avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
            matched_qty = min(sell_qty, buy_qty)
            if matched_qty > TIME_EDGE_Q_EPS:
                realized_cost_key = avg_cost * matched_qty
                realized_pnl_key = sell_proceeds - realized_cost_key
        open_cost_key = float(key_open_cost.get(key) or 0.0)
        unrealized_pnl_key = float(key_unrealized_pnl.get(key) or 0.0)
        net_cost_key = realized_cost_key + open_cost_key
        if net_cost_key <= TIME_EDGE_Q_EPS:
            continue
        entry_day = key_first_buy_date.get(key)
        if entry_day is None:
            entry_day = key_entry_date_hint.get(key)
        if entry_day is None or entry_day < seven_start or entry_day > today:
            continue
        marginal_day_cost[entry_day] = float(marginal_day_cost.get(entry_day) or 0.0) + float(net_cost_key)
        marginal_day_pnl[entry_day] = float(marginal_day_pnl.get(entry_day) or 0.0) + float(
            realized_pnl_key + unrealized_pnl_key
        )
        marginal_day_keys[entry_day] = int(marginal_day_keys.get(entry_day) or 0) + 1
    cumulative_cost = 0.0
    cumulative_pnl = 0.0
    cumulative_key_count = 0
    best_balance_pnl = -float("inf")
    roi_points: List[float] = []
    for day in seven_dates:
        day_cost = float(marginal_day_cost.get(day) or 0.0)
        day_pnl = float(marginal_day_pnl.get(day) or 0.0)
        day_key_count = int(marginal_day_keys.get(day) or 0)
        day_roi = (day_pnl / day_cost) if day_cost > TIME_EDGE_Q_EPS else None
        cumulative_cost += day_cost
        cumulative_pnl += day_pnl
        cumulative_key_count += day_key_count
        cumulative_roi = (cumulative_pnl / cumulative_cost) if cumulative_cost > TIME_EDGE_Q_EPS else None
        if day_roi is not None and math.isfinite(day_roi):
            roi_points.append(float(day_roi))
            marginal_roi_latest_7d = float(day_roi)
        curve_row = {
            "date": day.isoformat(),
            "day_cost": day_cost,
            "day_pnl": day_pnl,
            "day_roi": day_roi,
            "cumulative_cost": cumulative_cost,
            "cumulative_pnl": cumulative_pnl,
            "cumulative_roi": cumulative_roi,
            "key_count": day_key_count,
            "cumulative_key_count": cumulative_key_count,
        }
        marginal_roi_curve_7d.append(curve_row)
        if cumulative_cost > TIME_EDGE_Q_EPS and cumulative_key_count > 0 and cumulative_pnl > best_balance_pnl + TIME_EDGE_Q_EPS:
            best_balance_pnl = cumulative_pnl
            marginal_balance_day_7d = str(curve_row.get("date") or "")
            marginal_balance_cost_7d = float(curve_row.get("cumulative_cost") or 0.0)
            marginal_balance_pnl_7d = float(curve_row.get("cumulative_pnl") or 0.0)
            marginal_balance_key_count_7d = int(curve_row.get("cumulative_key_count") or 0)
    if roi_points:
        sorted_points = sorted(float(v) for v in roi_points if math.isfinite(v))
        n_points = len(sorted_points)
        mid = n_points // 2
        if n_points % 2 == 1:
            marginal_roi_median_7d = float(sorted_points[mid])
        else:
            marginal_roi_median_7d = float((sorted_points[mid - 1] + sorted_points[mid]) / 2.0)
    marginal_avg_buy_usdc_7d: Optional[float] = None
    marginal_recommended_order_usdc_7d: Optional[float] = None
    marginal_recommended_order_basis_7d = ""
    avg_odds_total = odds_sum_total / odds_count_total if odds_count_total else None
    avg_odds_7d = odds_sum_7d / odds_count_7d if odds_count_7d else None
    avg_odds_today = odds_sum_today / odds_count_today if odds_count_today else None
    if avg_odds_today is None and sell_today_qty:
        weighted_sum = 0.0
        weighted_qty = 0.0
        for key, qty in sell_today_qty.items():
            if qty <= 0:
                continue
            buy_cost, buy_qty = buy_totals.get(key, (0.0, 0.0))
            if buy_qty <= 0:
                continue
            avg_cost = buy_cost / buy_qty if buy_qty > 0 else 0.0
            if avg_cost <= 0 or avg_cost >= 1:
                continue
            odds_val = (1 - avg_cost) / avg_cost
            weighted_sum += odds_val * qty
            weighted_qty += qty
        if weighted_qty > 0:
            avg_odds_today = weighted_sum / weighted_qty
    filled_order_count = len(filled_order_ids)
    filled_order_count_7d = len(filled_order_ids_7d)
    filled_order_count_today = len(filled_order_ids_today)
    buy_count_total = len(buy_trade_ids)
    buy_count_7d = len(buy_trade_ids_7d)
    buy_count = len(buy_trade_ids_today)
    sell_count_total = len(sell_trade_ids)
    sell_count_7d = len(sell_trade_ids_7d)
    sell_count = len(sell_trade_ids_today)
    total_pnl = realized_total + unrealized_total
    total_pnl_7d = realized_7d + unrealized_7d
    total_pnl_today = realized_today + unrealized_today
    roi = realized_total / cost_total if cost_total > 0 else None
    roi_7d = realized_7d / cost_7d if cost_7d > 0 else None
    roi_today = realized_today / cost_today if cost_today > 0 else None
    net_cost_total = cost_total + open_cost_total
    net_cost_7d = cost_7d + open_cost_7d
    net_cost_today = cost_today + open_cost_today
    net_roi = total_pnl / net_cost_total if net_cost_total > 0 else None
    net_roi_7d = total_pnl_7d / net_cost_7d if net_cost_7d > 0 else None
    net_roi_today = total_pnl_today / net_cost_today if net_cost_today > 0 else None
    order_count = buy_count_total
    order_count_7d = buy_count_7d
    order_count_today = buy_count
    if buy_count_7d > 0 and buy_amount_7d > TIME_EDGE_Q_EPS:
        marginal_avg_buy_usdc_7d = float(buy_amount_7d / float(buy_count_7d))
    if (
        marginal_balance_key_count_7d > 0
        and marginal_balance_cost_7d is not None
        and math.isfinite(marginal_balance_cost_7d)
        and marginal_balance_cost_7d > TIME_EDGE_Q_EPS
    ):
        marginal_recommended_order_usdc_7d = float(marginal_balance_cost_7d / float(marginal_balance_key_count_7d))
        marginal_recommended_order_basis_7d = "balance_point_7d"
    elif marginal_avg_buy_usdc_7d is not None and marginal_avg_buy_usdc_7d > TIME_EDGE_Q_EPS:
        marginal_recommended_order_usdc_7d = float(marginal_avg_buy_usdc_7d)
        marginal_recommended_order_basis_7d = "avg_buy_7d"
    missing_count = 0
    missing_examples: List[Dict[str, Any]] = []
    if not strict_mirror_follow:
        try:
            cur.execute(
                """
                WITH auto_keys AS (
                    SELECT DISTINCT slug, event_date, outcome, side
                    FROM auto_orders
                    WHERE COALESCE(slug, '') != ''
                      AND COALESCE(event_date, '') != ''
                      AND COALESCE(outcome, '') != ''
                      AND COALESCE(side, '') != ''
                ), auto_order_ids AS (
                    SELECT DISTINCT order_id
                    FROM auto_orders
                    WHERE COALESCE(order_id, '') != ''
                )
                SELECT COUNT(1) FROM (
                    SELECT f.slug, f.event_date, f.outcome, f.outcome_side
                    FROM edge_trade_fills f
                    JOIN auto_keys k
                      ON f.slug = k.slug
                     AND f.event_date = k.event_date
                     AND f.outcome = k.outcome
                     AND f.outcome_side = k.side
                    GROUP BY f.slug, f.event_date, f.outcome, f.outcome_side
                    HAVING SUM(CASE
                        WHEN f.trade_side='SELL'
                         AND f.order_id IN (SELECT order_id FROM auto_order_ids)
                        THEN f.size ELSE 0 END
                    ) >
                    SUM(CASE WHEN f.trade_side='BUY' THEN f.size ELSE 0 END) + 1e-9
                )
                """
            )
            row = cur.fetchone()
            if row:
                missing_count = int(row[0] or 0)
            if missing_count:
                cur.execute(
                    """
                    WITH auto_keys AS (
                        SELECT DISTINCT slug, event_date, outcome, side
                        FROM auto_orders
                        WHERE COALESCE(slug, '') != ''
                          AND COALESCE(event_date, '') != ''
                          AND COALESCE(outcome, '') != ''
                          AND COALESCE(side, '') != ''
                    ), auto_order_ids AS (
                        SELECT DISTINCT order_id
                        FROM auto_orders
                        WHERE COALESCE(order_id, '') != ''
                    )
                    SELECT f.slug, f.event_date, f.outcome, f.outcome_side,
                           SUM(CASE WHEN f.trade_side='BUY' THEN f.size ELSE 0 END) AS buy_qty,
                           SUM(CASE
                               WHEN f.trade_side='SELL'
                                AND f.order_id IN (SELECT order_id FROM auto_order_ids)
                               THEN f.size ELSE 0 END
                           ) AS sell_qty
                    FROM edge_trade_fills f
                    JOIN auto_keys k
                      ON f.slug = k.slug
                     AND f.event_date = k.event_date
                     AND f.outcome = k.outcome
                     AND f.outcome_side = k.side
                    GROUP BY f.slug, f.event_date, f.outcome, f.outcome_side
                    HAVING SUM(CASE
                        WHEN f.trade_side='SELL'
                         AND f.order_id IN (SELECT order_id FROM auto_order_ids)
                        THEN f.size ELSE 0 END
                    ) >
                    SUM(CASE WHEN f.trade_side='BUY' THEN f.size ELSE 0 END) + 1e-9
                    ORDER BY (
                        SUM(CASE
                            WHEN f.trade_side='SELL'
                             AND f.order_id IN (SELECT order_id FROM auto_order_ids)
                            THEN f.size ELSE 0 END
                        ) - SUM(CASE WHEN f.trade_side='BUY' THEN f.size ELSE 0 END)
                    ) DESC
                    LIMIT 5
                    """
                )
                for row in cur.fetchall():
                    missing_examples.append(
                        {
                            "slug": str(row[0] or ""),
                            "event_date": str(row[1] or ""),
                            "outcome": str(row[2] or ""),
                            "side": str(row[3] or ""),
                            "buy_qty": float(row[4] or 0.0),
                            "sell_qty": float(row[5] or 0.0),
                        }
                    )
        except sqlite3.OperationalError:
            pass
    return {
        "stats_today": today.isoformat(),
        "stats_today_source": today_source,
        "stats_scope": stats_scope,
        "stats_start_date": cutoff_text,
        "today_buy_count": buy_count,
        "today_sell_count": sell_count,
        "buy_count_total": buy_count_total,
        "sell_count_total": sell_count_total,
        "buy_count_7d": buy_count_7d,
        "sell_count_7d": sell_count_7d,
        "today_buy_amount": buy_amount,
        "buy_amount_7d": buy_amount_7d,
        "today_pnl": realized_today,
        "today_avg_odds": avg_odds_today,
        "today_roi": roi_today,
        "order_count": order_count,
        "order_count_7d": order_count_7d,
        "order_count_today": order_count_today,
        "fill_count": fill_count,
        "fill_count_7d": fill_count_7d,
        "fill_count_today": fill_count_today,
        "filled_order_count": filled_order_count,
        "filled_order_count_7d": filled_order_count_7d,
        "filled_order_count_today": filled_order_count_today,
        "active_positions": open_position_count,
        "open_position_count": open_position_count,
        "open_position_count_all": open_position_count_all,
        "open_position_total_count": open_position_total_count,
        "open_position_redeemable_count": open_position_redeemable_count,
        "open_position_redeemable_events": open_position_redeemable_events,
        "open_position_legacy_count": open_position_legacy_count,
        "open_position_legacy_grace_days": STATS_OPEN_POSITION_LEGACY_GRACE_DAYS,
        "open_position_count_7d": open_position_count_7d,
        "open_position_count_today": open_position_count_today,
        "position_truth_source": position_truth_source,
        "position_sync_error": position_sync_error_local,
        "position_sync_at": position_sync_at_local,
        "failed_trade_count": failed_trade_count,
        "failed_trade_count_7d": failed_trade_count_7d,
        "failed_trade_count_today": failed_trade_count_today,
        "successful_trade_count": successful_trade_count,
        "successful_trade_count_7d": successful_trade_count_7d,
        "successful_trade_count_today": successful_trade_count_today,
        "break_even_trade_count": break_even_trade_count,
        "break_even_trade_count_7d": break_even_trade_count_7d,
        "break_even_trade_count_today": break_even_trade_count_today,
        "completed_trade_count": completed_trade_count,
        "completed_trade_count_7d": completed_trade_count_7d,
        "completed_trade_count_today": completed_trade_count_today,
        "avg_odds": avg_odds_total,
        "avg_odds_7d": avg_odds_7d,
        "total_buy_amount": total_buy_amount,
        "realized_pnl": realized_total,
        "unrealized_pnl": unrealized_total,
        "realized_cost_total": cost_total,
        "realized_cost_7d": cost_7d,
        "realized_cost_today": cost_today,
        "total_pnl": total_pnl,
        "realized_pnl_7d": realized_7d,
        "unrealized_pnl_7d": unrealized_7d,
        "realized_pnl_today": realized_today,
        "unrealized_pnl_today": unrealized_today,
        "total_pnl_7d": total_pnl_7d,
        "total_pnl_today": total_pnl_today,
        "total_roi": roi,
        "roi_7d": roi_7d,
        "today_filled_events": today_filled_events,
        "net_roi": net_roi,
        "net_roi_7d": net_roi_7d,
        "net_roi_today": net_roi_today,
        "marginal_roi_curve_7d": marginal_roi_curve_7d,
        "marginal_roi_latest_7d": marginal_roi_latest_7d,
        "marginal_roi_median_7d": marginal_roi_median_7d,
        "marginal_balance_day_7d": marginal_balance_day_7d,
        "marginal_balance_cost_7d": marginal_balance_cost_7d,
        "marginal_balance_pnl_7d": marginal_balance_pnl_7d,
        "marginal_balance_key_count_7d": marginal_balance_key_count_7d,
        "marginal_avg_buy_usdc_7d": marginal_avg_buy_usdc_7d,
        "marginal_recommended_order_usdc_7d": marginal_recommended_order_usdc_7d,
        "marginal_recommended_order_basis_7d": marginal_recommended_order_basis_7d,
        "open_cost_total": open_cost_total,
        "open_cost_7d": open_cost_7d,
        "open_cost_today": open_cost_today,
        "mirror_follow_today": mirror_follow_today,
        "lcb_global_summary": {
            "start_date": cutoff_text,
            "open_position_count": open_position_count,
            "completed_order_count": completed_trade_count,
            "completed_success_count": successful_trade_count,
            "completed_failed_count": failed_trade_count,
            "completed_break_even_count": break_even_trade_count,
            "realized_pnl": realized_total,
            "unrealized_pnl": unrealized_total,
            "roi": roi,
            "net_roi": net_roi,
        },
        "fills_incomplete": bool(missing_count),
        "fills_incomplete_count": missing_count,
        "fills_incomplete_examples": missing_examples,
    }


def cached_auto_trade_daily_stats(conn: sqlite3.Connection) -> Dict[str, Any]:
    ttl_sec = float(AUTO_TRADE_STATUS_DAILY_CACHE_SEC)
    now_ts = time.time()
    with AUTO_TRADE_STATUS_DAILY_CACHE_LOCK:
        cached_ts = float(AUTO_TRADE_STATUS_DAILY_CACHE.get("ts") or 0.0)
        cached_payload = AUTO_TRADE_STATUS_DAILY_CACHE.get("payload")
        if (
            isinstance(cached_payload, dict)
            and cached_payload
            and now_ts - cached_ts <= ttl_sec
        ):
            return dict(cached_payload)
    try:
        payload = compute_auto_trade_daily_stats(conn, lightweight=False)
    except Exception:
        payload = compute_auto_trade_daily_stats_fast(conn)
    if not isinstance(payload, dict):
        payload = {}
    with AUTO_TRADE_STATUS_DAILY_CACHE_LOCK:
        AUTO_TRADE_STATUS_DAILY_CACHE["ts"] = now_ts
        AUTO_TRADE_STATUS_DAILY_CACHE["payload"] = dict(payload)
    return dict(payload)


def compute_auto_trade_daily_stats_fast(conn: sqlite3.Connection) -> Dict[str, Any]:
    now_local = datetime.now().astimezone()
    local_tz = now_local.tzinfo
    today = now_local.date()
    cutoff = stats_cutoff_date()
    cutoff_text = cutoff.isoformat() if cutoff else ""
    seven_start = today - timedelta(days=6)
    stats_scope = "mirror_follow_strict" if bool(STATS_STRICT_MIRROR_FOLLOW) else "auto_managed"
    position_sync_error_local = str(POSITIONS_CACHE.get("error") or "")
    position_sync_at_local = str(POSITIONS_CACHE.get("updated_at") or "")
    if ACCOUNT_REQUESTS_DISABLED:
        position_truth_source = "data_only_local"
        if not position_sync_error_local:
            position_sync_error_local = "account_requests_disabled"
    elif not POSITIONS_SYNC_ENABLED:
        position_truth_source = "edge_trades_local_sync_disabled"
        if not position_sync_error_local:
            position_sync_error_local = "positions_sync_disabled"
    elif not POSITIONS_API_URL:
        position_truth_source = "edge_trades_local_missing_url"
        if not position_sync_error_local:
            position_sync_error_local = "missing_positions_url"
    elif position_sync_error_local:
        position_truth_source = "edge_trades_local_sync_error"
    else:
        position_truth_source = "positions_api_funder"
    out: Dict[str, Any] = {
        "stats_today": today.isoformat(),
        "stats_today_source": "local",
        "stats_scope": stats_scope,
        "stats_start_date": cutoff_text,
        "today_buy_count": 0,
        "today_sell_count": 0,
        "buy_count_total": 0,
        "sell_count_total": 0,
        "buy_count_7d": 0,
        "sell_count_7d": 0,
        "order_count": 0,
        "order_count_today": 0,
        "order_count_7d": 0,
        "fill_count": 0,
        "fill_count_today": 0,
        "fill_count_7d": 0,
        "filled_order_count": 0,
        "filled_order_count_today": 0,
        "filled_order_count_7d": 0,
        "open_position_count": 0,
        "open_position_count_all": 0,
        "open_position_total_count": 0,
        "open_position_redeemable_count": 0,
        "open_position_redeemable_events": [],
        "open_position_count_7d": 0,
        "open_position_count_today": 0,
        "open_position_legacy_count": 0,
        "position_truth_source": position_truth_source,
        "position_sync_error": position_sync_error_local,
        "position_sync_at": position_sync_at_local,
        "successful_trade_count": 0,
        "successful_trade_count_7d": 0,
        "successful_trade_count_today": 0,
        "failed_trade_count": 0,
        "failed_trade_count_7d": 0,
        "failed_trade_count_today": 0,
        "break_even_trade_count": 0,
        "break_even_trade_count_7d": 0,
        "break_even_trade_count_today": 0,
        "completed_trade_count": 0,
        "completed_trade_count_7d": 0,
        "completed_trade_count_today": 0,
        "realized_pnl": 0.0,
        "unrealized_pnl": 0.0,
        "total_roi": None,
        "net_roi": None,
        "net_roi_7d": None,
        "net_roi_today": None,
        "marginal_roi_curve_7d": [],
        "marginal_roi_latest_7d": None,
        "marginal_roi_median_7d": None,
        "marginal_balance_day_7d": "",
        "marginal_balance_cost_7d": None,
        "marginal_balance_pnl_7d": None,
        "marginal_balance_key_count_7d": 0,
        "marginal_avg_buy_usdc_7d": None,
        "marginal_recommended_order_usdc_7d": None,
        "marginal_recommended_order_basis_7d": "",
        "today_filled_events": [],
        "mirror_follow_today": {"count": 0, "placed": 0, "failed": 0, "skipped": 0, "rows": [], "sync": {}},
        "lcb_global_summary": {
            "start_date": cutoff_text,
            "open_position_count": 0,
            "completed_order_count": 0,
            "completed_success_count": 0,
            "completed_failed_count": 0,
            "completed_break_even_count": 0,
            "realized_pnl": 0.0,
            "unrealized_pnl": 0.0,
            "roi": None,
            "net_roi": None,
        },
    }
    cur = conn.cursor()

    auto_order_ids: Set[str] = set()
    auto_order_keys: Set[Tuple[str, str, str, str]] = set()
    try:
        sql = """
            SELECT DISTINCT order_id, slug, event_date, outcome, side
            FROM auto_orders
            WHERE order_id IS NOT NULL AND order_id != ''
        """
        params: List[Any] = []
        if bool(STATS_STRICT_MIRROR_FOLLOW):
            sql += " AND LOWER(COALESCE(strategy, '')) = 'mirror_follow'"
        cur.execute(sql, params)
        for row in cur.fetchall():
            oid = str(row["order_id"] or "").strip()
            if oid:
                auto_order_ids.add(oid)
            key = (
                str(row["slug"] or "").strip(),
                date_only(str(row["event_date"] or "")),
                str(row["outcome"] or "").strip(),
                str(row["side"] or "").strip().upper(),
            )
            if all(key) and key[3] in {"YES", "NO"}:
                auto_order_keys.add(key)
    except sqlite3.OperationalError:
        auto_order_ids = set()
        auto_order_keys = set()

    buy_trade_ids: Set[str] = set()
    buy_trade_ids_today: Set[str] = set()
    buy_trade_ids_7d: Set[str] = set()
    sell_trade_ids: Set[str] = set()
    sell_trade_ids_today: Set[str] = set()
    sell_trade_ids_7d: Set[str] = set()
    filled_orders: Set[str] = set()
    filled_orders_today: Set[str] = set()
    filled_orders_7d: Set[str] = set()
    try:
        cur.execute(
            """
            SELECT trade_id, order_id, trade_side, trade_time, created_at
            FROM edge_trade_fills
            WHERE order_id IS NOT NULL AND order_id != ''
            """
        )
        for row in cur.fetchall():
            order_id = str(row["order_id"] or "").strip()
            if auto_order_ids and order_id not in auto_order_ids:
                continue
            ts = str(row["trade_time"] or row["created_at"] or "")
            dt = parse_iso_ts(ts)
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=local_tz)
            d = dt.astimezone(local_tz).date()
            side = str(row["trade_side"] or "").upper()
            trade_id = str(row["trade_id"] or "").strip()

            out["fill_count"] += 1
            filled_orders.add(order_id)
            if d == today:
                out["fill_count_today"] += 1
                filled_orders_today.add(order_id)
            if d >= seven_start:
                out["fill_count_7d"] += 1
                filled_orders_7d.add(order_id)

            if trade_id:
                if side == "BUY":
                    buy_trade_ids.add(trade_id)
                    if d == today:
                        buy_trade_ids_today.add(trade_id)
                    if d >= seven_start:
                        buy_trade_ids_7d.add(trade_id)
                elif side == "SELL":
                    sell_trade_ids.add(trade_id)
                    if d == today:
                        sell_trade_ids_today.add(trade_id)
                    if d >= seven_start:
                        sell_trade_ids_7d.add(trade_id)
    except sqlite3.OperationalError:
        pass

    out["buy_count_total"] = len(buy_trade_ids)
    out["sell_count_total"] = len(sell_trade_ids)
    out["today_buy_count"] = len(buy_trade_ids_today)
    out["today_sell_count"] = len(sell_trade_ids_today)
    out["buy_count_7d"] = len(buy_trade_ids_7d)
    out["sell_count_7d"] = len(sell_trade_ids_7d)
    out["order_count"] = out["buy_count_total"]
    out["order_count_today"] = out["today_buy_count"]
    out["order_count_7d"] = out["buy_count_7d"]
    out["filled_order_count"] = len(filled_orders)
    out["filled_order_count_today"] = len(filled_orders_today)
    out["filled_order_count_7d"] = len(filled_orders_7d)

    def _looks_auto_managed(last_status: str, last_action: str) -> bool:
        status = str(last_status or "").strip().lower()
        action = str(last_action or "").strip().lower()
        if status.startswith(("entry_", "exit_", "open_order_", "reconcile_")):
            return True
        if action in {
            "entry",
            "entry_skip",
            "entry_order",
            "entry_retry",
            "exit",
            "exit_skip",
            "exit_order",
            "exit_retry",
            "blocker_reconcile",
        }:
            return True
        return status in {"no_balance"}

    def _parse_bool(value: Any) -> Optional[bool]:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            try:
                return bool(int(value))
            except Exception:
                return None
        text = str(value or "").strip().lower()
        if not text:
            return None
        if text in {"1", "true", "yes", "on", "y"}:
            return True
        if text in {"0", "false", "no", "off", "n"}:
            return False
        return None

    if position_truth_source == "positions_api_funder":
        try:
            position_overrides, pos_err, pos_updated = fetch_positions_cache(conn)
            if pos_updated:
                out["position_sync_at"] = str(pos_updated)
            if not pos_err and position_overrides:
                edge_rows_by_key: Dict[Tuple[str, str, str, str], Dict[str, str]] = {}
                inferred_auto_keys: Set[Tuple[str, str, str, str]] = set(auto_order_keys)
                cur.execute(
                    """
                    SELECT slug, event_date, outcome, side, entry_at, last_order_id, last_status, last_action
                    FROM edge_trades
                    """
                )
                for row in cur.fetchall():
                    key = (
                        str(row["slug"] or "").strip(),
                        date_only(str(row["event_date"] or "")),
                        str(row["outcome"] or "").strip(),
                        str(row["side"] or "").strip().upper(),
                    )
                    if not (all(key) and key[3] in {"YES", "NO"}):
                        continue
                    row_payload = {
                        "entry_at": str(row["entry_at"] or ""),
                        "last_order_id": str(row["last_order_id"] or "").strip(),
                        "last_status": str(row["last_status"] or ""),
                        "last_action": str(row["last_action"] or ""),
                    }
                    edge_rows_by_key[key] = row_payload
                    if _looks_auto_managed(row_payload["last_status"], row_payload["last_action"]):
                        inferred_auto_keys.add(key)
                        if row_payload["last_order_id"]:
                            auto_order_ids.add(row_payload["last_order_id"])

                for raw_key, pos_entry in position_overrides.items():
                    if not (isinstance(raw_key, tuple) and len(raw_key) == 4 and isinstance(pos_entry, dict)):
                        continue
                    key = (
                        str(raw_key[0] or "").strip(),
                        date_only(str(raw_key[1] or "")),
                        str(raw_key[2] or "").strip(),
                        str(raw_key[3] or "").strip().upper(),
                    )
                    if not (all(key) and key[3] in {"YES", "NO"}):
                        continue
                    pos_val = to_float(pos_entry.get("position_size"))
                    if pos_val is None:
                        pos_val = to_float(pos_entry.get("size"))
                    if pos_val is None or not math.isfinite(pos_val) or pos_val <= TIME_EDGE_Q_EPS:
                        continue
                    row_payload = edge_rows_by_key.get(key) or {}
                    last_order_id = str(row_payload.get("last_order_id") or "").strip()
                    is_auto = key in inferred_auto_keys
                    if not is_auto and last_order_id and last_order_id in auto_order_ids:
                        is_auto = True
                    if not is_auto:
                        continue
                    out["open_position_count_all"] += 1
                    out["open_position_total_count"] += 1
                    if bool(_parse_bool(pos_entry.get("redeemable"))):
                        out["open_position_redeemable_count"] += 1
                        continue
                    out["open_position_count"] += 1
                    entry_at = parse_iso_ts(str(row_payload.get("entry_at") or ""))
                    if entry_at is None:
                        continue
                    if entry_at.tzinfo is None:
                        entry_at = entry_at.replace(tzinfo=local_tz)
                    entry_day = entry_at.astimezone(local_tz).date()
                    if entry_day == today:
                        out["open_position_count_today"] += 1
                    if entry_day >= seven_start:
                        out["open_position_count_7d"] += 1
                return out
        except sqlite3.OperationalError:
            pass
        except Exception:
            pass

    try:
        cur.execute(
            """
            SELECT position_size, entry_at, last_order_id, last_status, last_action
            FROM edge_trades
            WHERE COALESCE(position_size, 0) > 0
            """
        )
        for row in cur.fetchall():
            last_order_id = str(row["last_order_id"] or "").strip()
            last_status = str(row["last_status"] or "")
            last_action = str(row["last_action"] or "")
            if auto_order_ids:
                is_auto = (last_order_id and last_order_id in auto_order_ids) or _looks_auto_managed(last_status, last_action)
            else:
                is_auto = _looks_auto_managed(last_status, last_action)
            if not is_auto:
                continue
            out["open_position_count_all"] += 1
            out["open_position_total_count"] += 1
            out["open_position_count"] += 1
            entry_at = parse_iso_ts(str(row["entry_at"] or ""))
            if entry_at is None:
                continue
            if entry_at.tzinfo is None:
                entry_at = entry_at.replace(tzinfo=local_tz)
            entry_day = entry_at.astimezone(local_tz).date()
            if entry_day == today:
                out["open_position_count_today"] += 1
            if entry_day >= seven_start:
                out["open_position_count_7d"] += 1
    except sqlite3.OperationalError:
        pass

    out["lcb_global_summary"] = {
        "start_date": cutoff_text,
        "open_position_count": int(out.get("open_position_count") or 0),
        "completed_order_count": int(out.get("completed_trade_count") or 0),
        "completed_success_count": int(out.get("successful_trade_count") or 0),
        "completed_failed_count": int(out.get("failed_trade_count") or 0),
        "completed_break_even_count": int(out.get("break_even_trade_count") or 0),
        "realized_pnl": float(out.get("realized_pnl") or 0.0),
        "unrealized_pnl": float(out.get("unrealized_pnl") or 0.0),
        "roi": to_float(out.get("total_roi")),
    }
    return out


