def _ssot_trade_info_map(auto_trades: Any) -> Dict[Tuple[str, str], Dict[str, Any]]:
    trades = auto_trades if isinstance(auto_trades, list) else []
    out: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for trade in trades:
        if not isinstance(trade, dict):
            continue
        outcome = str(trade.get("outcome") or "")
        side = str(trade.get("side") or "").upper()
        if not outcome or side not in {"YES", "NO"}:
            continue
        fills = trade.get("fills")
        fills_count = len(fills) if isinstance(fills, list) else 0
        out[(outcome, side)] = {
            "last_order_id": str(trade.get("last_order_id") or ""),
            "last_status": str(trade.get("last_status") or ""),
            "last_error": str(trade.get("last_error") or ""),
            "state": str(trade.get("state") or ""),
            "last_action": str(trade.get("last_action") or ""),
            "position_size": trade.get("position_size"),
            "avg_price": trade.get("avg_price"),
            "mark_price": trade.get("mark_price"),
            "peak_price": trade.get("peak_price"),
            "realized_pnl": trade.get("realized_pnl"),
            "unrealized_pnl": trade.get("unrealized_pnl"),
            "entry_at": str(trade.get("entry_at") or ""),
            "last_fill_at": str(trade.get("last_fill_at") or ""),
            "updated_at": str(trade.get("updated_at") or ""),
            "exit_reasons": str(trade.get("exit_reasons") or ""),
            "exit_reason_codes": str(trade.get("exit_reason_codes") or ""),
            "exit_triggered_at": str(trade.get("exit_triggered_at") or ""),
            "exit_skip_reason": str(trade.get("exit_skip_reason") or ""),
            "exit_skip_detail": str(trade.get("exit_skip_detail") or ""),
            "exit_skip_at": str(trade.get("exit_skip_at") or ""),
            "fills_count": fills_count,
        }
    return out


def _top_label_from_distribution(distribution: Any, key: str) -> str:
    if not isinstance(distribution, list):
        return ""
    best_val: Optional[float] = None
    best_label = ""
    for drow in distribution:
        if not isinstance(drow, dict):
            continue
        label = str(drow.get("outcome") or "")
        if not label:
            continue
        q_val = to_float(drow.get(key))
        if q_val is None or not math.isfinite(q_val):
            continue
        if best_val is None or q_val > best_val:
            best_val = q_val
            best_label = label
    return best_label


def _edge_score_penalty_simple(spread: Optional[float], ask: Optional[float]) -> float:
    # Keep in sync with UI edge_scorePenalty() semantics.
    penalty = 0.0
    if spread is not None and math.isfinite(spread):
        penalty += max(0.0, (spread * 100.0 - 8.0) / 10.0)
    if ask is not None and math.isfinite(ask):
        penalty += max(0.0, (ask - 0.6) / 0.2)
    return penalty


def _edge_realizable_target_exit_cap_hint_ui(row: Dict[str, Any], side: str) -> Optional[float]:
    if not isinstance(row, dict):
        return None
    side_key = "yes" if str(side or "").strip().upper() == "YES" else "no"
    keys = (
        f"edge_realizable_delta_exit_cap_{side_key}",
        f"edge_realizable_delta_exit_p75_{side_key}",
        f"edge_realizable_delta_exit_p90_{side_key}",
        "edge_realizable_delta_exit_cap",
        "edge_realizable_delta_exit_p75",
        "edge_realizable_delta_exit_p90",
    )
    for key in keys:
        val = to_float(row.get(key))
        if val is None or not math.isfinite(val) or val <= 0:
            continue
        return float(val)
    return None


def _build_edge_realizable_target_exit_price_ui(
    *,
    exec_exit_price: Optional[float],
    exec_edge_exit: Optional[float],
    base_bid: Optional[float],
    spread: Optional[float],
    side: str,
    row: Dict[str, Any],
    headroom_min: float,
) -> Tuple[Optional[float], Dict[str, Any]]:
    meta: Dict[str, Any] = {}
    if exec_exit_price is None or not math.isfinite(exec_exit_price):
        return None, meta
    if exec_edge_exit is None or not math.isfinite(exec_edge_exit):
        return None, meta
    raw_target = float(exec_exit_price) + float(exec_edge_exit) - float(headroom_min)
    if not math.isfinite(raw_target) or raw_target <= 0:
        return None, meta
    meta["target_exit_price_raw"] = float(raw_target)
    if base_bid is None or not math.isfinite(base_bid):
        return float(raw_target), meta
    delta_raw = float(raw_target) - float(base_bid)
    if not math.isfinite(delta_raw):
        return None, meta
    meta["delta_exit_raw"] = float(delta_raw)
    min_delta = to_float(os.environ.get("PM_EDGE_REALIZABLE_TARGET_EXIT_MIN_DELTA"))
    if min_delta is None or not math.isfinite(min_delta) or min_delta < 0:
        min_delta = 0.0
    max_delta = to_float(os.environ.get("PM_EDGE_REALIZABLE_TARGET_EXIT_MAX_DELTA"))
    if max_delta is None or not math.isfinite(max_delta) or max_delta <= 0:
        max_delta = 0.06
    spread_mult = to_float(os.environ.get("PM_EDGE_REALIZABLE_TARGET_EXIT_MAX_SPREAD_MULT"))
    if spread_mult is None or not math.isfinite(spread_mult) or spread_mult <= 0:
        spread_mult = 2.0
    cap_candidates: List[float] = [float(max_delta)]
    if spread is not None and math.isfinite(spread) and spread > 0:
        cap_candidates.append(float(spread) * float(spread_mult))
    hint_cap = _edge_realizable_target_exit_cap_hint_ui(row, side)
    if hint_cap is not None and math.isfinite(hint_cap) and hint_cap > 0:
        cap_candidates.append(float(hint_cap))
        meta["delta_exit_cap_hint"] = float(hint_cap)
    delta_cap = min(cap_candidates) if cap_candidates else None
    delta_final = float(delta_raw)
    clamped = False
    if delta_final < float(min_delta):
        delta_final = float(min_delta)
        clamped = True
    if delta_cap is not None and math.isfinite(delta_cap) and delta_cap >= 0:
        if delta_final > float(delta_cap):
            delta_final = float(delta_cap)
            clamped = True
        meta["delta_exit_cap"] = float(delta_cap)
    if delta_final < 0:
        delta_final = 0.0
        clamped = True
    target = float(base_bid) + float(delta_final)
    if not math.isfinite(target) or target <= 0:
        return None, meta
    meta["target_exit_clamped"] = clamped
    meta["delta_exit"] = float(delta_final)
    meta["target_exit_price"] = float(target)
    return float(target), meta


def _ssot_candidate_from_row(
    row: Dict[str, Any],
    side: str,
    market_top_label: str,
    trade_info_map: Dict[Tuple[str, str], Dict[str, Any]],
    days_to_event: Optional[int] = None,
) -> Optional[Dict[str, Any]]:
    if not isinstance(row, dict):
        return None
    outcome = str(row.get("outcome") or "")
    if not outcome:
        return None
    side = str(side or "").upper()
    if side not in {"YES", "NO"}:
        return None
    if side == "YES":
        ask = to_float(row.get("entry_price_yes"))
        if ask is None:
            ask = to_float(row.get("best_ask"))
        if ask is None:
            ask = to_float(row.get("exec_entry_price_yes"))
        spread = to_float(row.get("spread"))
        if spread is None:
            bid_val = to_float(row.get("best_bid"))
            if bid_val is not None and ask is not None and math.isfinite(bid_val) and math.isfinite(ask):
                spread = max(float(ask) - float(bid_val), 0.0)
        lag = to_float(row.get("lag_yes"))
        edge_score = to_float(row.get("edge_score_yes"))
        exec_edge_entry = to_float(row.get("exec_edge_entry_yes"))
        exec_edge_exit = to_float(row.get("exec_edge_exit_yes"))
        exec_edge_score = to_float(row.get("exec_edge_score_yes"))
        exec_exit_price = to_float(row.get("exec_exit_price_yes"))
        edge_realizable = to_float(row.get("edge_realizable_yes"))
        edge_realizable_score_val = to_float(row.get("edge_realizable_score_yes"))
        exec_fee_cost = to_float(row.get("exec_fee_cost_yes"))
        time_factor = to_float(row.get("time_factor_yes")) or to_float(row.get("time_factor"))
        q_round = to_float(row.get("q_round"))
        q_min_bound = to_float(row.get("q_entry"))
        edge_min = to_float(row.get("signal_edge_min"))
        token_id = str(row.get("yes_token") or "")
        entry_depth_ok = row.get("entry_depth_ok_yes")
        dominance = to_float(row.get("dominance"))
        time_base = to_float(row.get("time_base_yes"))
        yes_ask = ask
        yes_q = q_min_bound
        no_ask = to_float(row.get("entry_price_no")) or to_float(row.get("best_ask_no"))
        no_q = to_float(row.get("q_entry_no"))
        penalty = to_float(row.get("penalty_yes"))
        trend_down = bool(row.get("trend_down_yes"))
        trend_unknown = bool(row.get("trend_unknown_yes"))
        trend_up = bool(row.get("trend_up_yes"))
        trend_pct = to_float(row.get("trend_pct_yes"))
        trend_consistency_up = to_float(row.get("trend_consistency_up_yes"))
    else:
        ask = to_float(row.get("entry_price_no"))
        if ask is None:
            ask = to_float(row.get("best_ask_no"))
        if ask is None:
            ask = to_float(row.get("exec_entry_price_no"))
        spread = to_float(row.get("spread_no"))
        if spread is None:
            bid_val = to_float(row.get("best_bid_no"))
            if bid_val is not None and ask is not None and math.isfinite(bid_val) and math.isfinite(ask):
                spread = max(float(ask) - float(bid_val), 0.0)
        lag = to_float(row.get("lag_no"))
        edge_score = to_float(row.get("edge_score_no"))
        exec_edge_entry = to_float(row.get("exec_edge_entry_no"))
        exec_edge_exit = to_float(row.get("exec_edge_exit_no"))
        exec_edge_score = to_float(row.get("exec_edge_score_no"))
        exec_exit_price = to_float(row.get("exec_exit_price_no"))
        edge_realizable = to_float(row.get("edge_realizable_no"))
        edge_realizable_score_val = to_float(row.get("edge_realizable_score_no"))
        exec_fee_cost = to_float(row.get("exec_fee_cost_no"))
        time_factor = to_float(row.get("time_factor_no")) or to_float(row.get("time_factor"))
        q_round = to_float(row.get("q_round_no"))
        if q_round is None:
            q_yes = to_float(row.get("q_round"))
            if q_yes is not None and math.isfinite(q_yes):
                q_round = 1.0 - q_yes
        q_min_bound = to_float(row.get("q_entry_no"))
        edge_min = to_float(row.get("signal_edge_min_no"))
        token_id = str(row.get("no_token") or "")
        entry_depth_ok = row.get("entry_depth_ok_no")
        dominance = to_float(row.get("dominance"))
        time_base = to_float(row.get("time_base_no"))
        yes_ask = to_float(row.get("entry_price_yes")) or to_float(row.get("best_ask"))
        yes_q = to_float(row.get("q_entry"))
        no_ask = ask
        no_q = q_min_bound
        penalty = to_float(row.get("penalty_no"))
        trend_down = bool(row.get("trend_down_no"))
        trend_unknown = bool(row.get("trend_unknown_no"))
        trend_up = bool(row.get("trend_up_no"))
        trend_pct = to_float(row.get("trend_pct_no"))
        trend_consistency_up = to_float(row.get("trend_consistency_up_no"))
    structure_factor = to_float(row.get("structure_factor"))
    time_trend = to_float(row.get("time_trend"))
    time_freshness = to_float(row.get("time_freshness"))
    edge_points = None
    if q_round is not None and ask is not None and math.isfinite(q_round) and math.isfinite(ask):
        edge_points = max(q_round - ask, 0.0) * 100.0
    if penalty is None:
        penalty = _edge_score_penalty_simple(spread, ask)
    edge_realizable_v2_val = None
    edge_realizable_score_v2_val = None
    edge_realizable_p_realize = None
    edge_realizable_p_converge = None
    edge_realizable_p_fill_entry = None
    edge_realizable_p_fill_exit = None
    edge_realizable_hold_cost = None
    edge_realizable_target_exit_price = None
    edge_realizable_target_exit_price_raw = None
    edge_realizable_delta_exit = None
    edge_realizable_delta_exit_raw = None
    edge_realizable_delta_exit_cap = None
    edge_realizable_target_exit_clamped = None
    edge_realizable_p_realize_missing = None
    edge_realizable_p_realize_low_sample = None
    edge_realizable_p_realize_samples_min = None
    v2_enabled = str(os.environ.get("PM_EDGE_REALIZABLE_V2_ENABLED", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    if v2_enabled and exec_edge_entry is not None and math.isfinite(exec_edge_entry):
        exec_entry_price = to_float(row.get("exec_entry_price_yes") if side == "YES" else row.get("exec_entry_price_no"))
        if exec_entry_price is None or not math.isfinite(exec_entry_price):
            exec_entry_price = ask
        exec_fee_bps = to_float(row.get("exec_fee_bps"))
        depth_ratio = to_float(row.get("depth_ratio_yes") if side == "YES" else row.get("depth_ratio_no"))
        base_bid = to_float(row.get("best_bid") if side == "YES" else row.get("best_bid_no"))
        try:
            headroom_min = float(os.environ.get("PM_AUTO_TRADE_EXIT_HEADROOM_MIN", "0.02"))
        except (TypeError, ValueError):
            headroom_min = 0.02
        if not math.isfinite(headroom_min) or headroom_min < 0:
            headroom_min = 0.02
        edge_realizable_target_exit_price, target_exit_meta = _build_edge_realizable_target_exit_price_ui(
            exec_exit_price=exec_exit_price,
            exec_edge_exit=exec_edge_exit,
            base_bid=base_bid,
            spread=spread,
            side=side,
            row=row,
            headroom_min=float(headroom_min),
        )
        if target_exit_meta:
            edge_realizable_target_exit_price_raw = to_float(target_exit_meta.get("target_exit_price_raw"))
            edge_realizable_delta_exit_raw = to_float(target_exit_meta.get("delta_exit_raw"))
            edge_realizable_delta_exit_cap = to_float(target_exit_meta.get("delta_exit_cap"))
            edge_realizable_target_exit_clamped = bool(target_exit_meta.get("target_exit_clamped"))
        days_to_settle_val = float(days_to_event) if days_to_event is not None else None
        hours_to_settle_val = (
            float(days_to_event) * 24.0 if days_to_event is not None else None
        )
        order_type = str(os.environ.get("PM_AUTO_TRADE_ORDER_TYPE", "GTC") or "GTC").strip().upper()
        v2_edge, v2_meta = edge_realizable_v2(
            exec_edge_entry,
            exec_entry_price,
            exec_fee_bps,
            target_exit_price=edge_realizable_target_exit_price,
            base_bid=base_bid,
            spread=spread,
            depth_ratio=depth_ratio,
            days_to_settle=days_to_settle_val,
            hours_to_settle=hours_to_settle_val,
            order_type=order_type,
        )
        if v2_edge is not None and math.isfinite(v2_edge):
            edge_realizable_v2_val = float(v2_edge)
            try:
                time_structure_min = float(os.environ.get("PM_TIME_STRUCTURE_MIN", "0.1"))
            except (TypeError, ValueError):
                time_structure_min = 0.1
            if not math.isfinite(time_structure_min) or time_structure_min <= 0:
                time_structure_min = 0.1
            tf_val = time_factor if time_factor is not None and math.isfinite(time_factor) else 1.0
            sf_val = structure_factor if structure_factor is not None and math.isfinite(structure_factor) else 1.0
            time_structure = max(float(tf_val) * float(sf_val), time_structure_min)
            edge_realizable_score_v2_val = edge_realizable_score(
                edge_realizable_v2_val,
                time_structure,
                penalty,
            )
        if isinstance(v2_meta, dict):
            edge_realizable_p_realize = to_float(v2_meta.get("p_realize"))
            edge_realizable_p_converge = to_float(v2_meta.get("p_converge"))
            edge_realizable_p_fill_entry = to_float(v2_meta.get("p_fill_entry"))
            edge_realizable_p_fill_exit = to_float(v2_meta.get("p_fill_exit"))
            edge_realizable_hold_cost = to_float(v2_meta.get("hold_cost"))
            edge_realizable_p_realize_missing = bool(v2_meta.get("p_realize_missing"))
            edge_realizable_p_realize_low_sample = bool(v2_meta.get("p_realize_low_sample"))
            edge_realizable_p_realize_samples_min = to_float(v2_meta.get("p_realize_samples_min"))
            if edge_realizable_target_exit_price is None:
                edge_realizable_target_exit_price = to_float(v2_meta.get("target_exit_price"))
            edge_realizable_delta_exit = to_float(v2_meta.get("delta_exit"))
    return {
        "side": side,
        "outcome": outcome,
        "edge_score": edge_score,
        "exec_edge_entry": exec_edge_entry,
        "exec_edge_exit": exec_edge_exit,
        "exec_edge_score": exec_edge_score,
        "exec_exit_price": exec_exit_price,
        "edge_realizable": edge_realizable,
        "edge_realizable_score": edge_realizable_score_val,
        "edge_realizable_v2": edge_realizable_v2_val,
        "edge_realizable_score_v2": edge_realizable_score_v2_val,
        "edge_realizable_p_realize": edge_realizable_p_realize,
        "edge_realizable_p_converge": edge_realizable_p_converge,
        "edge_realizable_p_realize_min": to_float(row.get("edge_realizable_p_realize_min")),
        "edge_realizable_p_converge_min": to_float(row.get("edge_realizable_p_converge_min")),
        "edge_realizable_p_fill_entry": edge_realizable_p_fill_entry,
        "edge_realizable_p_fill_exit": edge_realizable_p_fill_exit,
        "edge_realizable_hold_cost": edge_realizable_hold_cost,
        "edge_realizable_p_realize_missing": edge_realizable_p_realize_missing,
        "edge_realizable_p_realize_low_sample": edge_realizable_p_realize_low_sample,
        "edge_realizable_p_realize_samples_min": edge_realizable_p_realize_samples_min,
        "edge_tradeability_edge_lcb": to_float(row.get("edge_tradeability_edge_lcb")),
        "edge_tradeability_signal_lcb_min": to_float(row.get("edge_tradeability_signal_lcb_min")),
        "edge_tradeability_path_lcb_min": to_float(row.get("edge_tradeability_path_lcb_min")),
        "edge_tradeability_edge_lcb_min": to_float(row.get("edge_tradeability_edge_lcb_min")),
        "edge_realizable_hq_edge_lcb_min": to_float(row.get("edge_realizable_hq_edge_lcb_min")),
        "edge_realizable_hq_bypass_p_realize_min": row.get("edge_realizable_hq_bypass_p_realize_min"),
        "edge_realizable_hq_bypass_p_converge_min": row.get("edge_realizable_hq_bypass_p_converge_min"),
        "edge_realizable_hq_bypassed_p_realize_min": row.get("edge_realizable_hq_bypassed_p_realize_min"),
        "edge_realizable_hq_bypassed_p_converge_min": row.get("edge_realizable_hq_bypassed_p_converge_min"),
        "edge_realizable_target_exit_price": edge_realizable_target_exit_price,
        "edge_realizable_target_exit_price_raw": edge_realizable_target_exit_price_raw,
        "edge_realizable_delta_exit": edge_realizable_delta_exit,
        "edge_realizable_delta_exit_raw": edge_realizable_delta_exit_raw,
        "edge_realizable_delta_exit_cap": edge_realizable_delta_exit_cap,
        "edge_realizable_target_exit_clamped": edge_realizable_target_exit_clamped,
        "exec_fee_cost": exec_fee_cost,
        "exec_fee_bps": to_float(row.get("exec_fee_bps")),
        "time_factor": time_factor,
        "structure_factor": structure_factor,
        "dominance": dominance,
        "time_trend": time_trend,
        "time_base": time_base,
        "time_freshness": time_freshness,
        "edge_points": edge_points,
        "penalty": penalty,
        "ask": ask,
        "spread": spread,
        "lag": lag,
        "edge_min": edge_min,
        "q_round": q_round,
        "q_min_bound": q_min_bound,
        "market_top_label": market_top_label or "",
        "yes_ask": yes_ask,
        "yes_q": yes_q,
        "no_ask": no_ask,
        "no_q": no_q,
        "entry_depth_ok": entry_depth_ok,
        "edge_min_exit_reasons": row.get("edge_min_exit_reasons_yes") if side == "YES" else row.get("edge_min_exit_reasons_no"),
        "token_id": token_id,
        "trade_info": trade_info_map.get((outcome, side)),
        "trend_down": trend_down,
        "trend_unknown": trend_unknown,
        "trend_up": trend_up,
        "trend_pct": trend_pct,
        "trend_consistency_up": trend_consistency_up,
    }


def _ssot_candidate_rank(candidate: Dict[str, Any]) -> float:
    # Ranking is for trade/explanation UI. Prefer candidates that have a tradable ask.
    ask = to_float(candidate.get("ask"))
    if ask is None or not math.isfinite(ask) or ask <= 0:
        return float("-inf")
    edge_realizable_score = to_float(candidate.get("edge_realizable_score"))
    if edge_realizable_score is not None and math.isfinite(edge_realizable_score):
        return float(edge_realizable_score)
    exec_edge_score = to_float(candidate.get("exec_edge_score"))
    if exec_edge_score is not None and math.isfinite(exec_edge_score):
        return float(exec_edge_score)
    edge_score = to_float(candidate.get("edge_score"))
    if edge_score is not None and math.isfinite(edge_score):
        return float(edge_score)
    edge_min = to_float(candidate.get("edge_min"))
    if edge_min is not None and math.isfinite(edge_min):
        return float(edge_min) * 100.0
    q_round = to_float(candidate.get("q_round"))
    if q_round is not None and math.isfinite(q_round):
        return float(q_round) * 10.0
    return float("-inf")


def _ssot_resolve_entry_realizable_score_min(
    policy: Dict[str, Any],
    days_to_event: Optional[int],
) -> Tuple[Optional[float], Optional[Dict[str, Any]]]:
    base = to_float(policy.get("entry_edge_score_market_min"))
    if base is None or not math.isfinite(base):
        base = None
    selected: Optional[Dict[str, Any]] = None
    tiers = policy.get("entry_time_thresholds")
    if days_to_event is not None and isinstance(tiers, list) and tiers:
        for tier in tiers:
            if not isinstance(tier, dict):
                continue
            try:
                max_days = int(tier.get("max_days")) if tier.get("max_days") is not None else None
            except (TypeError, ValueError):
                max_days = None
            if max_days is None:
                continue
            if days_to_event <= max_days:
                selected = tier
                break
        if selected is None:
            for tier in reversed(tiers):
                if isinstance(tier, dict):
                    selected = tier
                    break
    if selected is not None:
        tier_val = to_float(selected.get("edge_score_min"))
        if tier_val is not None and math.isfinite(tier_val):
            return tier_val, selected
    return base, selected


def _ssot_entry_reasons_main(
    candidate: Dict[str, Any],
    policy: Dict[str, Any],
    *,
    market_closed: bool,
    temp_event_blocked: bool,
    days_to_event: Optional[int] = None,
) -> List[str]:
    eps = 1e-6
    reasons: List[str] = []
    if market_closed:
        reasons.append("市场已收盘")
        return reasons
    if temp_event_blocked:
        min_val = to_float(policy.get("temp_event_min_edge_score_entry"))
        min_text = f"{min_val:.2f}" if min_val is not None and math.isfinite(min_val) else "?"
        reasons.append(f"温度事件入场阈值阻断(temp_edge_min={min_text})")
    side = str(candidate.get("side") or "").upper()
    outcome = str(candidate.get("outcome") or "")
    market_top_label = str(candidate.get("market_top_label") or "")
    flags = policy.get("flags") if isinstance(policy.get("flags"), dict) else {}
    if flags.get("entry_skip_top_label") and side == "NO" and market_top_label and outcome == market_top_label:
        reasons.append("最高概率桶NO不做")
    ask = to_float(candidate.get("ask"))
    if ask is None or not math.isfinite(ask) or ask <= 0:
        if ask is not None and math.isfinite(ask):
            reasons.append(f"价格无效(ask={ask:.2f})")
        else:
            reasons.append("价格无效(ask=—)")
        return reasons
    token_id = str(candidate.get("token_id") or "")
    if not token_id:
        reasons.append("缺少token_id")
    # 可兑现分仅用于排序/展示，不参与主策略入场阻断。
    if flags.get("entry_require_edge_realizable"):
        edge_realizable = to_float(candidate.get("edge_realizable"))
        edge_realizable_min = to_float(policy.get("entry_edge_realizable_min"))
        if edge_realizable is None or not math.isfinite(edge_realizable):
            reasons.append("可兑现口径无效")
        elif edge_realizable_min is not None and math.isfinite(edge_realizable_min):
            if edge_realizable + eps < edge_realizable_min:
                reasons.append(f"可兑现口径={edge_realizable:.4f}<{edge_realizable_min:.4f}")
    q_min_bound = to_float(candidate.get("q_min_bound"))
    if q_min_bound is None or not math.isfinite(q_min_bound):
        reasons.append("q无效")
    else:
        if flags.get("entry_require_q_range"):
            q_min = to_float(policy.get("entry_q_min"))
            q_max = to_float(policy.get("entry_q_max"))
            if q_min is not None and q_max is not None and math.isfinite(q_min) and math.isfinite(q_max):
                if q_min_bound + eps < q_min or q_min_bound - eps > q_max:
                    reasons.append(f"q={q_min_bound:.3f}不在区间[{q_min:.2f},{q_max:.2f}]")
    if side == "YES":
        if flags.get("entry_require_ask_range"):
            a_min = to_float(policy.get("entry_ask_min"))
            a_max = to_float(policy.get("entry_ask_max"))
            if a_min is not None and a_max is not None and math.isfinite(a_min) and math.isfinite(a_max):
                if ask + eps < a_min or ask - eps > a_max:
                    reasons.append(f"ask={ask:.2f}不在区间[{a_min:.2f},{a_max:.2f}]")
    else:
        if flags.get("entry_require_no_ask_range"):
            a_min = to_float(policy.get("no_ask_min"))
            a_max = to_float(policy.get("no_ask_max"))
            if a_min is not None and a_max is not None and math.isfinite(a_min) and math.isfinite(a_max):
                if ask + eps < a_min or ask - eps > a_max:
                    reasons.append(f"ask_no={ask:.2f}不在区间[{a_min:.2f},{a_max:.2f}]")
        if flags.get("entry_require_yes_overprice"):
            yes_ask = to_float(candidate.get("yes_ask"))
            yes_q = to_float(candidate.get("yes_q"))
            over_min = _ssot_env_float("PM_AUTO_TRADE_YES_OVERPRICE_MIN", 0.02) or 0.0
            if yes_ask is None or yes_q is None or not math.isfinite(yes_ask) or not math.isfinite(yes_q):
                reasons.append("YES侧价格/q缺失(无法验证overprice)")
            else:
                if yes_ask <= yes_q + over_min - eps:
                    reasons.append(f"YES未overprice(ask={yes_ask:.2f}<=q+{over_min:.2f})")
        if flags.get("entry_block_no_by_yes_q"):
            yes_q = to_float(candidate.get("yes_q"))
            n_min = _ssot_env_float("PM_AUTO_TRADE_YES_Q_NEVER_MIN", 0.85)
            n_max = _ssot_env_float("PM_AUTO_TRADE_YES_Q_NEVER_MAX", 1.0)
            if yes_q is not None and n_min is not None and n_max is not None and math.isfinite(yes_q) and math.isfinite(n_min) and math.isfinite(n_max):
                if yes_q + eps >= n_min and yes_q - eps <= n_max:
                    reasons.append(f"NO被YES概率阻断(yes_q={yes_q:.3f} in [{n_min:.2f},{n_max:.2f}])")
    if flags.get("entry_require_signal_edge"):
        edge_min = to_float(candidate.get("edge_min"))
        edge_min_th = to_float(policy.get("entry_signal_edge_min")) or 0.0
        if edge_min is None or not math.isfinite(edge_min):
            reasons.append("信号边际无效")
        elif edge_min <= edge_min_th + eps:
            reasons.append(f"信号边际={edge_min:.3f}≤{edge_min_th:.3f}")
    if flags.get("entry_require_ask_le_q_min"):
        buffer = to_float(policy.get("entry_ask_le_q_min_buffer")) or 0.0
        if q_min_bound is not None and math.isfinite(q_min_bound):
            if ask > q_min_bound + buffer + eps:
                reasons.append(f"ask={ask:.2f}>q+{buffer:.2f}")
    spread = to_float(candidate.get("spread"))
    if flags.get("entry_require_nonneg_spread"):
        if spread is None or not math.isfinite(spread):
            reasons.append("spread缺失")
        elif spread < -eps:
            reasons.append(f"spread={spread:.3f}<0")
    if flags.get("entry_require_spread_max"):
        max_spread = to_float(policy.get("entry_spread_max"))
        if max_spread is not None and math.isfinite(max_spread):
            if spread is None or not math.isfinite(spread):
                reasons.append("spread缺失")
            elif spread > max_spread + eps:
                reasons.append(f"spread={spread:.3f}>{max_spread:.3f}")
    if flags.get("entry_require_auto_max_ask"):
        max_ask = to_float(policy.get("auto_max_ask"))
        if max_ask is not None and math.isfinite(max_ask) and max_ask > 0:
            if ask > max_ask + eps:
                reasons.append(f"ask={ask:.2f}>{max_ask:.2f}")
    # Tail-lock quote (ultra-low ask with extreme q) protection.
    if policy.get("tail_lock_enabled"):
        hard = to_float(policy.get("tail_lock_ask_hard"))
        soft = to_float(policy.get("tail_lock_ask_soft"))
        q_min = to_float(policy.get("tail_lock_q_min"))
        if hard is not None and math.isfinite(hard) and ask <= hard + eps:
            reasons.append("尾部锁定报价(ask过低)")
        else:
            if soft is not None and q_min is not None and math.isfinite(soft) and math.isfinite(q_min):
                if ask <= soft + eps and q_min_bound is not None and math.isfinite(q_min_bound) and q_min_bound >= q_min - eps:
                    reasons.append("尾部锁定报价(ask偏低且q极端)")
    trade_info = candidate.get("trade_info")
    if isinstance(trade_info, dict):
        try:
            pos = float(trade_info.get("position_size")) if trade_info.get("position_size") is not None else None
        except (TypeError, ValueError):
            pos = None
        state = str(trade_info.get("state") or "")
        if (pos is not None and math.isfinite(pos) and pos > 0) or state in {"entry", "entry_pending"}:
            reasons.append("已有持仓/入场中")
    return reasons


def _ssot_build_auto_trade_ssot(item: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(item, dict):
        return None
    market_var = str(item.get("market_var") or "")
    if market_var and not market_var.startswith("temperature"):
        policy = _ssot_entry_policy_snapshot()
        reason = "不适用：非温度类事件"
        return {
            "version": 2,
            "policy": policy,
            "main_candidate": None,
            "main_entry_ok": False,
            "main_entry_reasons": [reason],
            "model_yes_top_candidate": None,
            "model_yes_top_label": "",
            "model_yes_top_na_reason": reason,
            "computed_at": str(item.get("created_at") or ""),
        }
    dist = item.get("distribution")
    if not isinstance(dist, list) or not dist:
        policy = _ssot_entry_policy_snapshot()
        reason = "不适用：distribution 为空"
        return {
            "version": 2,
            "policy": policy,
            "main_candidate": None,
            "main_entry_ok": False,
            "main_entry_reasons": [reason],
            "model_yes_top_candidate": None,
            "model_yes_top_label": "",
            "model_yes_top_na_reason": reason,
            "computed_at": str(item.get("created_at") or ""),
        }
    run_date_key = date_only(str(item.get("run_date") or item.get("current_event_date") or ""))
    event_date_key = date_only(str(item.get("event_date") or ""))
    run_dt = parse_date(run_date_key)
    event_dt = parse_date(event_date_key)
    days_to_event: Optional[int] = None
    if run_dt is not None and event_dt is not None:
        try:
            days_to_event = int((event_dt - run_dt).days)
        except Exception:
            days_to_event = None
    if days_to_event is not None and days_to_event < 0:
        days_to_event = 0
    # SSOT safety: some facts may have valid asks (possibly patched from ticks) but missing derived
    # fields like `edge_score_yes/no` due to older composer versions. Recompute in-memory so the
    # auto-trade SSOT candidate never shows "有效优势分 —" when price/q/time/structure are available.
    needs_recompute = False
    for row in dist:
        if not isinstance(row, dict):
            continue
        ask_yes = to_float(row.get("best_ask"))
        ask_no = to_float(row.get("best_ask_no"))
        es_yes = to_float(row.get("edge_score_yes"))
        es_no = to_float(row.get("edge_score_no"))
        exs_yes = to_float(row.get("exec_edge_score_yes"))
        exs_no = to_float(row.get("exec_edge_score_no"))
        ers_yes = to_float(row.get("edge_realizable_score_yes"))
        ers_no = to_float(row.get("edge_realizable_score_no"))
        er_yes = to_float(row.get("edge_realizable_yes"))
        er_no = to_float(row.get("edge_realizable_no"))
        fee_yes = to_float(row.get("exec_fee_cost_yes"))
        fee_no = to_float(row.get("exec_fee_cost_no"))
        if ask_yes is not None and math.isfinite(ask_yes) and (es_yes is None or not math.isfinite(es_yes)):
            needs_recompute = True
            break
        if ask_no is not None and math.isfinite(ask_no) and (es_no is None or not math.isfinite(es_no)):
            needs_recompute = True
            break
        if ask_yes is not None and math.isfinite(ask_yes) and (exs_yes is None or not math.isfinite(exs_yes)):
            needs_recompute = True
            break
        if ask_no is not None and math.isfinite(ask_no) and (exs_no is None or not math.isfinite(exs_no)):
            needs_recompute = True
            break
        if ask_yes is not None and math.isfinite(ask_yes) and (
            ers_yes is None or not math.isfinite(ers_yes) or er_yes is None or not math.isfinite(er_yes)
        ):
            needs_recompute = True
            break
        if ask_no is not None and math.isfinite(ask_no) and (
            ers_no is None or not math.isfinite(ers_no) or er_no is None or not math.isfinite(er_no)
        ):
            needs_recompute = True
            break
        if ask_yes is not None and math.isfinite(ask_yes) and (fee_yes is None or not math.isfinite(fee_yes)):
            needs_recompute = True
            break
        if ask_no is not None and math.isfinite(ask_no) and (fee_no is None or not math.isfinite(fee_no)):
            needs_recompute = True
            break
    if needs_recompute:
        try:
            time_structure_min = float(os.environ.get("PM_TIME_STRUCTURE_MIN", "0.1"))
        except (TypeError, ValueError):
            time_structure_min = 0.1
        if not math.isfinite(time_structure_min) or time_structure_min <= 0:
            time_structure_min = 0.1
        for row in dist:
            if isinstance(row, dict):
                _compute_edge_fields_in_place(row, time_structure_min)
    trade_info_map = _ssot_trade_info_map(item.get("auto_trades"))
    market_top_label = str(item.get("market_top_label") or "")
    candidates: List[Dict[str, Any]] = []
    for row in dist:
        if not isinstance(row, dict):
            continue
        for side in ("YES", "NO"):
            cand = _ssot_candidate_from_row(row, side, market_top_label, trade_info_map, days_to_event)
            if cand:
                candidates.append(cand)
    if not candidates:
        return {
            "version": 2,
            "policy": _ssot_entry_policy_snapshot(),
            "main_candidate": None,
            "main_entry_ok": False,
            "main_entry_reasons": ["无可用候选(缺少盘口/模型字段)"],
            "model_yes_top_candidate": None,
            "model_yes_top_label": "",
            "model_yes_top_na_reason": "不适用：无可用候选(缺少盘口/模型字段)",
        }
    # pickReasonCandidate() ranking: edge_score desc, else edge_min, else q, else -ask.
    best = max(candidates, key=_ssot_candidate_rank)
    policy = _ssot_entry_policy_snapshot()
    market_closed = bool(item.get("market_closed"))
    temp_event_blocked = False
    reasons = _ssot_entry_reasons_main(
        best,
        policy,
        market_closed=market_closed,
        temp_event_blocked=temp_event_blocked,
        days_to_event=days_to_event,
    )
    best["entry_reasons"] = reasons
    best["entry_ok"] = not reasons

    # Also compute "model-top YES candidate" under main-gate semantics for UI explanation:
    # this is the YES-side contract for the model_top_label bucket, regardless of which side is main-best.
    model_yes_top_candidate: Optional[Dict[str, Any]] = None
    model_yes_top_na_reason: Optional[str] = None
    model_top_label = str(item.get("model_top_label") or "").strip()
    q_cal_top_label = _top_label_from_distribution(dist, "q_calibrated")
    direct_label_match_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_YES_TOP_DIRECT_LABEL_MATCH", True)
    direct_label_match = (
        direct_label_match_enabled
        and q_cal_top_label
        and market_top_label
        and q_cal_top_label == market_top_label
    )
    yes_top_label = q_cal_top_label if direct_label_match else model_top_label
    if yes_top_label:
        matched_row: Optional[Dict[str, Any]] = None
        for row in dist:
            if not isinstance(row, dict):
                continue
            if str(row.get("outcome") or "") == yes_top_label:
                matched_row = row
                break
        if not matched_row:
            label_kind = "q_calibrated_top_label" if direct_label_match else "model_top_label"
            model_yes_top_na_reason = f"不适用：distribution 未包含 {label_kind}={yes_top_label}"
        else:
            try:
                cand_top = _ssot_candidate_from_row(matched_row, "YES", market_top_label, trade_info_map, days_to_event)
            except Exception:
                cand_top = None
                model_yes_top_na_reason = "不适用：构建 YES 侧候选异常"
            if isinstance(cand_top, dict):
                if direct_label_match and not market_closed:
                    cand_top["entry_reasons"] = []
                    cand_top["entry_ok"] = True
                    cand_top["direct_entry"] = True
                else:
                    top_reasons = _ssot_entry_reasons_main(
                        cand_top,
                        policy,
                        market_closed=market_closed,
                        temp_event_blocked=temp_event_blocked,
                        days_to_event=days_to_event,
                    )
                    cand_top["entry_reasons"] = top_reasons
                    cand_top["entry_ok"] = not top_reasons
                model_yes_top_candidate = cand_top
            else:
                if model_yes_top_na_reason is None:
                    model_yes_top_na_reason = "不适用：该桶缺少 YES 侧盘口/Token，无法构建候选"
    else:
        model_yes_top_na_reason = "不适用：缺少 model_top_label（未计算模型最高桶）"
    return {
        "version": 2,
        "policy": policy,
        "main_candidate": best,
        "main_entry_ok": not reasons,
        "main_entry_reasons": reasons,
        "model_yes_top_candidate": model_yes_top_candidate,
        "model_yes_top_label": yes_top_label,
        "model_yes_top_na_reason": model_yes_top_na_reason,
        "computed_at": str(item.get("created_at") or ""),
    }


def _get_or_build_auto_trade_ssot(payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(payload, dict):
        return None
    ssot = payload.get("auto_trade_ssot")
    if not isinstance(ssot, dict):
        return _safe_build_auto_trade_ssot(payload)
    v2_enabled = str(os.environ.get("PM_EDGE_REALIZABLE_V2_ENABLED", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    def _missing_exec_fields(cand: Any) -> bool:
        if not isinstance(cand, dict):
            return False
        for key in ("exec_edge_score", "exec_edge_entry", "exec_edge_exit"):
            val = to_float(cand.get(key))
            if val is None or not math.isfinite(val):
                return True
        for key in ("edge_realizable", "edge_realizable_score", "exec_fee_cost", "exec_fee_bps"):
            val = to_float(cand.get(key))
            if val is None or not math.isfinite(val):
                return True
        return False
    def _missing_v2_fields(cand: Any) -> bool:
        if not v2_enabled or not isinstance(cand, dict):
            return False
        v2 = to_float(cand.get("edge_realizable_v2"))
        v2_score = to_float(cand.get("edge_realizable_score_v2"))
        p_realize = to_float(cand.get("edge_realizable_p_realize"))
        hold_cost = to_float(cand.get("edge_realizable_hold_cost"))
        if v2 is None or not math.isfinite(v2):
            return True
        if v2_score is None or not math.isfinite(v2_score):
            return True
        if p_realize is None or not math.isfinite(p_realize):
            return True
        if hold_cost is None or not math.isfinite(hold_cost):
            return True
        return False
    if (
        _missing_exec_fields(ssot.get("main_candidate"))
        or _missing_exec_fields(ssot.get("model_yes_top_candidate"))
        or _missing_v2_fields(ssot.get("main_candidate"))
        or _missing_v2_fields(ssot.get("model_yes_top_candidate"))
    ):
        return _safe_build_auto_trade_ssot(payload)
    # If legacy SSOT lacks YES-top NA reason and no candidate, rebuild for explicit reason.
    if (
        ssot.get("model_yes_top_candidate") is None
        and not str(ssot.get("model_yes_top_na_reason") or "").strip()
    ):
        return _safe_build_auto_trade_ssot(payload)
    return ssot


def _safe_build_auto_trade_ssot(payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(payload, dict):
        return None
    try:
        return _ssot_build_auto_trade_ssot(payload)
    except Exception:
        reason = "不适用：SSOT构建异常"
        policy = _ssot_entry_policy_snapshot()
        return {
            "version": 2,
            "policy": policy,
            "main_candidate": None,
            "main_entry_ok": False,
            "main_entry_reasons": [reason],
            "model_yes_top_candidate": None,
            "model_yes_top_label": str(payload.get("model_top_label") or ""),
            "model_yes_top_na_reason": reason,
            "computed_at": str(payload.get("created_at") or ""),
        }


def build_run_item(
    conn: sqlite3.Connection,
    row: sqlite3.Row,
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]],
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]],
    auto_orders_map: Dict[str, sqlite3.Row],
    market_tick_latest_map: Optional[Dict[Tuple[str, str], str]] = None,
    platt: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    payload = safe_json_loads(row["payload_json"])
    _slim_fact_payload_for_ui(payload)
    cache_age_sec = payload.get("model_cache_age_sec")
    cache_freshness = payload.get("model_cache_freshness")
    suggestions: List[Any] = []
    if row["suggestions_json"]:
        try:
            loaded = json.loads(row["suggestions_json"])
        except json.JSONDecodeError:
            loaded = []
        if isinstance(loaded, list):
            suggestions = loaded
    distribution = normalize_distribution_rows(payload.get("rows") or [])
    models = payload_models(payload)
    model_info = ",".join(str(m) for m in models if m)
    model_count = len(models)
    suggestion_filter_stats = payload.get("suggestion_filter_stats") or {}
    event_date_key = str(row["event_date"] or "")
    if "T" in event_date_key:
        event_date_key = event_date_key.split("T", 1)[0]
    key = (str(row["slug"] or ""), event_date_key)
    payload_market_updated_at = str(payload.get("market_updated_at") or "").strip()
    tick_market_updated_at = str((market_tick_latest_map or {}).get(key) or "").strip()
    run_market_updated_at = str(row["created_at"] or "").strip()
    if tick_market_updated_at:
        market_updated_at = tick_market_updated_at
        market_updated_source = "tick"
    elif run_market_updated_at:
        market_updated_at = run_market_updated_at
        market_updated_source = "run"
    else:
        market_updated_at = payload_market_updated_at
        market_updated_source = "payload" if payload_market_updated_at else ""
    try:
        market_stale_sec = int(os.environ.get("PM_AUTO_TRADE_ENTRY_STALE_SEC", "120"))
    except (TypeError, ValueError):
        market_stale_sec = 120
    if distribution:
        needs_tick = any(
            (row.get("best_ask") is None and row.get("best_ask_no") is None)
            for row in distribution
        )
        touched_market = False
        if needs_tick:
            tick_map = _latest_ticks_for_event(conn, str(row["slug"] or ""), event_date_key)
            if tick_map:
                for dist_row in distribution:
                    outcome = str(dist_row.get("outcome") or "")
                    if not outcome:
                        continue
                    tick_yes = tick_map.get((outcome, "YES"))
                    if tick_yes:
                        if dist_row.get("best_bid") is None and tick_yes["best_bid"] is not None:
                            dist_row["best_bid"] = tick_yes["best_bid"]
                        if dist_row.get("best_ask") is None and tick_yes["best_ask"] is not None:
                            dist_row["best_ask"] = tick_yes["best_ask"]
                            dist_row["ask_missing_reason_yes"] = ""
                            touched_market = True
                        if dist_row.get("spread") is None and dist_row.get("best_bid") is not None and dist_row.get("best_ask") is not None:
                            dist_row["spread"] = max(float(dist_row["best_ask"]) - float(dist_row["best_bid"]), 0.0)
                        if dist_row.get("bid_depth_topN") is None and tick_yes["bid_depth_topN"] is not None:
                            dist_row["bid_depth_topN"] = tick_yes["bid_depth_topN"]
                        if dist_row.get("ask_depth_topN") is None and tick_yes["ask_depth_topN"] is not None:
                            dist_row["ask_depth_topN"] = tick_yes["ask_depth_topN"]
                    tick_no = tick_map.get((outcome, "NO"))
                    if tick_no:
                        if dist_row.get("best_bid_no") is None and tick_no["best_bid"] is not None:
                            dist_row["best_bid_no"] = tick_no["best_bid"]
                        if dist_row.get("best_ask_no") is None and tick_no["best_ask"] is not None:
                            dist_row["best_ask_no"] = tick_no["best_ask"]
                            dist_row["ask_missing_reason_no"] = ""
                            touched_market = True
                        if dist_row.get("spread_no") is None and dist_row.get("best_bid_no") is not None and dist_row.get("best_ask_no") is not None:
                            dist_row["spread_no"] = max(float(dist_row["best_ask_no"]) - float(dist_row["best_bid_no"]), 0.0)
                        if dist_row.get("bid_depth_topN_no") is None and tick_no["bid_depth_topN"] is not None:
                            dist_row["bid_depth_topN_no"] = tick_no["bid_depth_topN"]
                        if dist_row.get("ask_depth_topN_no") is None and tick_no["ask_depth_topN"] is not None:
                            dist_row["ask_depth_topN_no"] = tick_no["ask_depth_topN"]
        # Recompute derived fields (time/base/penalty/edge_score) when asks exist but edge_score is missing.
        # This is required because we may patch asks from ticks (or have historical tick-filled asks),
        # and leaving derived fields as null would break SSOT (UI shows "有效优势分 —" with a valid ask).
        needs_recompute = touched_market
        if not needs_recompute:
            for dist_row in distribution:
                if not isinstance(dist_row, dict):
                    continue
                ask_yes = to_float(dist_row.get("best_ask"))
                ask_no = to_float(dist_row.get("best_ask_no"))
                es_yes = to_float(dist_row.get("edge_score_yes"))
                es_no = to_float(dist_row.get("edge_score_no"))
                exs_yes = to_float(dist_row.get("exec_edge_score_yes"))
                exs_no = to_float(dist_row.get("exec_edge_score_no"))
                if ask_yes is not None and math.isfinite(ask_yes) and (es_yes is None or not math.isfinite(es_yes)):
                    needs_recompute = True
                    break
                if ask_no is not None and math.isfinite(ask_no) and (es_no is None or not math.isfinite(es_no)):
                    needs_recompute = True
                    break
                if ask_yes is not None and math.isfinite(ask_yes) and (exs_yes is None or not math.isfinite(exs_yes)):
                    needs_recompute = True
                    break
                if ask_no is not None and math.isfinite(ask_no) and (exs_no is None or not math.isfinite(exs_no)):
                    needs_recompute = True
                    break
        if needs_recompute:
            try:
                time_structure_min = float(os.environ.get("PM_TIME_STRUCTURE_MIN", "0.1"))
            except (TypeError, ValueError):
                time_structure_min = 0.1
            if not math.isfinite(time_structure_min) or time_structure_min <= 0:
                time_structure_min = 0.1
            for dist_row in distribution:
                if isinstance(dist_row, dict):
                    _compute_edge_fields_in_place(dist_row, time_structure_min)
    q_cal_na_reason = None
    fact_prov_extra: Optional[Dict[str, Any]] = None
    if distribution:
        try:
            cal_payload = {"distribution": distribution}
            if _ensure_fact_q_calibrated(cal_payload, platt):
                if isinstance(cal_payload.get("fact_provenance"), dict):
                    fact_prov_extra = dict(cal_payload.get("fact_provenance") or {})
        except Exception:
            pass
        try:
            na_payload = {"distribution": distribution}
            _set_fact_q_calibrated_na_reason(na_payload, platt)
            q_cal_na_reason = na_payload.get("q_calibrated_na_reason")
        except Exception:
            q_cal_na_reason = None
    top_label, top_q = top_bucket_from_distribution(distribution, "q_round")
    market_label = market_top_label(distribution)
    corrected_top_bucket = build_weight_map(
        {
            "equal": row["corrected_top_bucket_equal"] or "",
            "auto": row["corrected_top_bucket_auto"] or "",
            "scenario": row["corrected_top_bucket_scenario"] or "",
        }
    )
    corrected_top_consistency = build_weight_map(
        {
            "equal": row["corrected_top_consistency_equal"] or "",
            "auto": row["corrected_top_consistency_auto"] or "",
            "scenario": row["corrected_top_consistency_scenario"] or "",
        }
    )
    bucket_diag = payload.get("bucket_diag") or payload.get("bucket_diagnostics") or {}
    weight_maps = resolve_weight_maps_for_row(row, distribution, models) if distribution and models else {}
    if weight_maps:
        distribution = apply_weighted_distribution(distribution, models, weight_maps)
    top_bucket_stats: Optional[Dict[str, Any]] = None
    top_bucket_stats_label = str(corrected_top_bucket.get("equal") or "").strip()
    if not top_bucket_stats_label:
        top_bucket_stats_label = str(top_label or "").strip()
    if distribution and top_bucket_stats_label:
        matched_row: Optional[Dict[str, Any]] = None
        for dist_row in distribution:
            if str(dist_row.get("outcome") or "") == top_bucket_stats_label:
                matched_row = dist_row
                break
        if matched_row:
            q_raw_val = to_float(matched_row.get("q_raw"))
            if q_raw_val is None:
                q_raw_val = to_float(matched_row.get("q_round"))
            top_bucket_stats = {
                "weighting": "equal",
                "label": top_bucket_stats_label,
                "q_raw": q_raw_val,
                "q_min": to_float(matched_row.get("q_min")),
                "q_max": to_float(matched_row.get("q_max")),
                "q_equal": to_float(matched_row.get("q_equal")),
                "q_auto": to_float(matched_row.get("q_auto")),
                "q_scenario": to_float(matched_row.get("q_scenario")),
                "q_calibrated": to_float(matched_row.get("q_calibrated")),
            }
            if top_bucket_stats.get("q_calibrated") is None:
                top_bucket_stats["q_calibrated"] = to_float(matched_row.get("raw_q_calibrated"))
    mean_bucket: Dict[str, Dict[str, Any]] = {}
    if distribution and models:
        weight_entries = (
            ("equal", "q_equal"),
            ("auto", "q_auto"),
            ("scenario", "q_scenario"),
        )
        for weight_key, q_key in weight_entries:
            weights = weight_maps.get(weight_key) or {}
            expected = expected_value_from_distribution_weighted(
                distribution,
                models,
                weights,
                str(row["rounding_rule"] or ""),
                str(row["market_var"] or ""),
            )
            if expected is None:
                expected = expected_value_from_distribution(
                    distribution,
                    q_key,
                    str(row["rounding_rule"] or ""),
                    str(row["market_var"] or ""),
                )
            if expected is None:
                continue
            p25, p75 = quantiles_from_distribution_weighted(
                distribution,
                models,
                weights,
                str(row["rounding_rule"] or ""),
                str(row["market_var"] or ""),
            )
            if p25 is None or p75 is None:
                p25, p75 = quantiles_from_distribution(
                    distribution,
                    q_key,
                    str(row["rounding_rule"] or ""),
                    str(row["market_var"] or ""),
                )
            label = bucket_label_for_value(
                distribution,
                expected,
                str(row["rounding_rule"] or ""),
                str(row["market_var"] or ""),
            )
            q_val = weighted_q_for_label(distribution, label, models, weights) if label else None
            if q_val is None and label:
                for dist_row in distribution:
                    if str(dist_row.get("outcome") or "") != label:
                        continue
                    q_val = to_float(dist_row.get(q_key))
                    if q_val is None:
                        q_val = to_float(dist_row.get("q_round"))
                    break
            mean_bucket[weight_key] = {
                "expected": expected,
                "label": label,
                "q": q_val,
                "p25": p25,
                "p75": p75,
            }
    auto_trades: List[Dict[str, Any]] = []
    avg_price_map: Dict[Tuple[str, str], float] = {}
    for trade in trade_map.get(key, []):
        outcome = str(trade["outcome"] or "")
        side = str(trade["side"] or "")
        avg_price = to_float(trade["avg_price"])
        if avg_price is None:
            avg_price = to_float(trade["entry_price"])
        if outcome and side and avg_price is not None:
            avg_price_map[(outcome, side)] = avg_price
        fills = []
        fill_key = (key[0], key[1], outcome, side)
        for fill in fills_map.get(fill_key, []):
            fills.append(
                {
                    "trade_side": str(fill["trade_side"] or ""),
                    "price": fill["price"],
                    "size": fill["size"],
                    "trade_time": str(fill["trade_time"] or ""),
                    "order_id": str(fill["order_id"] or ""),
                    "trade_id": str(fill["trade_id"] or ""),
                }
            )
        auto_trades.append(
            {
                "outcome": outcome,
                "side": side,
                "state": str(trade["state"] or ""),
                "entry_at": str(trade["entry_at"] or ""),
                "last_order_id": str(trade["last_order_id"] or ""),
                "entry_price": trade["entry_price"] if "entry_price" in trade.keys() else None,
                "entry_size": trade["entry_size"] if "entry_size" in trade.keys() else None,
                "last_action": str(trade["last_action"] or "") if "last_action" in trade.keys() else "",
                "last_action_price": trade["last_action_price"] if "last_action_price" in trade.keys() else None,
                "last_action_size": trade["last_action_size"] if "last_action_size" in trade.keys() else None,
                "last_action_at": str(trade["last_action_at"] or "") if "last_action_at" in trade.keys() else "",
                "last_status": str(trade["last_status"] or "") if "last_status" in trade.keys() else "",
                "last_error": str(trade["last_error"] or "") if "last_error" in trade.keys() else "",
                "position_size": trade["position_size"] if "position_size" in trade.keys() else None,
                "avg_price": trade["avg_price"] if "avg_price" in trade.keys() else None,
                "realized_pnl": trade["realized_pnl"] if "realized_pnl" in trade.keys() else None,
                "unrealized_pnl": trade["unrealized_pnl"] if "unrealized_pnl" in trade.keys() else None,
                "mark_price": trade["mark_price"] if "mark_price" in trade.keys() else None,
                "peak_price": trade["peak_price"] if "peak_price" in trade.keys() else None,
                "exit_reasons": str(trade["exit_reasons"] or "") if "exit_reasons" in trade.keys() else "",
                "exit_reason_codes": str(trade["exit_reason_codes"] or "") if "exit_reason_codes" in trade.keys() else "",
                "exit_triggered_at": str(trade["exit_triggered_at"] or "") if "exit_triggered_at" in trade.keys() else "",
                "exit_skip_reason": str(trade["exit_skip_reason"] or "") if "exit_skip_reason" in trade.keys() else "",
                "exit_skip_detail": str(trade["exit_skip_detail"] or "") if "exit_skip_detail" in trade.keys() else "",
                "exit_skip_at": str(trade["exit_skip_at"] or "") if "exit_skip_at" in trade.keys() else "",
                "last_fill_at": str(trade["last_fill_at"] or "") if "last_fill_at" in trade.keys() else "",
                "updated_at": str(trade["updated_at"] or ""),
                "fills": fills,
            }
        )
    auto_order_ids = {oid for oid in auto_orders_map.keys() if oid}
    for trade in trade_map.get(key, []):
        entry_at = str(trade["entry_at"] or "")
        if entry_at and is_before_stats_cutoff(entry_at):
            continue
        last_order = str(trade["last_order_id"] or "")
        if last_order:
            auto_order_ids.add(last_order)
    order_list: List[Dict[str, Any]] = []
    for fill_key, fills in fills_map.items():
        if fill_key[0] != key[0] or fill_key[1] != key[1]:
            continue
        outcome = fill_key[2]
        side = fill_key[3]
        for fill in fills:
            trade_side = str(fill["trade_side"] or "").upper()
            price = to_float(fill["price"])
            size = to_float(fill["size"])
            order_id = str(fill["order_id"] or "")
            if order_id and order_id not in auto_order_ids:
                continue
            amount = price * size if price is not None and size is not None else None
            cost = avg_price_map.get((outcome, side))
            buy_price = price if trade_side == "BUY" else cost
            sell_price = price if trade_side == "SELL" else None
            pnl = None
            if trade_side == "SELL" and price is not None and size is not None and cost is not None:
                pnl = (price - cost) * size
            order_list.append(
                {
                    "source": "auto",
                    "trade_time": str(fill["trade_time"] or ""),
                    "trade_side": trade_side,
                    "price": price,
                    "size": size,
                    "amount": amount,
                    "pnl": pnl,
                    "buy_price": buy_price,
                    "sell_price": sell_price,
                    "outcome": outcome,
                    "bucket_tag": format_bucket_tag(outcome),
                    "order_id": order_id,
                }
            )
    order_list.sort(
        key=lambda item: parse_iso_ts(str(item.get("trade_time") or "")) or datetime.min,
        reverse=True,
    )
    if len(order_list) > 50:
        order_list = order_list[:50]
    out = {
        "slug": str(row["slug"] or ""),
        "event_url": str(row["event_url"] or payload.get("event_url") or ""),
        "title": str(row["title"] or payload.get("title") or ""),
        "city": str(row["city"] or ""),
        "station_id": str(row["station_id"] or ""),
        "location_basis": str(row["location_basis"] or ""),
        "event_date": str(row["event_date"] or ""),
        "run_date": str(row["run_date"] or ""),
        "event_tz": str(row["tz"] or "UTC"),
        "event_target_utc": "",
        "event_peak_time_utc": str(row["event_peak_time_utc"] or ""),
        "event_end_utc": str(row["event_end_utc"] or ""),
        "market_var": str(row["market_var"] or ""),
        "market_unit": str(row["market_unit"] or ""),
        "rounding_rule": str(row["rounding_rule"] or ""),
        "resolution_source": str(row["resolution_source"] or ""),
        "settlement_actual": row["settlement_actual"],
        "market_closed": int(row["market_closed"] or 0),
        "city_most_likely_label": str(row["city_most_likely_label"] or ""),
        "city_most_likely_q": row["city_most_likely_q"],
        "model_info": model_info,
        "model_provenance": payload.get("model_provenance") or {},
        "model_cache_age_sec": cache_age_sec,
        "model_cache_freshness": cache_freshness,
        "model_count": model_count,
        "equal_model_count": model_count,
        "model_top_label": top_label,
        "model_top_q": top_q,
        "model_top_q_calibrated": (top_bucket_stats or {}).get("q_calibrated"),
        "market_top_label": market_label,
        "market_close_label": "",
        "market_close_price": None,
        "market_updated_at": market_updated_at,
        "market_updated_source": market_updated_source,
        "market_quote_updated_at": payload_market_updated_at,
        "market_stale_sec": market_stale_sec,
        "model_spread_kind": "prob",
        "sample_info": "",
        "index_source": "",
        "suggestions": suggestions,
        "suggestion_filter_stats": suggestion_filter_stats,
        "distribution": distribution,
        "q_calibrated_na_reason": q_cal_na_reason,
        "top_bucket_stats": top_bucket_stats,
        "corrected_top_bucket": corrected_top_bucket,
        "corrected_top_consistency": corrected_top_consistency,
        "bucket_diag": bucket_diag,
        "mean_bucket": mean_bucket,
        "auto_trades": auto_trades,
        "trade_list": order_list,
        "order_list": order_list,
    }
    if fact_prov_extra:
        out_prov = out.get("fact_provenance")
        if isinstance(out_prov, dict):
            out_prov.update(fact_prov_extra)
        else:
            out["fact_provenance"] = fact_prov_extra
    out["auto_trade_ssot"] = _safe_build_auto_trade_ssot(out)
    return out


def query_runs(date: str, include_history: bool) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    with open_db() as conn:
        rows = select_event_run_rows(conn, date, include_history)
        if not rows:
            return []
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        market_tick_latest_map = query_market_tick_latest(conn)
        return [
            build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map)
            for row in rows
        ]


def select_event_run_rows(conn: sqlite3.Connection, date: str, include_history: bool) -> List[sqlite3.Row]:
    date_key = str(date or "").strip()
    if not date_key:
        date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    cur = conn.cursor()
    if include_history:
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date <= ? ORDER BY run_date DESC, created_at DESC",
            (date_key,),
        )
    else:
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date = ? ORDER BY created_at DESC",
            (date_key,),
        )
    rows = cur.fetchall()
    if not rows:
        return []
    if not include_history:
        seen: set[Tuple[str, str]] = set()
        out: List[sqlite3.Row] = []
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            out.append(row)
        return out
    best_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    fallback_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date_key = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date_key:
            continue
        key = (slug, event_date_key)
        run_date = _normalize_date_key(str(row["run_date"] or ""))
        created_at = str(row["created_at"] or "")
        prev_fallback = fallback_rows.get(key)
        if not prev_fallback or (run_date, created_at) > (
            _normalize_date_key(str(prev_fallback["run_date"] or "")),
            str(prev_fallback["created_at"] or ""),
        ):
            fallback_rows[key] = row
        cutoff = date_key
        if date_key and event_date_key and event_date_key < date_key:
            cutoff = event_date_key
        if cutoff and run_date and run_date > cutoff:
            continue
        prev_best = best_rows.get(key)
        if not prev_best or (run_date, created_at) > (
            _normalize_date_key(str(prev_best["run_date"] or "")),
            str(prev_best["created_at"] or ""),
        ):
            best_rows[key] = row
    out: List[sqlite3.Row] = []
    for key, fallback in fallback_rows.items():
        out.append(best_rows.get(key) or fallback)
    return out


def select_event_run_rows_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[sqlite3.Row]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM event_runs
        WHERE run_date >= ? AND run_date <= ?
        ORDER BY run_date DESC, created_at DESC
        """,
        (start_key, end_key),
    )
    return cur.fetchall()


def _load_latest_snapshot(
    conn: sqlite3.Connection,
    table: str,
    slug: str,
    event_date: str,
) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]], str, Optional[int]]:
    if table not in {"model_snapshots", "market_snapshots"}:
        return None, None, "", None
    slug_key = str(slug or "").strip()
    date_key = _normalize_date_key(str(event_date or ""))
    if not slug_key or not date_key:
        return None, None, "", None
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT id, payload_json, meta_json, created_at
            FROM {table}
            WHERE slug = ? AND event_date = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (slug_key, date_key),
        )
    except sqlite3.Error:
        return None, None, "", None
    row = cur.fetchone()
    if not row:
        return None, None, "", None
    payload = safe_json_loads(row["payload_json"] if "payload_json" in row.keys() else None)
    meta: Dict[str, Any] = {}
    meta_raw = row["meta_json"] if "meta_json" in row.keys() else None
    if meta_raw:
        try:
            loaded = json.loads(meta_raw)
        except json.JSONDecodeError:
            loaded = {}
        if isinstance(loaded, dict):
            meta = loaded
    created_at = str(row["created_at"] or "")
    snap_id = _to_int(row["id"])
    return payload, meta, created_at, snap_id


def _snapshot_key_rows_for_run_date(conn: sqlite3.Connection, run_date: str) -> List[Tuple[str, str, str]]:
    run_key = _normalize_date_key(run_date)
    if not run_key:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, run_date
            FROM (
                SELECT slug, event_date, run_date
                FROM model_snapshots
                WHERE run_date = ?
                UNION
                SELECT slug, event_date, run_date
                FROM market_snapshots
                WHERE run_date = ?
            )
            GROUP BY slug, event_date, run_date
            """,
            (run_key, run_key),
        )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    out: List[Tuple[str, str, str]] = []
    for r in rows:
        slug = str(r[0] or "")
        event_date = _normalize_date_key(str(r[1] or ""))
        run_date_val = _normalize_date_key(str(r[2] or ""))
        if slug and event_date and run_date_val:
            out.append((slug, event_date, run_date_val))
    return out


def _snapshot_key_rows_for_run_date_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[Tuple[str, str, str]]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, MAX(run_date) AS run_date
            FROM (
                SELECT slug, event_date, run_date
                FROM model_snapshots
                WHERE run_date >= ? AND run_date <= ?
                UNION
                SELECT slug, event_date, run_date
                FROM market_snapshots
                WHERE run_date >= ? AND run_date <= ?
            )
            GROUP BY slug, event_date
            """,
            (start_key, end_key, start_key, end_key),
        )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    out: List[Tuple[str, str, str]] = []
    for r in rows:
        slug = str(r[0] or "")
        event_date = _normalize_date_key(str(r[1] or ""))
        run_date_val = _normalize_date_key(str(r[2] or ""))
        if slug and event_date and run_date_val:
            out.append((slug, event_date, run_date_val))
    return out


def _edge_score_penalty(spread: Optional[float], ask: Optional[float]) -> float:
    penalty = 0.0
    if spread is not None and ask is not None:
        spread_pct = max(float(spread) * 100.0, 0.0)
        penalty += max(0.0, (spread_pct - 8.0) / 10.0)
        penalty += max(0.0, (float(ask) - 0.6) / 0.2)
    return penalty


def _direction_base(delta: Optional[float], scale: float = 0.02) -> float:
    """Directional base term used by time_factor.

    This mirrors scan_weather_market.py's sigmoid-based base:
      base = sigmoid((q_entry - ask) / 0.02)
    """
    if delta is None or scale <= 0:
        return 0.0
    try:
        x = float(delta) / float(scale)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(x):
        return 0.0
    if x >= 20:
        return 1.0
    if x <= -20:
        return 0.0
    return 1.0 / (1.0 + math.exp(-x))


def _compute_edge_fields_in_place(row: Dict[str, Any], time_structure_min: float) -> None:
    exec_fee_bps = _ssot_env_float("PM_AUTO_TRADE_EXEC_FEE_BPS", 100.0)
    q_round = to_float(row.get("q_round"))
    q_round_no = to_float(row.get("q_round_no"))
    if q_round_no is None and q_round is not None:
        q_round_no = 1.0 - q_round
        row["q_round_no"] = q_round_no
    q_cal = to_float(row.get("q_calibrated"))
    q_raw = to_float(row.get("q_raw"))
    q_raw_canonical = q_raw if q_raw is not None else q_round
    q_raw_no = to_float(row.get("q_raw_no"))
    if q_raw_no is None and q_raw_canonical is not None:
        q_raw_no = 1.0 - q_raw_canonical
        if row.get("q_raw_no") is None:
            row["q_raw_no"] = q_raw_no
    q_entry = to_float(row.get("q_entry"))
    if q_entry is None:
        q_entry = q_cal if q_cal is not None else (q_raw if q_raw is not None else q_round)
        if q_entry is not None:
            row["q_entry"] = q_entry
    q_entry_no = to_float(row.get("q_entry_no"))
    if q_entry_no is None and q_entry is not None:
        q_entry_no = 1.0 - q_entry
        row["q_entry_no"] = q_entry_no
    ask_yes = to_float(row.get("best_ask"))
    ask_no = to_float(row.get("best_ask_no"))
    bid_yes = to_float(row.get("best_bid"))
    bid_no = to_float(row.get("best_bid_no"))
    # SSOT: signal_edge_round is the *raw* signal margin (q_raw vs best_ask), not calibrated.
    if ask_yes is not None and q_raw_canonical is not None:
        row["signal_edge_round"] = q_raw_canonical - ask_yes
    if ask_yes is not None and q_entry is not None:
        row["signal_edge_min"] = q_entry - ask_yes
    if ask_no is not None and q_raw_no is not None:
        row["signal_edge_round_no"] = q_raw_no - ask_no
    if ask_no is not None and q_entry_no is not None:
        row["signal_edge_min_no"] = q_entry_no - ask_no

    # Recompute time base/time factor after market merge. Model-only snapshots compute these
    # with missing asks, which clamps base to 0 and time_factor to TIME_FACTOR_MIN.
    time_trend = to_float(row.get("time_trend"))
    if time_trend is None or not math.isfinite(time_trend):
        time_trend = 0.0
        row["time_trend"] = time_trend
    time_fresh = to_float(row.get("time_freshness"))
    if time_fresh is None:
        # Fallback to the legacy model freshness key when present in snapshot payloads.
        time_fresh = to_float(row.get("model_cache_freshness"))
    if time_fresh is None or not math.isfinite(time_fresh):
        time_fresh = 1.0
    try:
        time_factor_min = float(os.environ.get("PM_TIME_FACTOR_MIN", "0.1"))
    except (TypeError, ValueError):
        time_factor_min = 0.1
    if not math.isfinite(time_factor_min) or time_factor_min <= 0:
        time_factor_min = 0.1

    base_yes = _direction_base((q_entry - ask_yes) if (q_entry is not None and ask_yes is not None) else None)
    base_no = _direction_base((q_entry_no - ask_no) if (q_entry_no is not None and ask_no is not None) else None)
    row["time_base_yes"] = base_yes
    row["time_base_no"] = base_no
    time_yes = min(max(time_trend + base_yes * time_fresh, time_factor_min), 1.0)
    time_no = min(max(time_trend + base_no * time_fresh, time_factor_min), 1.0)
    row["time_factor_yes"] = time_yes
    row["time_factor_no"] = time_no
    row["time_factor"] = max(time_yes, time_no)
    structure = to_float(row.get("structure_factor"))
    if structure is None:
        structure = to_float(row.get("structure_factor_yes"))
    if structure is None:
        structure = to_float(row.get("structure_factor_no"))
    time_yes = to_float(row.get("time_factor_yes"))
    time_no = to_float(row.get("time_factor_no"))
    spread_yes = to_float(row.get("spread"))
    spread_no = to_float(row.get("spread_no"))
    if spread_yes is None and ask_yes is not None and bid_yes is not None and math.isfinite(ask_yes) and math.isfinite(bid_yes):
        spread_yes = max(float(ask_yes) - float(bid_yes), 0.0)
        row["spread"] = spread_yes
    if spread_no is None and ask_no is not None and bid_no is not None and math.isfinite(ask_no) and math.isfinite(bid_no):
        spread_no = max(float(ask_no) - float(bid_no), 0.0)
        row["spread_no"] = spread_no
    pen_yes = _edge_score_penalty(spread_yes, ask_yes) if ask_yes is not None else 0.0
    pen_no = _edge_score_penalty(spread_no, ask_no) if ask_no is not None else 0.0
    row["penalty_yes"] = pen_yes
    row["penalty_no"] = pen_no
    if q_round is not None and ask_yes is not None and time_yes is not None and structure is not None:
        edge_points = max(q_round - ask_yes, 0.0) * 100.0
        time_structure = max(time_yes * structure, time_structure_min)
        row["edge_score_yes"] = edge_points * time_structure - pen_yes
    if q_round_no is not None and ask_no is not None and time_no is not None and structure is not None:
        edge_points = max(q_round_no - ask_no, 0.0) * 100.0
        time_structure = max(time_no * structure, time_structure_min)
        row["edge_score_no"] = edge_points * time_structure - pen_no
    # Backward-compatible fill for legacy facts missing executable-edge fields.
    # Do not overwrite existing values produced by the scanner's full microstructure path.
    def _env_cost(name: str, default: float) -> float:
        try:
            v = float(os.environ.get(name, str(default)))
        except (TypeError, ValueError):
            v = default
        if not math.isfinite(v):
            v = default
        if v < 0:
            v = 0.0
        if v > 1:
            v = v / 100.0
        return v
    exec_spread_weight = _env_cost("PM_EXEC_EDGE_SPREAD_WEIGHT", 0.25)
    exec_depth_penalty_weight = _env_cost("PM_EXEC_EDGE_DEPTH_PENALTY_WEIGHT", 1.0)
    exec_cancel_cost = _env_cost("PM_EXEC_EDGE_CANCEL_COST", 0.002)
    exec_retry_cost = _env_cost("PM_EXEC_EDGE_RETRY_COST", 0.001)
    exec_base_cost = exec_cancel_cost + exec_retry_cost

    def _shortfall_ratio(depth_total: Optional[float], target_size: Optional[float]) -> float:
        if (
            target_size is None
            or not math.isfinite(target_size)
            or target_size <= 0
        ):
            return 0.0
        if depth_total is None or not math.isfinite(depth_total):
            return 1.0
        if depth_total >= target_size:
            return 0.0
        return min(1.0, max(0.0, (target_size - depth_total) / target_size))

    def _compute_exec_for_side(
        side: str,
        ask: Optional[float],
        spread: Optional[float],
        q_entry_side: Optional[float],
        time_side: Optional[float],
        penalty_side: float,
    ) -> None:
        suffix = "_yes" if side == "YES" else "_no"
        existing_score = to_float(row.get(f"exec_edge_score{suffix}"))
        existing_entry = to_float(row.get(f"exec_edge_entry{suffix}"))
        existing_exit = to_float(row.get(f"exec_edge_exit{suffix}"))
        existing_realizable = to_float(row.get(f"edge_realizable{suffix}"))
        existing_realizable_score = to_float(row.get(f"edge_realizable_score{suffix}"))
        existing_fee_cost = to_float(row.get(f"exec_fee_cost{suffix}"))
        existing_entry_price = to_float(row.get(f"exec_entry_price{suffix}"))
        existing_entry_cost = to_float(row.get(f"exec_entry_cost{suffix}"))
        has_exec = (
            existing_score is not None and math.isfinite(existing_score)
            and existing_entry is not None and math.isfinite(existing_entry)
            and existing_exit is not None and math.isfinite(existing_exit)
        )
        has_realizable = (
            existing_realizable is not None and math.isfinite(existing_realizable)
            and existing_realizable_score is not None and math.isfinite(existing_realizable_score)
            and existing_fee_cost is not None and math.isfinite(existing_fee_cost)
        )
        has_entry_cost = (
            existing_entry_price is not None and math.isfinite(existing_entry_price)
            and existing_entry_cost is not None and math.isfinite(existing_entry_cost)
        )
        if has_exec and has_realizable and has_entry_cost:
            return
        if q_entry_side is None or not math.isfinite(q_entry_side):
            return
        if time_side is None or not math.isfinite(time_side):
            return
        if structure is None or not math.isfinite(structure):
            return

        entry_price = to_float(row.get(f"entry_price{suffix}"))
        exec_entry_price = to_float(row.get(f"exec_entry_price{suffix}"))
        if exec_entry_price is None:
            mode = str(os.environ.get("PM_EXEC_EDGE_ENTRY_PRICE_MODE", "auto") or "auto").strip().lower()
            if mode == "auto":
                ot = str(os.environ.get("PM_AUTO_TRADE_ORDER_TYPE", "GTC") or "GTC").strip().upper()
                mode = "book_vwap" if ot in {"FAK", "FOK"} else "best_ask"
            if mode not in {"best_ask", "book_vwap", "mid"}:
                mode = "best_ask"
            if mode == "best_ask":
                exec_entry_price = ask
            elif mode == "mid":
                mid_max_spread = _env_cost("PM_EXEC_EDGE_ENTRY_MID_MAX_SPREAD", 0.06)
                best_bid_key0 = "best_bid" if side == "YES" else f"best_bid{suffix}"
                best_bid0 = to_float(row.get(best_bid_key0))
                spr0 = to_float(spread)
                if spr0 is None and ask is not None and best_bid0 is not None:
                    spr0 = float(ask) - float(best_bid0)
                if (
                    ask is not None
                    and best_bid0 is not None
                    and math.isfinite(ask)
                    and math.isfinite(best_bid0)
                    and spr0 is not None
                    and math.isfinite(spr0)
                    and spr0 <= mid_max_spread + 1e-9
                ):
                    exec_entry_price = (float(ask) + float(best_bid0)) / 2.0
                else:
                    exec_entry_price = ask
            else:
                exec_entry_price = entry_price if entry_price is not None else ask
        if exec_entry_price is None or not math.isfinite(exec_entry_price):
            return
        entry_size = to_float(row.get(f"entry_size{suffix}"))
        ask_depth_total_key = "ask_depth_total" if side == "YES" else f"ask_depth_total{suffix}"
        ask_depth_topn_key = "ask_depth_topN" if side == "YES" else f"ask_depth_topN{suffix}"
        ask_depth_total = to_float(row.get(ask_depth_total_key))
        ask_depth_topn = to_float(row.get(ask_depth_topn_key))
        depth_total = ask_depth_total if ask_depth_total is not None else ask_depth_topn
        shortfall = _shortfall_ratio(depth_total, entry_size)
        slippage = 0.0
        if ask is not None and math.isfinite(ask):
            slippage = max(exec_entry_price - ask, 0.0)
        spread_cost = max(spread, 0.0) * exec_spread_weight if spread is not None and math.isfinite(spread) else 0.0
        depth_cost = max(spread, 0.0) * shortfall * exec_depth_penalty_weight if spread is not None and math.isfinite(spread) else 0.0
        exec_entry_cost = to_float(row.get(f"exec_entry_cost{suffix}"))
        if exec_entry_cost is None or not math.isfinite(exec_entry_cost):
            exec_entry_cost = slippage + spread_cost + depth_cost + exec_base_cost
        exec_edge_entry = q_entry_side - exec_entry_price - exec_entry_cost

        best_bid_key = "best_bid" if side == "YES" else f"best_bid{suffix}"
        best_bid = to_float(row.get(best_bid_key))
        exec_exit_price = to_float(row.get(f"exec_exit_price{suffix}"))
        if exec_exit_price is None:
            if best_bid is not None and math.isfinite(best_bid):
                exec_exit_price = best_bid
            else:
                exec_exit_price = ask
        if exec_exit_price is None or not math.isfinite(exec_exit_price):
            return
        bid_depth_topn_key = "bid_depth_topN" if side == "YES" else f"bid_depth_topN{suffix}"
        bid_depth_topn = to_float(row.get(bid_depth_topn_key))
        exit_fill = 1.0
        if entry_size is not None and math.isfinite(entry_size) and entry_size > 0:
            if bid_depth_topn is None or not math.isfinite(bid_depth_topn):
                exit_fill = 1.0 if (best_bid is not None and math.isfinite(best_bid)) else 0.0
            else:
                exit_fill = min(1.0, max(0.0, bid_depth_topn / entry_size))
        exit_spread_cost = max(spread, 0.0) * exec_spread_weight if spread is not None and math.isfinite(spread) else 0.0
        exit_fill_penalty = max(spread, 0.0) * max(0.0, 1.0 - exit_fill) * exec_depth_penalty_weight if spread is not None and math.isfinite(spread) else 0.0
        exec_exit_cost = to_float(row.get(f"exec_exit_cost{suffix}"))
        if exec_exit_cost is None or not math.isfinite(exec_exit_cost):
            exec_exit_cost = exit_spread_cost + exit_fill_penalty + exec_base_cost
        exec_edge_exit = q_entry_side - exec_exit_price - exec_exit_cost
        time_structure = max(time_side * structure, time_structure_min)
        exec_edge_score = max(exec_edge_entry, 0.0) * 100.0 * time_structure - penalty_side
        realizable_edge, fee_cost_val = edge_realizable(exec_edge_entry, exec_entry_price, exec_fee_bps)
        realizable_score = edge_realizable_score(realizable_edge, time_structure, penalty_side)

        if existing_entry is None or not math.isfinite(existing_entry):
            row[f"exec_edge_entry{suffix}"] = exec_edge_entry
        if existing_exit is None or not math.isfinite(existing_exit):
            row[f"exec_edge_exit{suffix}"] = exec_edge_exit
        if existing_score is None or not math.isfinite(existing_score):
            row[f"exec_edge_score{suffix}"] = exec_edge_score
        if row.get(f"edge_realizable{suffix}") is None and realizable_edge is not None and math.isfinite(realizable_edge):
            row[f"edge_realizable{suffix}"] = realizable_edge
        if row.get(f"edge_realizable_score{suffix}") is None and realizable_score is not None and math.isfinite(realizable_score):
            row[f"edge_realizable_score{suffix}"] = realizable_score
        if row.get(f"exec_fee_cost{suffix}") is None and fee_cost_val is not None and math.isfinite(fee_cost_val):
            row[f"exec_fee_cost{suffix}"] = fee_cost_val
        if row.get("exec_fee_bps") is None and exec_fee_bps is not None and math.isfinite(exec_fee_bps):
            row["exec_fee_bps"] = exec_fee_bps
        if row.get(f"exec_entry_price{suffix}") is None:
            row[f"exec_entry_price{suffix}"] = exec_entry_price
        if row.get(f"exec_entry_cost{suffix}") is None:
            row[f"exec_entry_cost{suffix}"] = exec_entry_cost
        if row.get(f"exec_exit_price{suffix}") is None:
            row[f"exec_exit_price{suffix}"] = exec_exit_price
        if row.get(f"exec_exit_cost{suffix}") is None:
            row[f"exec_exit_cost{suffix}"] = exec_exit_cost

    _compute_exec_for_side("YES", ask_yes, spread_yes, q_entry, time_yes, pen_yes)
    _compute_exec_for_side("NO", ask_no, spread_no, q_entry_no, time_no, pen_no)


def _compose_fact_from_snapshots(
    conn: sqlite3.Connection,
    run_date: str,
    slug: str,
    event_date: str,
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]],
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]],
    auto_orders_map: Dict[str, sqlite3.Row],
    market_tick_latest_map: Optional[Dict[Tuple[str, str], str]] = None,
    platt: Optional[Dict[str, Any]] = None,
) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], str]]:
    payload_model, meta_model, created_model, model_id = _load_latest_snapshot(conn, "model_snapshots", slug, event_date)
    payload_market, meta_market, created_market, market_id = _load_latest_snapshot(conn, "market_snapshots", slug, event_date)
    if payload_model is None or payload_market is None:
        return None
    time_structure_min = 0.1
    try:
        time_structure_min = float(os.environ.get("PM_TIME_STRUCTURE_MIN", "0.1"))
    except (TypeError, ValueError):
        time_structure_min = 0.1
    if not math.isfinite(time_structure_min) or time_structure_min <= 0:
        time_structure_min = 0.1
    market_map: Dict[str, Dict[str, Any]] = {}
    for row in payload_market.get("rows") or []:
        if not isinstance(row, dict):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        market_map[outcome] = row
    merged_rows: List[Dict[str, Any]] = []
    for row in payload_model.get("rows") or []:
        if not isinstance(row, dict):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        merged = dict(row)
        mrow = market_map.get(outcome)
        if isinstance(mrow, dict):
            for key in (
                "best_bid",
                "best_ask",
                "spread",
                "bid_depth_topN",
                "ask_depth_topN",
                "best_bid_no",
                "best_ask_no",
                "spread_no",
                "bid_depth_topN_no",
                "ask_depth_topN_no",
            ):
                if mrow.get(key) is not None:
                    merged[key] = mrow.get(key)
        _compute_edge_fields_in_place(merged, time_structure_min)
        merged_rows.append(merged)
    if not merged_rows:
        return None
    merged_payload = dict(payload_model)
    merged_payload["rows"] = merged_rows
    merged_payload["market_updated_at"] = created_market or merged_payload.get("market_updated_at") or ""
    top_label_fallback = ""
    try:
        top_label_fallback, _top_q = top_bucket_from_distribution(merged_rows, "q_round")
    except Exception:
        top_label_fallback = ""
    meta = dict(meta_model or {})
    for source in (meta_market or {},):
        if isinstance(source, dict):
            for key, value in source.items():
                if key not in meta or meta.get(key) in (None, ""):
                    meta[key] = value
    created_candidates = [created_model, created_market]
    as_of = ""
    best_dt = None
    for ts in created_candidates:
        dt = parse_iso_ts(str(ts or ""))
        if dt is None:
            continue
        if best_dt is None or dt > best_dt:
            best_dt = dt
            as_of = str(ts or "")
    if not as_of:
        as_of = utc_now_iso()
    event_row: Dict[str, Any] = {
        "slug": slug,
        "event_url": meta.get("event_url") or merged_payload.get("event_url") or "",
        "title": meta.get("title") or merged_payload.get("title") or "",
        "city": meta.get("city") or "",
        "lat": meta.get("lat"),
        "lon": meta.get("lon"),
        "tz": meta.get("tz") or merged_payload.get("tz") or "UTC",
        "location_basis": meta.get("location_basis") or "",
        "resolution_source": meta.get("resolution_source") or merged_payload.get("resolution_source") or "",
        "station_id": meta.get("station_id") or "",
        "rounding_rule": meta.get("rounding_rule") or merged_payload.get("rounding_rule") or "",
        "market_var": meta.get("market_var") or merged_payload.get("market_var") or "",
        "market_unit": meta.get("market_unit") or merged_payload.get("market_unit") or "",
        "market_open_at": meta.get("market_open_at"),
        "event_date": _normalize_date_key(event_date),
        "run_date": _normalize_date_key(run_date),
        "suggestions_json": None,
        "settlement_actual": None,
        "city_most_likely_label": meta.get("city_most_likely_label") or merged_payload.get("city_most_likely_label") or "",
        "city_most_likely_q": meta.get("city_most_likely_q") or merged_payload.get("city_most_likely_q"),
        "event_peak_time_utc": meta.get("event_peak_time_utc") or "",
        "event_end_utc": meta.get("event_end_utc") or "",
        "market_closed": 1 if meta.get("market_closed") else 0,
        "corrected_top_bucket_equal": top_label_fallback or "",
        "corrected_top_bucket_auto": "",
        "corrected_top_bucket_scenario": "",
        "corrected_top_consistency_equal": "",
        "corrected_top_consistency_auto": "",
        "corrected_top_consistency_scenario": "",
        "created_at": as_of,
        "payload_json": json.dumps(merged_payload, ensure_ascii=False),
    }
    try:
        diag = merged_payload.get("bucket_diag") or merged_payload.get("bucket_diagnostics") or {}
        if isinstance(diag, dict):
            corrected = diag.get("corrected_top3")
            if isinstance(corrected, dict):
                for wk, col in (
                    ("equal", "corrected_top_bucket_equal"),
                    ("auto", "corrected_top_bucket_auto"),
                    ("scenario", "corrected_top_bucket_scenario"),
                ):
                    series = corrected.get(wk)
                    if isinstance(series, list) and series and isinstance(series[0], dict):
                        label = str(series[0].get("label") or "")
                        if label:
                            event_row[col] = label
    except Exception:
        pass
    item = build_run_item(
        conn,
        event_row,
        trade_map,
        fills_map,
        auto_orders_map,
        market_tick_latest_map,
        platt=platt,
    )
    run_payload = {
        "score_composer": {
            "model_snapshot_id": model_id,
            "market_snapshot_id": market_id,
            "model_snapshot_at": created_model,
            "market_snapshot_at": created_market,
            "source": "snapshots",
        }
    }
    if isinstance(item.get("fact_provenance"), dict):
        item["fact_provenance"].update(run_payload["score_composer"])
    else:
        item["fact_provenance"] = run_payload["score_composer"]
    return item, run_payload, as_of


def _materialize_facts_from_snapshots_for_run_date(conn: sqlite3.Connection, run_date: str) -> int:
    rows = _snapshot_key_rows_for_run_date(conn, run_date)
    if not rows:
        return 0
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest(conn)
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    created = 0
    for slug, event_date, run_date_val in sorted(rows):
        composed = _compose_fact_from_snapshots(
            conn,
            run_date_val,
            slug,
            event_date,
            trade_map,
            fills_map,
            auto_orders_map,
            market_tick_latest_map,
            platt=platt,
        )
        if not composed:
            continue
        item, run_payload, as_of = composed
        fact_id = upsert_event_fact_from_run_item(
            conn,
            run_date=run_date,
            slug=slug,
            event_date=event_date,
            run_created_at=as_of,
            run_payload=run_payload,
            item=item,
        )
        if fact_id:
            created += 1
    if created:
        try:
            conn.commit()
        except sqlite3.Error:
            pass
    return created


