def _facts_exist_for_run_date(conn: sqlite3.Connection, run_date: str) -> bool:
    run_key = _normalize_date_key(run_date)
    if not run_key:
        return False
    cur = conn.cursor()
    cur.execute("SELECT 1 FROM event_fact_history WHERE run_date = ? LIMIT 1", (run_key,))
    return cur.fetchone() is not None


def _facts_exist_for_run_date_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> bool:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return False
    cur = conn.cursor()
    cur.execute(
        "SELECT 1 FROM event_fact_history WHERE run_date >= ? AND run_date <= ? LIMIT 1",
        (start_key, end_key),
    )
    return cur.fetchone() is not None


def _backfill_facts_from_event_run_rows(conn: sqlite3.Connection, rows: List[sqlite3.Row]) -> None:
    if not rows:
        return
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest(conn)
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    for row in rows:
        item = build_run_item(
            conn,
            row,
            trade_map,
            fills_map,
            auto_orders_map,
            market_tick_latest_map,
            platt=platt,
        )
        run_payload = safe_json_loads(row["payload_json"])
        upsert_event_fact_from_run_item(
            conn,
            run_date=str(row["run_date"] or ""),
            slug=str(row["slug"] or ""),
            event_date=str(row["event_date"] or ""),
            run_created_at=str(row["created_at"] or ""),
            run_payload=run_payload,
            item=item,
        )


def _backfill_facts_if_needed(
    conn: sqlite3.Connection,
    date_key: str,
    include_history: bool,
    start_date_key: str = "",
) -> None:
    if not DB_PATH.exists():
        return
    date_key = _normalize_date_key(date_key)
    start_date_key = _normalize_date_key(start_date_key)
    if include_history and start_date_key and not _facts_exist_for_run_date_range(conn, start_date_key, date_key):
        _materialize_facts_from_snapshots_for_range(conn, start_date_key, date_key)
        if _facts_exist_for_run_date_range(conn, start_date_key, date_key):
            return
        rows = select_event_run_rows_range(conn, start_date_key, date_key)
        if rows:
            seen: set[Tuple[str, str]] = set()
            selected: List[sqlite3.Row] = []
            for row in rows:
                slug = str(row["slug"] or "")
                event_date_key = _normalize_date_key(str(row["event_date"] or ""))
                if not slug or not event_date_key:
                    continue
                key = (slug, event_date_key)
                if key in seen:
                    continue
                seen.add(key)
                selected.append(row)
            _backfill_facts_from_event_run_rows(conn, selected)
            try:
                conn.commit()
            except sqlite3.Error:
                pass
        return
    if not include_history and _facts_exist_for_run_date(conn, date_key):
        return
    if not _facts_exist_for_run_date(conn, date_key):
        _materialize_facts_from_snapshots_for_run_date(conn, date_key)
        if _facts_exist_for_run_date(conn, date_key):
            return
    if include_history:
        rows = select_event_run_rows(conn, date_key, include_history=True)
    else:
        rows = select_event_run_rows(conn, date_key, include_history=False)
    if not rows:
        return
    _backfill_facts_from_event_run_rows(conn, rows)
    try:
        conn.commit()
    except sqlite3.Error:
        pass


def select_event_fact_rows(conn: sqlite3.Connection, date_key: str, include_history: bool) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    cur = conn.cursor()
    if include_history:
        cur.execute(
            """
            SELECT *
            FROM event_fact_history
            WHERE run_date <= ?
            ORDER BY run_date DESC, fact_as_of DESC, id DESC
            """,
            (date_key,),
        )
    else:
        cur.execute(
            """
            SELECT *
            FROM event_fact_history
            WHERE run_date = ?
            ORDER BY fact_as_of DESC, id DESC
            """,
            (date_key,),
        )
    rows = cur.fetchall()
    if not rows:
        return []
    if not include_history:
        seen: set[Tuple[str, str]] = set()
        out: List[sqlite3.Row] = []
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            out.append(row)
        return out
    best_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    fallback_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date_key = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date_key:
            continue
        key = (slug, event_date_key)
        run_date = _normalize_date_key(str(row["run_date"] or ""))
        fact_as_of = str(row["fact_as_of"] or "")
        prev_fallback = fallback_rows.get(key)
        if not prev_fallback or (run_date, fact_as_of) > (
            _normalize_date_key(str(prev_fallback["run_date"] or "")),
            str(prev_fallback["fact_as_of"] or ""),
        ):
            fallback_rows[key] = row
        cutoff = date_key
        if date_key and event_date_key and event_date_key < date_key:
            cutoff = event_date_key
        if cutoff and run_date and run_date > cutoff:
            continue
        prev_best = best_rows.get(key)
        if not prev_best or (run_date, fact_as_of) > (
            _normalize_date_key(str(prev_best["run_date"] or "")),
            str(prev_best["fact_as_of"] or ""),
        ):
            best_rows[key] = row
    out: List[sqlite3.Row] = []
    for key, fallback in fallback_rows.items():
        out.append(best_rows.get(key) or fallback)
    return out


def select_event_fact_rows_latest(conn: sqlite3.Connection, date_key: str) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    id, slug, event_date, run_date, fact_as_of, fact_json,
                    ROW_NUMBER() OVER (
                        PARTITION BY slug, event_date
                        ORDER BY fact_as_of DESC, id DESC
                    ) AS rn
                FROM event_fact_history
                WHERE run_date = ?
            )
            SELECT id, slug, event_date, run_date, fact_as_of, fact_json
            FROM ranked
            WHERE rn = 1
            ORDER BY fact_as_of DESC, id DESC
            """,
            (date_key,),
        )
    except sqlite3.OperationalError:
        return []
    rows = cur.fetchall()
    return rows or []


def select_event_fact_rows_paged(
    conn: sqlite3.Connection,
    date_key: str,
    page: int,
    page_size: int,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    page = max(1, int(page or 1))
    page_size = max(1, min(int(page_size or 1), 200))
    offset = (page - 1) * page_size
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE h.run_date = ?
            ORDER BY h.fact_as_of DESC, h.id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, page_size, offset),
        )
        rows = cur.fetchall()
        if rows:
            return rows
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    id, slug, event_date, run_date, fact_as_of, fact_json,
                    ROW_NUMBER() OVER (
                        PARTITION BY slug, event_date
                        ORDER BY fact_as_of DESC, id DESC
                    ) AS rn
                FROM event_fact_history
                WHERE run_date = ?
            )
            SELECT id, slug, event_date, run_date, fact_as_of, fact_json
            FROM ranked
            WHERE rn = 1
            ORDER BY fact_as_of DESC, id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, page_size, offset),
        )
        return cur.fetchall()
    except sqlite3.OperationalError:
        # Fallback for older SQLite builds without window functions.
        rows = select_event_fact_rows(conn, date_key, include_history=False)
        if not rows:
            return []
        return rows[offset : offset + page_size]


def count_event_fact_rows(conn: sqlite3.Connection, date_key: str) -> int:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return 0
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT COUNT(*)
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE h.run_date = ?
            """,
            (date_key,),
        )
        row = cur.fetchone()
        if row:
            return int(row[0] or 0)
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            SELECT COUNT(*)
            FROM (
                SELECT 1
                FROM event_fact_history
                WHERE run_date = ?
                GROUP BY slug, event_date
            ) AS t
            """,
            (date_key,),
        )
        row = cur.fetchone()
        return int(row[0] or 0) if row else 0
    except sqlite3.OperationalError:
        rows = select_event_fact_rows(conn, date_key, include_history=False)
        return len(rows)


def select_event_fact_rows_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[sqlite3.Row]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    cur.execute(
        """
        SELECT *
        FROM event_fact_history
        WHERE run_date >= ? AND run_date <= ?
        ORDER BY run_date DESC, fact_as_of DESC, id DESC
        """,
        (start_key, end_key),
    )
    return cur.fetchall()


def query_runs_paged(
    date: str,
    include_history: bool,
    page: int,
    page_size: int,
) -> Dict[str, Any]:
    if page < 1:
        page = 1
    page_size = max(1, min(page_size, 200))
    if include_history:
        data = query_runs(date, include_history)
        total = len(data)
        start = (page - 1) * page_size
        end = start + page_size
        items = data[start:end] if start < total else []
        return {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
    if not DB_PATH.exists():
        return {
            "items": [],
            "page": page,
            "page_size": page_size,
            "has_more": False,
            "total": None,
        }
    with open_db() as conn:
        if not date:
            date = latest_unsettled_run_date(conn) or latest_run_date(conn)
        if date and "T" in date:
            date = date.split("T", 1)[0]
        cur = conn.cursor()
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date = ? ORDER BY created_at DESC",
            (date,),
        )
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        market_tick_latest_map = query_market_tick_latest(conn)
        seen: set[Tuple[str, str]] = set()
        out: List[Dict[str, Any]] = []
        skipped = 0
        has_more = False
        offset = (page - 1) * page_size
        for row in cur:
            event_date_key = str(row["event_date"] or "")
            if "T" in event_date_key:
                event_date_key = event_date_key.split("T", 1)[0]
            key = (str(row["slug"] or ""), event_date_key)
            if key in seen:
                continue
            seen.add(key)
            if skipped < offset:
                skipped += 1
                continue
            out.append(build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map))
            if len(out) >= page_size:
                for row_next in cur:
                    event_date_next = str(row_next["event_date"] or "")
                    if "T" in event_date_next:
                        event_date_next = event_date_next.split("T", 1)[0]
                    next_key = (str(row_next["slug"] or ""), event_date_next)
                    if next_key in seen:
                        continue
                    has_more = True
                    break
                break
        return {
            "items": out,
            "page": page,
            "page_size": page_size,
            "has_more": has_more,
            "total": None,
        }


def query_runs_range(days: int, end_date: str) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    with open_db() as conn:
        if not end_date:
            end_date = latest_unsettled_run_date(conn) or latest_run_date(conn)
        if not end_date:
            return []
        if "T" in end_date:
            end_date = end_date.split("T", 1)[0]
        try:
            end_dt = datetime.fromisoformat(end_date).date()
        except ValueError:
            return []
        if days <= 0:
            start_dt = end_dt
        else:
            start_dt = end_dt - timedelta(days=max(0, days - 1))
        start_date = start_dt.isoformat()
        cur = conn.cursor()
        cur.execute(
            """
            SELECT * FROM event_runs
            WHERE run_date >= ? AND run_date <= ?
            ORDER BY run_date DESC, created_at DESC
            """,
            (start_date, end_date),
        )
        rows = cur.fetchall()
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        market_tick_latest_map = query_market_tick_latest(conn)
        out: List[Dict[str, Any]] = []
        seen: set[Tuple[str, str]] = set()
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = str(row["event_date"] or "")
            if "T" in event_date_key:
                event_date_key = event_date_key.split("T", 1)[0]
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            out.append(build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map))
        return out


def _hydrate_fact_market_updated_at(payload: Any, market_tick_latest_map: Dict[Tuple[str, str], str]) -> None:
    if not isinstance(payload, dict):
        return
    slug = str(payload.get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or payload.get("date") or ""))
    if not slug or not event_date:
        return
    tick_updated_at = str(market_tick_latest_map.get((slug, event_date)) or "").strip()
    if not tick_updated_at:
        return
    prev = str(payload.get("market_updated_at") or "").strip()
    if (not prev) or tick_updated_at > prev:
        payload["market_updated_at"] = tick_updated_at
        payload["market_updated_source"] = "tick"


def _hydrate_fact_market_top_label(payload: Any) -> None:
    """
    Backward/forward compatibility:
    - Older fact_json may have market_top_label derived from best_ask, which is misleading in illiquid books.
    - Recompute from distribution at read time so UI always sees the SSOT definition.
    """
    if not isinstance(payload, dict):
        return
    dist = payload.get("distribution") or payload.get("rows") or []
    distribution = normalize_distribution_rows(dist if isinstance(dist, list) else [])
    if not distribution:
        return
    payload["market_top_label"] = market_top_label(distribution)


def query_facts(date: str, include_history: bool) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    db_cm = open_db if allow_backfill else open_db_ro_fast
    platt_days = None
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    with db_cm() as conn:
        if allow_backfill:
            ensure_fact_tables(conn)
        date_key = str(date or "").strip()
        if not date_key:
            date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        date_key = _normalize_date_key(date_key)
        if not date_key:
            return []
        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, date_key, include_history)
            except sqlite3.OperationalError:
                pass
        try:
            market_tick_latest_map = query_market_tick_latest(conn)
            fact_rows = select_event_fact_rows(conn, date_key, include_history)
        except sqlite3.OperationalError:
            return []
        out: List[Dict[str, Any]] = []
        for row in fact_rows:
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if isinstance(payload, dict):
                _slim_fact_payload_for_ui(payload)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_label(payload)
                try:
                    _ensure_fact_q_calibrated(payload, platt)
                except Exception:
                    pass
                try:
                    _set_fact_q_calibrated_na_reason(payload, platt)
                except Exception:
                    pass
                # SSOT: front-end should not recompute entry candidates/reasons from raw distribution.
                payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
                out.append(payload)
        return out


def query_facts_paged(
    date: str,
    include_history: bool,
    page: int,
    page_size: int,
) -> Dict[str, Any]:
    if page < 1:
        page = 1
    page_size = max(1, min(page_size, 200))
    if include_history:
        data = query_facts(date, include_history=True)
        total = len(data)
        start = (page - 1) * page_size
        end = start + page_size
        items = data[start:end] if start < total else []
        return {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
    if not DB_PATH.exists():
        return {
            "items": [],
            "page": page,
            "page_size": page_size,
            "has_more": False,
            "total": None,
        }
    date_key_cache = _normalize_date_key(str(date or "").strip())
    if not include_history and FACTS_PAGE_CACHE_SEC > 0 and date_key_cache:
        cache_key = f"{date_key_cache}|p={page}|s={page_size}|h=0"
        cached = _FACTS_PAGE_CACHE.get(cache_key)
        if cached:
            cached_at, payload = cached
            if (time.time() - cached_at) <= FACTS_PAGE_CACHE_SEC:
                return payload
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    platt_days = None
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    db_cm = open_db if allow_backfill else open_db_ro_fast
    with db_cm() as conn:
        if allow_backfill:
            ensure_fact_tables(conn)
        date_key = str(date or "").strip()
        if not date_key:
            date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        date_key = _normalize_date_key(date_key)
        if not date_key:
            return {
                "items": [],
                "page": page,
                "page_size": page_size,
                "has_more": False,
                "total": 0,
            }
        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, date_key, include_history=False)
            except sqlite3.OperationalError:
                pass
        try:
            total = count_event_fact_rows(conn, date_key)
            start = (page - 1) * page_size
            end = start + page_size
            page_rows = select_event_fact_rows_paged(conn, date_key, page, page_size)
            market_tick_latest_map = query_market_tick_latest_for_keys(
                conn,
                [(row["slug"], row["event_date"]) for row in page_rows],
            )
        except sqlite3.OperationalError:
            return {
                "items": [],
                "page": page,
                "page_size": page_size,
                "has_more": False,
                "total": 0,
            }
        items: List[Dict[str, Any]] = []
        for row in page_rows:
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if isinstance(payload, dict):
                _slim_fact_payload_for_ui(payload)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_label(payload)
                try:
                    _ensure_fact_q_calibrated(payload, platt)
                except Exception:
                    pass
                try:
                    _set_fact_q_calibrated_na_reason(payload, platt)
                except Exception:
                    pass
                payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
                items.append(payload)
        payload = {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
        if not include_history and FACTS_PAGE_CACHE_SEC > 0:
            cache_key = f"{date_key}|p={page}|s={page_size}|h=0"
            _FACTS_PAGE_CACHE[cache_key] = (time.time(), payload)
        return payload


