def market_refresh_meta() -> Dict[str, Any]:
    meta = {
        "last_start": "",
        "log_mtime": "",
        "events_fetched": None,
        "events_planned": None,
        "events_seen": 0,
        "last_exit_code": None,
        "last_timeout": False,
        "stage": 0,
        "stage_text": "",
    }
    if not MARKET_REFRESH_LOG_PATH.exists():
        return meta
    try:
        mtime = MARKET_REFRESH_LOG_PATH.stat().st_mtime
        meta["log_mtime"] = datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S")
    except OSError:
        meta["log_mtime"] = ""
    lines = tail_log_lines(MARKET_REFRESH_LOG_PATH, 800)
    start_idx = None
    for idx in range(len(lines) - 1, -1, -1):
        line = lines[idx]
        match = re.search(r"----\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+market_refresh start", line)
        if match:
            meta["last_start"] = match.group(1)
            start_idx = idx
            break
    run_lines = lines[start_idx:] if start_idx is not None else lines
    for line in run_lines:
        if meta["events_fetched"] is None:
            fetched_match = re.search(r"Weather events fetched:\\s*(\\d+)", line)
            if fetched_match:
                try:
                    meta["events_fetched"] = int(fetched_match.group(1))
                except (TypeError, ValueError):
                    meta["events_fetched"] = None
        if meta["events_planned"] is None:
            planned_match = re.search(r"max_events_per_run=(\\d+)", line)
            if planned_match:
                try:
                    meta["events_planned"] = int(planned_match.group(1))
                except (TypeError, ValueError):
                    meta["events_planned"] = None
        exit_match = re.search(r"\[market_refresh\]\s+scan exit=(-?\d+)", line)
        if exit_match:
            try:
                meta["last_exit_code"] = int(exit_match.group(1))
            except (TypeError, ValueError):
                meta["last_exit_code"] = None
        if "[timeout] kill pid=" in line:
            meta["last_timeout"] = True
    meta["events_seen"] = sum(1 for line in run_lines if line.lstrip().startswith("- "))
    stage_idx, stage_text = _detect_scan_stage(run_lines)
    meta["stage"] = int(stage_idx)
    meta["stage_text"] = stage_text
    return meta


def pid_command(pid: int) -> str:
    try:
        output = subprocess.check_output(
            ["ps", "-p", str(pid), "-o", "command="],
            text=True,
        )
    except (OSError, subprocess.CalledProcessError):
        return ""
    return output.strip()


def pid_running(pid: int) -> bool:
    if pid <= 0:
        return False
    if not SCAN_PID_PATH.exists():
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    command = pid_command(pid)
    if command and "scan_weather_market.py" not in command:
        return False
    return True


def load_scan_state() -> Dict[str, Any]:
    default_state = {"running": False, "started_at": "", "ended_at": "", "exit_code": None, "pid": None}
    if not SCAN_STATE_PATH.exists():
        return dict(default_state)
    try:
        stat = SCAN_STATE_PATH.stat()
    except OSError:
        return dict(default_state)
    mtime_ns = int(getattr(stat, "st_mtime_ns", 0) or 0)
    now_mono = time.monotonic()
    with _SCAN_STATE_CACHE_LOCK:
        cached = _SCAN_STATE_CACHE.get("data")
        cached_mtime_ns = _SCAN_STATE_CACHE.get("mtime_ns")
        cached_ts = float(_SCAN_STATE_CACHE.get("ts") or 0.0)
        if (
            isinstance(cached, dict)
            and cached_mtime_ns == mtime_ns
            and SCAN_STATE_CACHE_SEC > 0
            and (now_mono - cached_ts) <= SCAN_STATE_CACHE_SEC
        ):
            return dict(cached)
    try:
        data = json.loads(SCAN_STATE_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return dict(default_state)
    if not isinstance(data, dict):
        return dict(default_state)
    with _SCAN_STATE_CACHE_LOCK:
        _SCAN_STATE_CACHE["data"] = dict(data)
        _SCAN_STATE_CACHE["mtime_ns"] = mtime_ns
        _SCAN_STATE_CACHE["ts"] = now_mono
    return dict(data)


def write_scan_state(state: Dict[str, Any]) -> None:
    if not isinstance(state, dict):
        return
    try:
        payload = json.dumps(state, ensure_ascii=True)
    except Exception:
        return
    with _SCAN_STATE_CACHE_LOCK:
        cached = _SCAN_STATE_CACHE.get("data")
        if isinstance(cached, dict) and cached == state:
            _SCAN_STATE_CACHE["ts"] = time.monotonic()
            return
    try:
        SCAN_STATE_PATH.write_text(payload, encoding="utf-8")
        try:
            mtime_ns = int(getattr(SCAN_STATE_PATH.stat(), "st_mtime_ns", 0) or 0)
        except OSError:
            mtime_ns = None
        with _SCAN_STATE_CACHE_LOCK:
            _SCAN_STATE_CACHE["data"] = dict(state)
            _SCAN_STATE_CACHE["mtime_ns"] = mtime_ns
            _SCAN_STATE_CACHE["ts"] = time.monotonic()
    except OSError:
        # Under temporary FD pressure, keep in-memory state to avoid crashing request path.
        with _SCAN_STATE_CACHE_LOCK:
            _SCAN_STATE_CACHE["data"] = dict(state)
            _SCAN_STATE_CACHE["ts"] = time.monotonic()


def load_scan_timing() -> Dict[str, Any]:
    if not SCAN_TIMING_PATH.exists():
        return {}
    try:
        stat = SCAN_TIMING_PATH.stat()
    except OSError:
        return {}
    mtime_ns = int(getattr(stat, "st_mtime_ns", 0) or 0)
    now_mono = time.monotonic()
    with _SCAN_TIMING_CACHE_LOCK:
        cached = _SCAN_TIMING_CACHE.get("data")
        cached_mtime_ns = _SCAN_TIMING_CACHE.get("mtime_ns")
        cached_ts = float(_SCAN_TIMING_CACHE.get("ts") or 0.0)
        if (
            isinstance(cached, dict)
            and cached_mtime_ns == mtime_ns
            and SCAN_TIMING_CACHE_SEC > 0
            and (now_mono - cached_ts) <= SCAN_TIMING_CACHE_SEC
        ):
            return dict(cached)
    try:
        data = json.loads(SCAN_TIMING_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {}
    if not isinstance(data, dict):
        return {}
    with _SCAN_TIMING_CACHE_LOCK:
        _SCAN_TIMING_CACHE["data"] = dict(data)
        _SCAN_TIMING_CACHE["mtime_ns"] = mtime_ns
        _SCAN_TIMING_CACHE["ts"] = now_mono
    return dict(data)


def normalize_scan_timing(data: Dict[str, Any]) -> Dict[str, Any]:
    if not data:
        return {}
    payload = dict(data)
    updated_raw = str(payload.get("updated_at") or "")
    dt = parse_iso_ts(updated_raw)
    if dt is not None:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        age_sec = max(0, int((datetime.now(timezone.utc) - dt).total_seconds()))
        payload["age_sec"] = age_sec
    return payload


def scan_status() -> Dict[str, Any]:
    with SCAN_LOCK:
        state = load_scan_state()
        state_before = dict(state)
        pid = state.get("pid")
        running = False
        if pid:
            running = pid_running(int(pid))
        if state.get("running") and not running:
            state["running"] = False
            if not state.get("ended_at"):
                state["ended_at"] = now_text()
        state["running"] = running
        if not running and SCAN_PID_PATH.exists():
            try:
                SCAN_PID_PATH.unlink()
            except OSError:
                pass
        meta_15m = model_scan_meta()
        if state != state_before:
            write_scan_state(state)
        timing = normalize_scan_timing(load_scan_timing())
        market_meta = market_refresh_meta()
        market_meta["running"] = market_refresh_running()
        return {
            "running": bool(state.get("running")),
            "started_at": state.get("started_at") or "",
            "ended_at": state.get("ended_at") or "",
            "exit_code": state.get("exit_code"),
            "scan_alerts_paused": bool(_scan_alerts_paused()),
            "model_scan_running": model_scan_running(),
            "model_scan_last_start": meta_15m.get("last_start") or "",
            "model_scan_log_mtime": meta_15m.get("log_mtime") or "",
            "model_scan_trade_sync_failed": bool(meta_15m.get("trade_sync_failed")),
            "model_scan_stage": int(meta_15m.get("stage") or 0),
            "model_scan_stage_text": meta_15m.get("stage_text") or "",
            "scan_15m_running": model_scan_running(),
            "scan_15m_last_start": meta_15m.get("last_start") or "",
            "scan_15m_log_mtime": meta_15m.get("log_mtime") or "",
            "scan_15m_trade_sync_failed": bool(meta_15m.get("trade_sync_failed")),
            "scan_timing": timing,
            "market_refresh": market_meta,
        }


def start_scan(force: bool, refresh_models: bool, mode: str) -> Dict[str, Any]:
    with SCAN_LOCK:
        diag = auto_trade_env_diagnostics()
        if diag.get("enabled") and (diag.get("dry_run") or diag.get("missing")):
            return {
                "started": False,
                "running": False,
                "message": "auto_trade_env_invalid",
                "detail": auto_trade_env_error_text(diag),
            }
        apply_auto_trade_config(load_auto_trade_config())
        state = load_scan_state()
        pid = state.get("pid")
        if pid and pid_running(int(pid)):
            if not force:
                state["running"] = True
                write_scan_state(state)
                return {"started": False, "running": True, "message": "scan already running"}
            try:
                os.kill(int(pid), 15)
            except OSError:
                pass
            state["running"] = False
            state["ended_at"] = now_text()
            state["exit_code"] = None
            state["pid"] = None
            write_scan_state(state)

        DATA_DIR.mkdir(parents=True, exist_ok=True)
        python = ROOT_DIR / ".venv" / "bin" / "python"
        py_cmd = str(python) if python.exists() else "python3"
        scan_mode = str(mode or "all").strip().lower()
        if scan_mode not in {"all", "model", "market"}:
            scan_mode = "all"
        cmd = [
            py_cmd,
            str(ROOT_DIR / "scan_weather_market.py"),
            "--scan-weather-today",
            "--tz",
            "America/New_York",
            "--days-ahead",
            "-1",
            "--no-update-models",
        ]
        if scan_mode == "market":
            cmd.append("--market-refresh-only")
            cmd.append("--no-auto-trade")
        elif scan_mode == "model":
            cmd.append("--model-refresh-only")
            cmd.append("--no-auto-trade")
        if force:
            cmd.append("--insecure")
        env = os.environ.copy()
        env.setdefault("PM_DISABLE_OPEN_METEO_GEOCODE", "1")
        env.setdefault("PM_SCAN_DB_LOCK_WAIT_SEC", "45")
        env.setdefault("PM_SCAN_FETCH_EVENT_DETAIL", "0")
        env.setdefault("PM_SCAN_GAMMA_TIMEOUT", "12")
        env.setdefault("PM_SCAN_GAMMA_RETRIES", "2")
        env.setdefault("PM_SCAN_GAMMA_BACKOFF", "0.6")
        env.setdefault("PM_SCAN_GAMMA_MAX_PAGES", "60")
        env.setdefault("PM_SCAN_OPEN_METEO_TIMEOUT_SEC", "10")
        env.setdefault("PM_SCAN_OPEN_METEO_RETRIES", "2")
        env.setdefault("PM_SCAN_OPEN_METEO_429_RETRIES", "2")
        env.setdefault("PM_DB_CONNECT_TIMEOUT_SEC", "5")
        env.setdefault("PM_DB_BUSY_TIMEOUT_MS", "5000")
        if scan_mode == "market":
            env.setdefault("PM_SCAN_MAX_EVENTS_PER_RUN", "2")
            max_events = env.get("PM_SCAN_MAX_EVENTS_PER_RUN", "2")
            env.setdefault("PM_SCAN_MAX_MATCHED_PER_RUN", max_events)
            env.setdefault("PM_MARKET_REFRESH_CACHE_ONLY", "1")
            env.setdefault("PM_MARKET_REFRESH_COMPOSE_SCORE", "0")
            env.setdefault("PM_SCAN_MARKET_REFRESH_MAX_OUTCOMES", "4")
            env.setdefault("PM_SCAN_MARKET_REFRESH_TIME_BUDGET_SEC", "6")
            env.setdefault("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_TIMEOUT_SEC", "2")
            env.setdefault("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_RETRIES", "1")
        elif scan_mode == "model":
            env.setdefault("PM_SCAN_MAX_EVENTS_PER_RUN", "6")
            max_events = env.get("PM_SCAN_MAX_EVENTS_PER_RUN", "6")
            env.setdefault("PM_SCAN_MAX_MATCHED_PER_RUN", max_events)
        if refresh_models or scan_mode == "model":
            env["PM_FORCE_MODEL_REFRESH"] = "1"
        log_file = open(SCAN_LOG_PATH, "a", encoding="utf-8")
        proc = subprocess.Popen(
            cmd,
            stdout=log_file,
            stderr=log_file,
            cwd=str(ROOT_DIR),
            env=env,
        )
        SCAN_PID_PATH.write_text(str(proc.pid), encoding="utf-8")
        state = {
            "running": True,
            "started_at": now_text(),
            "ended_at": "",
            "exit_code": None,
            "pid": proc.pid,
        }
        write_scan_state(state)

        def _watch() -> None:
            code = proc.wait()
            log_file.close()
            with SCAN_LOCK:
                state = load_scan_state()
                state["running"] = False
                state["ended_at"] = now_text()
                state["exit_code"] = code
                state["pid"] = None
                write_scan_state(state)
                try:
                    SCAN_PID_PATH.unlink()
                except OSError:
                    pass

        threading.Thread(target=_watch, daemon=True).start()
        return {"started": True, "running": True}


def _latest_event_run_meta(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> Optional[Dict[str, Any]]:
    cur = conn.cursor()
    cur.execute(
        """
        SELECT event_url, lat, lon, tz, title
        FROM event_runs
        WHERE slug = ? AND event_date = ?
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (slug, event_date),
    )
    row = cur.fetchone()
    if not row:
        return None
    return {
        "event_url": str(row["event_url"] or ""),
        "lat": row["lat"],
        "lon": row["lon"],
        "tz": str(row["tz"] or ""),
        "title": str(row["title"] or ""),
    }


def start_market_refresh(slug: str, event_date: str) -> Dict[str, Any]:
    if not slug or not event_date:
        return {"ok": False, "error": "missing_params"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    event_date = event_date.split("T", 1)[0]
    with MARKET_REFRESH_LOCK:
        pid = MARKET_REFRESH_STATE.get("pid")
        if pid and pid_running(int(pid)):
            return {"ok": False, "error": "refresh_running", "state": dict(MARKET_REFRESH_STATE)}
        MARKET_REFRESH_STATE.update(
            {
                "running": False,
                "started_at": "",
                "ended_at": "",
                "exit_code": None,
                "pid": None,
                "slug": "",
                "event_date": "",
                "error": "",
            }
        )
        with open_db() as conn:
            meta = _latest_event_run_meta(conn, slug, event_date)
        if not meta:
            return {"ok": False, "error": "event_not_found"}
        tz = meta.get("tz") or "UTC"
        event_url = meta.get("event_url") or f"https://polymarket.com/event/{slug}"
        python = ROOT_DIR / ".venv" / "bin" / "python"
        py_cmd = str(python) if python.exists() else "python3"
        cmd = [
            py_cmd,
            str(ROOT_DIR / "scan_weather_market.py"),
            "--event-url",
            event_url,
            "--date",
            event_date,
            "--tz",
            tz,
            "--market-refresh-only",
            "--no-update-models",
            "--no-auto-trade",
        ]
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        log_file = open(MARKET_REFRESH_LOG_PATH, "a", encoding="utf-8")
        log_file.write(f"\n[{now_text()}] refresh {slug} {event_date}\n")
        log_file.flush()
        proc = subprocess.Popen(
            cmd,
            stdout=log_file,
            stderr=log_file,
            cwd=str(ROOT_DIR),
            env=os.environ.copy(),
        )
        MARKET_REFRESH_STATE.update(
            {
                "running": True,
                "started_at": now_text(),
                "ended_at": "",
                "exit_code": None,
                "pid": proc.pid,
                "slug": slug,
                "event_date": event_date,
                "error": "",
            }
        )

    def _watch_refresh() -> None:
        code = proc.wait()
        log_file.close()
        with MARKET_REFRESH_LOCK:
            MARKET_REFRESH_STATE["running"] = False
            MARKET_REFRESH_STATE["ended_at"] = now_text()
            MARKET_REFRESH_STATE["exit_code"] = code
            MARKET_REFRESH_STATE["pid"] = None

    threading.Thread(target=_watch_refresh, daemon=True).start()
    return {"ok": True, "started": True, "slug": slug, "event_date": event_date}


def parse_iso_date(value: str) -> Optional[datetime]:
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


