        if path == "/api/most-likely-history":
            slug = params.get("slug", [""])[0]
            date = params.get("date", [""])[0]
            if date and "T" in date:
                date = date.split("T", 1)[0]
            weighting = params.get("weighting", ["equal"])[0]
            if not slug or not date:
                self._send_json({"ok": False, "items": [], "error": "missing_params"})
                return
            run_date = params.get("run_date", [""])[0]
            cache_key = (slug, date, weighting, run_date)
            now_ts = time.time()
            cached = _MOST_LIKELY_CACHE.get(cache_key)
            if cached and (now_ts - cached[0]) <= MOST_LIKELY_CACHE_SEC:
                self._send_json(cached[1])
                return
            if not _MOST_LIKELY_SEM.acquire(blocking=False):
                stale = _MOST_LIKELY_CACHE.get(cache_key)
                if stale and isinstance(stale[1], dict):
                    payload = dict(stale[1])
                    payload.setdefault("ok", True)
                    payload["stale_cached"] = True
                    payload["throttled"] = True
                    self._send_json(payload)
                    return
                self._send_json({"ok": False, "items": [], "error": "busy_throttle", "throttled": True})
                return
            try:
                data = query_most_likely_history(slug, date, weighting, run_date)
                if isinstance(data, dict):
                    _MOST_LIKELY_CACHE[cache_key] = (now_ts, data)
                self._send_json(data)
            finally:
                _MOST_LIKELY_SEM.release()
            return
        
        if path == "/api/settlement-actual":
            slug = params.get("slug", [""])[0]
            event_date = params.get("date", [""])[0]
            if event_date and "T" in event_date:
                event_date = event_date.split("T", 1)[0]
            if not slug or not event_date:
                self._send_json({"ok": False, "error": "missing_params"})
                return
            if not DB_PATH.exists():
                self._send_json({"ok": False, "error": "db_missing"})
                return
            with open_db() as conn:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT settlement_actual
                    FROM event_daily_temps
                    WHERE slug = ? AND event_date = ?
                    ORDER BY created_at DESC
                    LIMIT 1
                    """,
                    (slug, event_date),
                )
                row = cur.fetchone()
                if row and row["settlement_actual"] is not None:
                    self._send_json({"ok": True, "value": row["settlement_actual"]})
                    return
                # 迁移期兜底：若旧表存在结算值则回填到 event_daily_temps，确保后续读路径 SSOT
                try:
                    cur.execute(
                        """
                        SELECT settlement_actual, title, city, station_id, resolution_source, market_var, market_unit
                        FROM event_runs
                        WHERE slug = ? AND event_date = ?
                        ORDER BY created_at DESC
                        LIMIT 1
                        """,
                        (slug, event_date),
                    )
                    row = cur.fetchone()
                except sqlite3.OperationalError:
                    row = None
                if row and row["settlement_actual"] is not None:
                    value = row["settlement_actual"]
                    try:
                        run_date_val = latest_fact_run_date(conn) or latest_run_date(conn) or ""
                        cur.execute(
                            """
                            INSERT INTO event_daily_temps(
                                run_date, event_date, slug, title, city, station_id,
                                resolution_source, market_var, market_unit,
                                settlement_actual, created_at
                            )
                            VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                            """,
                            (
                                run_date_val,
                                event_date,
                                slug,
                                row["title"],
                                row["city"],
                                row["station_id"],
                                row["resolution_source"],
                                row["market_var"],
                                row["market_unit"],
                                value,
                                now_text(),
                            ),
                        )
                        conn.commit()
                    except sqlite3.Error:
                        pass
                    self._send_json({"ok": True, "value": value})
                    return
                self._send_json({"ok": False, "error": "not_available"})
                return

        if path == "/api/station-temp":
            station = params.get("station", [""])[0]
            event_date = params.get("event_date", [""])[0]
            if event_date and "T" in event_date:
                event_date = event_date.split("T", 1)[0]
            if not station:
                self._send_json({"ok": False, "error": "missing_station"})
                return
            if not DB_PATH.exists():
                self._send_json({"ok": False, "error": "db_missing"})
                return
            cache_key = (station, event_date)
            now_ts = time.time()
            cached = _STATION_TEMP_CACHE.get(cache_key)
            if cached and (now_ts - cached[0]) <= STATION_TEMP_CACHE_SEC:
                self._send_json(cached[1])
                return
            if not _STATION_TEMP_SEM.acquire(blocking=False):
                if cached and isinstance(cached[1], dict):
                    payload = dict(cached[1])
                    payload.setdefault("ok", True)
                    payload["stale_cached"] = True
                    payload["throttled"] = True
                    self._send_json(payload)
                    return
                self._send_json({"ok": False, "error": "busy_throttle", "throttled": True})
                return
            try:
                # Read-only endpoint: use fast RO connection to avoid blocking on writer PRAGMA/locks.
                with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                    cur = conn.cursor()
                    cur.execute(
                        """
                        SELECT forecast_max_f, forecast_max_c, forecast_time, forecast_date, source, created_at
                        FROM station_forecasts
                        WHERE station_id = ? AND (? = '' OR event_date = ?)
                        ORDER BY created_at DESC
                        LIMIT 1
                        """,
                        (station, event_date, event_date),
                    )
                    row = cur.fetchone()
                    if not row:
                        self._send_json({"ok": False, "error": "not_available"})
                        return
                    forecast_time = row["forecast_time"]
                    created_at = row["created_at"]
                    data_time = forecast_time or created_at
                    age_sec = None
                    is_recent = None
                    if data_time:
                        dt = parse_iso_ts(str(data_time))
                        if dt is not None:
                            if dt.tzinfo is None:
                                dt = dt.replace(tzinfo=timezone.utc)
                            age_sec = (datetime.now(timezone.utc) - dt).total_seconds()
                            if STATION_FORECAST_TTL_SEC > 0:
                                is_recent = age_sec <= STATION_FORECAST_TTL_SEC
                    payload = {
                        "ok": True,
                        "forecast_max_f": row["forecast_max_f"],
                        "forecast_max_c": row["forecast_max_c"],
                        "forecast_time": forecast_time,
                        "forecast_date": row["forecast_date"],
                        "source": row["source"],
                        "created_at": created_at,
                        "data_time": data_time,
                        "age_sec": age_sec,
                        "is_recent": is_recent,
                        "max_age_sec": STATION_FORECAST_TTL_SEC,
                    }
                    _STATION_TEMP_CACHE[cache_key] = (now_ts, payload)
                    self._send_json(payload)
                    return
            except sqlite3.OperationalError:
                if cached and isinstance(cached[1], dict):
                    payload = dict(cached[1])
                    payload.setdefault("ok", True)
                    payload["stale_cached"] = True
                    payload["db_busy"] = True
                    self._send_json(payload)
                    return
                self._send_json({"ok": False, "error": "db_busy", "db_busy": True})
                return
            finally:
                _STATION_TEMP_SEM.release()

